window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210115-10","meetingId":"r03-cm01","date":"2021年1月15日","dateIso":"2021-01-15","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","topics":[{"id":"topic-01","title":"議席の割り振りについておよび(3)常任・議運・特別委員会の構成等","agenda":"議席の割り振りについておよび(3)常任・議運・特別委員会の構成等","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"ただ、今回、いろいろそうすると、動く方がたくさん出てくると、またそれはそれで事務局も大変だと思いますので、今回はそれでいいのかと思いますが、今後、変わっていくのかどうか。私は今回のは、座席としては、議席としては少し違和感を感じます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"すみません、私の聞き違いだったら恐縮なのですが、今回、自・無が６名になったということは、今現在、共産が２名、議運に出ていますよね。自・無はそのまま３名という形で残るということですか。","respondent":"石田（秀）委員長","answer":"それで、先ほども言いました今までの前例というか、通例ですと、大会派順にそれを決めてきたということがありますので、先ほど会派の順番を決定させていただきましたので、そうなると、自民、自・無で１２番目、１３番目の数を決定していくということになるという。","id":"exchange-002"}]},{"id":"topic-02","title":"附属機関等議会選出委員についておよび(5)各種団体評議員","agenda":"附属機関等議会選出委員についておよび(5)各種団体評議員","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどから会派構成の人数の変更に伴って一つ一つ確認をしているところではありますけれども、年度の途中ということなので、基本的には現状どおりでいいかと思います。ただ、今年の臨時会でまた様々、少し調整も必要ですけれども、会派の人数に応じて協議ができたらと。一言述べさせていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-03","title":"その他各会議の構成等","agenda":"その他各会議の構成等","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"今、高橋伸明委員から、広報会議のサブリーダーということですよね。お願いということで、もともと正副の、リーダー、サブリーダーのバランスもどうかなと思っていたところではあったので、今そういう提案もあったので、共産党として引き受けたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/761909?Template=document&Id=5394#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":6304,"voices":39}},{"id":"r03-20210119-6","meetingId":"r03-cm01","date":"2021年1月19日","dateIso":"2021-01-19","committee":"区民委員会","time":"午後 １時００分～午後 ３時１１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件抜き出しています。","topics":[{"id":"topic-01","title":"令和２年陳情第６２号 目黒川沿いに設置されている喫煙所撤去に関する陳情","agenda":"令和２年陳情第６２号 目黒川沿いに設置されている喫煙所撤去に関する陳情","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"それと、その喫煙所の手前のところに、歩道橋というのですか、橋があって、その橋から下りてくるところがあるのですけれども、そこの下が完全にふさがっていました。この写真では。このコロナ禍の前ですね。この喫煙所自体に、そもそも場所的な問題であるとか、この場所に関して利用者のほうが多過ぎて、このような危険な状態が生じているかどうか、そこに関してどの程度把握していらっしゃいますでしょうか。","respondent":"黛生活安全担当課長","answer":"今、委員ご指摘のとおり、非常に多い、特に昼休みの時間帯ですが、あの喫煙所に２０人ぐらいですね。多くの方が集まって吸われていて、いっぱいになっているような状況があるというのは、私どもでも把握しております。","id":"exchange-001"},{"speaker":"くにば委員","kind":"意見","question":"例えば、その一案として、当然、そのピークの時間でもこういった大変に危険な状況が生じているのであれば、もうそれは喫煙所の１つであれば、一案は閉鎖・移動という形もあるかと思いますし、例えば分散、例えばその時間帯だけに限るかどうか分からないのですけれども、その至近の場所にもう１か所喫煙所を設置するなりをして、１か所に。","respondent":"黛生活安全担当課長","answer":"ただ、委員ご指摘のとおり、大変危険な状態であるというところにつきましては、私どもとしても認識しておりますので、その中でも特に重点的に、的を絞ってパトロールのほうをしつつ、また、利用者の方に危ないのだということを分かってもらえるような。","id":"exchange-002"},{"speaker":"くにば委員","kind":"質問・要望","question":"ですので、この喫煙所撤去に関する陳情は、これはコロナ禍という部分もあるかと思うのですけれども、それを除いてベースの部分で、私は近隣にもう１か所開設をして、危険は回避すべきだ、このまま設置しているべきではない、そこに関しての改善策をしっかりと前に進めていただきたいなという部分に関して、私はそう考えて、この陳情に関しては賛成をしようかと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"本当に喫煙所のある場所の方々、近隣の方々には、本当に、しかもこういう働く方が日中多くいると、昼休みであったり、本当に多く集まられてしまって大変な思いをされながら、コロナの前から、何とかならないかなという思いはあると思うのですけれども、先ほど課長が言った、煙や臭いが広がらないような方法というのは、とっていけたらなというふうにおっしゃっていたのですけれども、そういう方法というのは。","respondent":"黛生活安全担当課長","answer":"ただ、これが、この喫煙所に果たしてしっかりとマッチするものなのかどうかということにつきましては、まだ全然検討段階で、これがいいというところまで結論が出ていないというところだけは、大変申し訳ないですけれどもご了承いただいて、今申し上げましたのは。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"吸う側の方としても、やはり今、受動喫煙防止が広がる中で、吸う場所を探しながら、肩身の狭い思いもしているというのも、喫煙されている方からは聞きますけれども、ですので、そういった被害を与えずに、だけど結局のところ自分の体は被害を被っているので、やはり健康というところを考えると、たばこをやめていくということが一番だと思うのですけれども、それも進めながら、今吸われている方は。","respondent":"黛生活安全担当課長","answer":"委員ご指摘のとおりでございまして、喫煙所、今回の陳情をしていただきました陳情者様のご趣旨なども鑑みますと、まさにおっしゃっていただいたように、これはもうすぐにでも取りかからなければいけない問題だというところにつきましては、肝に銘じて、この間、何とか。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"厚生労働省の調査でも２０１８年が１７.８％だったのが２０２０年には１６.７％と、令和４年までには１２％に下げていくという厚生労働省の表なども見たのですけれども、そうしたところからも減ってきてはいるので、やはり品川区としても、そういった喫煙所の問題解決とともに、課は違いますけれども、厚生委員会のほうの健康課では健康プランを出されていますので。","respondent":"黛生活安全担当課長","answer":"この町会の方と当該喫煙所についてお話合いをする機会というのは、今までございませんでした。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですから、そういったことから見ても、本当に、この喫煙所で吸われている方の煙にさらされながら毎日道を行き来しなければいけない、行き来したくなかったら別の道を選ばなければいけないという、この区民の苦労、そういったところを考えると、１日も早く撤去または被害を抑えられる場所への移動、それは本当に必要だと思うのですけれども、いかがでしょうか。","respondent":"黛生活安全担当課長","answer":"委員ご指摘のとおり、１日も早く、こちらの喫煙所に対してそういう対策をとるか、あるいは、ほかの場所に適地があれば適地のほうへ移動するなど、対策のほうをしっかりとっていく必要があるというふうに考えております。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"その点について、２か月弱あったわけですけれども、これに対して、広がっている事態、喫煙所から広がっている事態について、区として具体的な何かこういう解決策というのは、聞いている限り、まだ明確にはないように見受けられるのですけれども、そこはまだ明確にないということでよろしいですか。","respondent":"黛生活安全担当課長","answer":"当該陳情が出されて以降、こちらの喫煙所のほうに生活安全サポート隊のパトロールのほうを、今まで以上に強化をして回らせていただいているところですが、コロナ禍ということもあるとは思うのですけれども、最大時において、そこからあふれるぐらい多くいた喫煙者が。","id":"exchange-008"},{"speaker":"松本委員","kind":"確認","question":"落ち着いているということなのですけれども、落ち着いているということは、逆にゼロではないというふうに思います。ここは確認ですけれども、路上喫煙禁止・地域美化推進地区であることは間違いないという認識でよろしいでしょうか。","respondent":"黛生活安全担当課長","answer":"ご指摘のとおりです。","id":"exchange-009"},{"speaker":"松本委員","kind":"質問","question":"そうすると、はみ出している人たちは条例違反ということでよろしいでしょうか。","respondent":"黛生活安全担当課長","answer":"厳密に申しますと、これは条例違反というふうに捉えられるかと存じます。","id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"この間、この１年ぐらいでいいですけれども、ここのはみ出している人たち、何人ぐらい罰則が適用されたのでしょうか。","respondent":"黛生活安全担当課長","answer":"４月から１２月までの間に、区内で取締りをいたしました数が６１件ありますが、こちらの喫煙所付近で何人かというところについては手持ちで数字がございませんのでお答えできませんが、６１件ということで、ほぼ例年どおりの状況で取締りのほうは推移をしています。","id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"間違いなくはみ出ているというふうに見えるのですが、ただ、はみ出ているの定義というのがなかなか難しいところもあって、例えば、大崎のように囲いがある場合であれば、はみ出ているというのは一見明白だと思うのですが、ここの場合は、はみ出ているかどうかというのがなかなか分かりにくいところで、路上に喫煙所がある、そこからどのくらい離れたら。","respondent":"黛生活安全担当課長","answer":"明確な基準のほうは設けてはいないところでございまして、例えばなのですが、喫煙所からやや離れているような場所で吸っている人を、すぐ、これで条例違反だから過料を徴収するぞと、こういうスタンスではなく、そういう方には、まず。","id":"exchange-012"},{"speaker":"松本委員","kind":"質問・要望","question":"そこは、その運用でまずいいのかというところがあるかと思います。線、ラインを引くのにどのくらい予算がかかるかまでは私も分からないですけれども、少なくとも、はっきりと明確に定義をしないと、どこまでが違反なのかという、喫煙者の方たちも分からないと思うので、そこまではやっていただきたいと思うのですが、いかがでしょうか。","respondent":"黛生活安全担当課長","answer":"たばこを吸われる方も認識しやすいというところがあろうかと思います。持ち帰らせていただいて、どの程度で何ができるのかということで、しっかり検討の課題とさせていただきたいと思います。","id":"exchange-013"},{"speaker":"小芝委員","kind":"質問・要望","question":"先ほど、答弁の中で課長がお話しされていたので幾つか気になりまして、今の、現状の喫煙所を移設するにしても適地がなかなか見つからない、分散するにしても適地がなかなか見つからないという話だったのですけれども、例えば、民間の事業者、コンビニエンスストア、飲食店も含めて、そういったところと、やはり民間事業者と協力して、民間と地域、行政が一体となって、受動喫煙。","respondent":"黛生活安全担当課長","answer":"ただ、ご指摘のとおり、今後、なかなか行政の力だけでは適地を見つけていくというのが非常に厳しいような現状がある中におきまして、民間のお力をお借りするというのは有効な手段の１つであるというふうに認識をしております。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"ただ、先ほど課長が、一番最初の説明のときに、お気持ちは分かるけれども、すぐ撤去ということではなく、もう少し時間をいただいて、行政としていろいろなことを施策として、施策というか、出すから、もうちょっと時間をいただけませんかみたいな、私を信頼してもうちょっと任せてくれませんかみたいなご意見だったと思うのですけれども、まず、それはそういうことでよろしいのでしょうか。","respondent":"黛生活安全担当課長","answer":"何とか早く、その問題の解決に向けて手を打っていきたいというふうに考えているところです。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"お気持ちは分かるけれども、陳情者の、しつこいですが、もう少し時間をくださいということでいいということを確認をしましたので、先ほども、新しいところを探すとか、いろいろな、作るとか、煙がというのがあったのですけれども、ふと思ったのですけれども、喫煙する方というのは、そもそも論でたばこを買うわけですよね。３０億円。これ。要望をして、何かいい結果を出していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのが、平成１５年から設置されているというところで、設置の基準とか、その辺の決まり、ルールとか、設置に向けては当然町会や警察署のようなところと話し合いながら進めていくのだと思うのですが、その辺のお話の、どういうふうになって設置が決まっていくのかというのを、教えていただければと思います。","respondent":"黛生活安全担当課長","answer":"今後ですが、委員からのご指摘も踏まえまして、こういう喫煙所に関しまして、説明する機会などは、積極的に我々、私のほうで出向いていって、必要な説明のほうをさせていただいて、町の方々にもご理解をしていただけるように進めてまいりたいと考えております。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"すぐそばに、そういうところも、そういう意味では分散で、そういう敷地の活用、検討をこれからされていくというところで、様々検討していっていただきたいのですけれども、例えばコンビニの、民間との連携みたいなところで、コンビニの前にそういう敷地があったりするところの活用とか、そういうところも、今、検討段階ではないとか、要はこれから検討していくというところだと思うので。","respondent":"黛生活安全担当課長","answer":"委員ご指摘のとおり、あらゆる可能性を排除しないで、できることがあればそれをどんどん検討していくというようなスタンスでやってまいりたいというふうに考えております。","id":"exchange-018"},{"speaker":"つる副委員長","kind":"質問・要望","question":"冒頭の説明のところで、陳情の趣旨、目的は撤去であるわけですけれども、その目的というのは受動喫煙等が残らない、双方にとってプラスになるというような理解ではいるのですが、その解決策というところで、冒頭、例えば分煙施設の導入であるとか、検討であるとか、それから民間との協力なども、先ほど藤原委員の質疑の中でも確認ができたところでありますが、それが非常に大事なのかなというところと。","respondent":"黛生活安全担当課長","answer":"最後に、一番最初にいただきましたように、ここの喫煙所、今回の陳情者の方のお気持ちのほうをしっかりと受け止めまして、このままということではなく、何とか、吸う人、たばこを吸う方も、吸わない方もご納得がいただけるような措置のほうを一生懸命検討してまいりますので。","id":"exchange-019"},{"speaker":"つる副委員長","kind":"確認","question":"設置されている場所自体は、公有地だと思うのですけれども、そうではなくて、私が聞いたのは、喫煙者が吸うであろう、立っているであろう場所というのが、先ほど来、確認の中で、いろいろ確認できるとかというのはあるのですけれども、実際に生活安全サポート隊も現状を確認して、現認しているところもあると思うのですが、そういう人たちが立っているところというのは、恐らく、そこは車道ですか。","respondent":"黛生活安全担当課長","answer":"少なくとも、車道にあふれているような状況があるというのは、これは間違いがないところです。","id":"exchange-020"},{"speaker":"つる副委員長","kind":"質問","question":"喫煙しているとしていないとに関わらず。車道上にこういう歩行者であろう人たちがたむろしている状況というのは、道路交通法上、何か規制等はあるのでしょうか。所管が違うから、分からなければ結構です。","respondent":"黛生活安全担当課長","answer":"決して、何か理由があってそこにとどまっているというわけではなく、たばこを吸うために、そこに多数の者がたむろしているというような状況が、いわゆる法律に適した行為ではないのではないかというふうには認識しております。","id":"exchange-021"},{"speaker":"つる副委員長","kind":"質問・要望","question":"何においても、今、コロナ禍にあっても、周りに気を遣わなきゃなというところがある中で、ことたばこというのは今に始まったわけではないわけですけれども。ですから、そういう工夫も、１つの課だけで、どうしよう、どうしようではなく、いろいろな課をまたいで知恵を出し合って、この課題をどうしようかねというところで対策をとっていく必要はあるのだろうなと。","respondent":"黛生活安全担当課長","answer":"そういうところをもっと工夫して、なぜそこで吸ってはいけないのかと、そういうことによって、誰が苦労しているのか、困っているのかというところまで、しっかりと説明をしたり、また、看板も、そういうところを分かるようなものにするなど、丁寧な説明をしながら。","id":"exchange-022"},{"speaker":"小芝委員","kind":"意見","question":"マナーの悪い方がいれば、そうでない方もいらっしゃいますけれども、ポイ捨てであるとか、また、路地裏での喫煙というものが増えると思いますので、直ちに撤去というふうには、私は考えておりませんで、今回の件に関しては継続でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"つる副委員長","kind":"質問・要望","question":"冒頭、課長のほうから説明がありました、先ほども質疑の中でも確認させていただきましたけれども、受動喫煙対策というところでの方向性、区行政としての今後の対応というのは示された中で、ただ一方で、先ほども質疑の中で一度申し上げましたけれども、その根本的な目的のところの解決には、では撤去が、すぐイコール喫煙者がこの周りにはないのだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こうしたたばこをめぐる、喫煙をめぐる問題が、この受動喫煙防止ということからすごく広がっていて、減ってきているという現状はありつつも、やはり煙を浴びる方、吸う方もそうですけれども、被害は残っているわけで、そして生活、ふだんの生活にも支障を来しているということであれば、私はこの陳情は採択して、議会が後押しする形で撤去へ向かっていくということをしていくべきだなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"くにば委員","kind":"意見","question":"この場で結論を出すで、採択で考えております。もしくは、先ほど申し上げた形で、ここの喫煙所はそのまま継続で利用して、この近隣にもう１か所喫煙所を開設するということで、そのいずれか、どちらにいたしましても、今回の陳情に関しては採択という立場でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"松本委員","kind":"意見","question":"大崎でトリックアートを使って、あれがどこまで効果があるのかというのは継続的に見ていかないといけないと思いますけれども、少なくとも、当区は何とか路上喫煙と、喫煙所の中での喫煙と、副流煙との、受動喫煙との関係で、何とか工夫できないかということをやられていたと思いますので、それはやはり評価されるべきことだと思っていて、全部の解決策が。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"}]},{"id":"topic-02","title":"しながわ活力応援給付金事業の進捗状況","agenda":"しながわ活力応援給付金事業の進捗状況","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"１点だけお伺いします。一番上の内容は、これは目的だと思うのですけれども、区全体の活力を取り戻すために給付金を給付したことですが、区全体の活力は取り戻せましたか。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"これまでの給付金の給付総額につきましては、１３０億円以上という形になっておりまして、昨年は３０％の区内の特別プレミアム付共通商品券を発行しておりましたり、そういったところから、区内の経済の下支えになっていると。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"つまり、もうそんなに、百何十億円も使ってもう１回配りましょうと言っても、いやあとなってしまうかもしれないけれども、直接区民にお金をこういうふうに配るという施策は、そんなにもうできないかもしれないけれども、やはり区民の方というのは本当にこれを喜んでいるのですねということを改めて確認して、担当課長もそれをひしひしと感じて、これから区政に邁進していっていただきたいと思いますので。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"この間、区民の方から、大変、コールセンター等やお手紙等でも、お礼の声ですとか、そういったものをいただきまして、大変励みになり、この事業を、まだ新生児の給付金の給付がありますが、進めているところです。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"私たちのところにも、耐え忍んできたけれども、やはり店を閉める、または解雇された、こうした相談はまだまだ続いているのですね。そういう中で、まだまだ支援が必要だなというふうには思っていますけれども、こうした、区が直接区民に支援をするという、こういう対策が今後も必要になってくるのではなかろうかと、私は思うのですけれども、区の考えはどうなのでしょうか。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"昨年４月２７日基準日の住民登録がある区民の方に給付し、また、新生児の方の給付というのを進めている中で、事業を行っているところでありまして、改めてという考えにつきましては、今のところございません。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こうした区民の暮らしというのが、このコロナ禍で本当に激変してきている中では、区がこうした直接支援をするというのは、本当に暮らしの１つの助けになりますし、励みになるし、その活力というものにもつながるかなと思いますので、状況を見て、引き続きこうした、私たちも要望はしていきますけれども、対応をしていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"松本委員","kind":"質問","question":"まだ決定していないから想定しなくていいではなくて、これを今のうちから、あり得るということで想定していただくのが大事かなと思うのですけれども、分からないですけれどもね。そのあたり、今後のことを考えた上で、どういうふうに短縮可能なのか、あるいはそれを所管間で情報共有しながら、一応、念頭に置かれているのか、その点についてお考えをお伺いできればと思います。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"今回のしながわ活力応援給付金の給付事務につきましては、ＲＰＡまたはＡＩ－ＯＣＲといったデジタル技術を活用しました。特別定額給付金での事務状況というのを伺っているところですので、適切な人数で委託しまして、開封作業等の対応というものもしてきました。","id":"exchange-032"},{"speaker":"松本委員","kind":"質問・要望","question":"ぜひそこは、今回の新型コロナ禍だけではなくて、今後何かこういった給付金とかが、何がしかの原因であるときに、早めに区の中で情報共有して、考えていただくというのが大事かなというふうに思いますので、これはあくまで要望なのですけれども、今回の給付の中で、国のほうの１０万円の特別定額給付金のときもそうだったのですけれども、これは考え方があると思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"つる副委員長","kind":"確認","question":"確認させてください。新生児分で１２月１１日から３１日までの方には、１月２２日に申請書を発送、それで、申請期限というのは、各発送者ごとにお知らせするというふうになっているかと思うのですけれども、このコールセンター等が３月３１日で閉めるとなっていますので、閉めた後に支給ということもあるのだと思うのですが、書類を受け取ったりとかですね。その期限というのはいつになるのか教えてください。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"１２月１１日から１２月３１日生まれの新生児の申請書を１月２２日に発送しまして、申請期限は３月１５日を申請期限とする予定です。","id":"exchange-034"},{"speaker":"つる副委員長","kind":"質問・要望","question":"１０万円のときもそうですし、もちろん部署が違うので、システム等、そうしたものも含め、人件費等も含めて、別でどうしてもかかってしまう経費というのは、これはあるとは思うのですが、例えばその申請方法、今回は紙媒体でやり取りをしましたけれども、例えば、それが今後電子申請であるとか、そういったことによって、またそのシステムを作るのにお金がかかるとかはあるのでしょうけれども、極力。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"速やかに区民の皆様に給付するというところから、事務を委託する人数等も計算しておりまして、今後という部分になりますけれども、給付を早めるためには、やはり同数程度の経費というのがかかる見込みではあろうかと思いますが、経験というのを生かす中で。","id":"exchange-035"}]},{"id":"topic-03","title":"ＬＩＮＥを活用した住民異動届出書等作成ツールの運用開始","agenda":"ＬＩＮＥを活用した住民異動届出書等作成ツールの運用開始","exchanges":[{"speaker":"小芝委員","kind":"質問・要望","question":"何点か確認をさせていただきたいのですけれども、この申請書自動交付機付記載台というのは、これは窓口のほうにあるということですか。それとも、ロビーの記載台の近くにあるということですかね。","respondent":"木村戸籍住民課長","answer":"今、ロビーのほうにございまして、正面玄関から入ってきていただいた大きなロビーの中にあります。","id":"exchange-036"},{"speaker":"小芝委員","kind":"質問","question":"これから適用される、対象となる届書が増えてくるわけなのですけれども、そうすると、何かイメージでは、この自動の交付記載台のほうの行列が出てくるのではないかという、そういった懸念もあったりするのですけれども、その辺どのようにお考えでしょうか。","respondent":"木村戸籍住民課長","answer":"まだ、当初はそこまでの使用はないであろうかというところ、現在の自動交付機の記載台、ＰＲもありますけれども、まだなかなか使われていないような状況もございまして、このＬＩＮＥでのというところを機に、またＰＲも進めてまいりたいと思いますが、すぐ行列というような形は。","id":"exchange-037"},{"speaker":"小芝委員","kind":"質問・要望","question":"私もＬＩＮＥのほうの、チャットボットのほうもすごく活用させていただいておりまして、大変使いやすいものだと思います。ただ、やはりＬＩＮＥというのはどうしても世代的には若い方々が多いので、これをやはり、広くご高齢の方にも普及していけるように、ぜひ取り組んでいただきたいと思います。言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"このツール運用とはちょっとずれるかもしれないけれども、どうしても言わざるを得ないので言いますが、いいでしょうか。すばらしいですね。本当にすばらしい。私は。ＬＩＮＥの親会社があるかもしれないし、ＬＩＮＥというツールかもしれないけれども、ＬＩＮＥ自体、大丈夫だという、よそには絶対流れませんよという保証が、だって個人情報とか入れてやるわけですから、その辺についてはいかがでしょうか。","respondent":"木村戸籍住民課長","answer":"高齢者の方を忘れないで対応をです。私どものほうも承知をしておりまして、先ほど、寄り添った対応という話がありましたけれども、やはり、これにお書きくださいと言っても、なかなかどこにどう何を書いていいのかという部分もありますので、それは直接ご案内をしています。","id":"exchange-039"}]},{"id":"topic-04","title":"飲食店・医療従事者応援プロジェクトの実施","agenda":"飲食店・医療従事者応援プロジェクトの実施","exchanges":[{"speaker":"小芝委員","kind":"確認","question":"幾つか確認をします。平日と土曜日ということで、１月１８日から日曜日以外は毎日という認識でよろしいでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"基本的に毎日、平日月曜日から金曜日と土曜日という形で進めしています。","id":"exchange-040"},{"speaker":"小芝委員","kind":"質問","question":"今回のこの目的は、飲食店の売上確保と医療従事者への感謝のメッセージということで、飲食店および関連企業、卸しなどの売上確保と雇用維持ということなのですけれども、配達は、先ほどレンタカーをお借りするということだったのですけれども、区職員のほうでされているのでしょうか。それとも、区内の業者の方にお願いをしているのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"商店街連合会のほうで、ご協力をいつもいただいているところがあるようですので、毎日というわけではないのですが、特に委託業者がというわけではなくて、一応、自前でレンタカーを用意して、そこに運転手を、知っている方と言うのですか、雇って。","id":"exchange-041"},{"speaker":"くにば委員","kind":"質問","question":"何点か伺うのですけれども、まずは、こちら今回は区内２病院ということなのですけれども、この２病院を選んだ理由を伺いたいです。その不公平感を拭えるだけの具体的な理由が、きちんと説明できるような理由があるのかどうか、そういった部分を踏まえて、２病院になった理由をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"こういう形で病院に飲食店が配達という形をお話ししたところ、こちらの２病院の方が、一応協力しましょうということでお手を挙げていただいたですので、決してこの２病院だけ声をかけたというわけではございません。","id":"exchange-042"},{"speaker":"くにば委員","kind":"質問","question":"すみません。今のご答弁で違和感があったのですけれども、複数の病院にお声をかけたけれども、協力という形、これはほかの病院、どちらでも無料で医療従事者の方が食事を提供していただけるなら、大喜びでしていただくと思うのですけれども、なぜその協力という形で、関係がなっているのか、ちょっとそこに関してもう一度ご答弁をお願いします。","respondent":"遠藤商業・ものづくり課長","answer":"病院にもそれぞれの事情があるということで、今回については、恐らくお弁当が集まってきて、それを結局、あちこちに配達、中で仕分けしなけしなければいけないとか、そういう人員の関係もあるのかなというふうに考えておりますけれども、いろいろそれぞれの病院。","id":"exchange-043"},{"speaker":"くにば委員","kind":"意見","question":"あくまで配達をする側の問題で、配達する側がいろいろな病院を回って、いろいろな店舗を回って回収をして、いろいろな病院に配達をするという部分で、その配達の手間であるとか、配達が難しくなるというのは、あくまで病院側のマターではないような気がするのですけれども、なぜそこが、今、病院側でご賛同いただけた理由、もしくはご賛同いただけなかった理由に含まれているのか。","respondent":"遠藤商業・ものづくり課長","answer":"説明が不十分で申し訳ございません。私どもとしては、お声をかけてさせていただいた全ての病院に対応できるような体制は一応とれるというふうに考えていたところです。ただ、正直、病院のほうでも、はっきりと断る理由というのですかね。","id":"exchange-044"},{"speaker":"くにば委員","kind":"質問","question":"分かりました。もう一度具体的に伺いますけれども、それでは、今回この２病院以外に、トータルで何病院にお声がけをしたのか。それで、お声がけをした病院の選定基準をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"ある程度、一定大きい病院を選定させていただいたところです。その中で、すみません。幾つの病院かということになりますけれども、こちらのほうで一定の基準にというところで声をかけさせていただいたです。","id":"exchange-045"},{"speaker":"くにば委員","kind":"質問","question":"もう少し、それはしっかりと具体的にお聞きしたい。なぜあの病院だけ、区のほうから無料でお弁当をもらっているのだ、なぜうちの病院では声もかけてもらえなかったのか、そういった不公平感というのは生じてしまうと思うのですけれども、そこの部分を払拭するために、今の部分について、具体的にもう一度ご答弁ください。","respondent":"遠藤商業・ものづくり課長","answer":"今回の選定基準といたしましては、いわゆるコロナの関係で、一定のご協力をいただいているところというのが、選定の一番大きなところです。そこで、逼迫しているというので、大変だというところで選ばせていただいたです。","id":"exchange-046"},{"speaker":"くにば委員","kind":"質問・要望","question":"やはり不公平感という部分だけは生じないような施策のほうを、あとは、そういったようにならないようなオペレーションというのを考えていただきたいなというのが１点目です。それで、こちらの発注先については、これは区商連のほうで一時的に決めたのか、それとも発注先は区のほうでももろもろ検討して最終的に決めたのか、こちら、誰がどういう基準で決めたのかということを伺いたいです。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの飲食店の選定につきましては、私どもは一切関与しておりませんで、商店街連合会のほうで、各商店街のほうに、こういうことをやります、あるいは。","id":"exchange-047"},{"speaker":"くにば委員","kind":"質問","question":"実際に感染防止ステッカー、誰でもダウンロードすれば掲示できます。ですが、このステッカー掲載以外の部分で、必ず営業時間２０時まで、都の要請には必ず従っているというのが条件に入っているのか、それとも、感染防止ステッカーを掲載しているから２０時までの時間短縮に協力をしていなくても大丈夫なのか、さらには、その営業時間２０時まで「等」の部分で、ほかにも条件があるものなのか、伺いたいです。","respondent":"遠藤商業・ものづくり課長","answer":"そういう部分も含めまして、感染拡大防止についていろいろ確認、商店街連合会のほうで、実際に店舗、当然、お弁当を集めに行きますので、そういうところで確認しながらというところで、万が一、ここは、というところであれば。","id":"exchange-048"},{"speaker":"くにば委員","kind":"質問","question":"基本的にはもうこちらは区商連のほうに、チェックであるとかは任せて、区のほうではチェックに関しては、関わっていないという認識でいいのかどうかという部分と、あとはもう１点、営業時間２０時までの時間短縮要請に応じているという部分に関して、これは対象の期間中、必ず全ての期間においてこちらに従いますというふうに、事前におっしゃった自己申告のみで、その後のチェック。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、こちらの、いわゆる補助事業という形になっておりますので、私どももこちらが条件で補助してくださいという条件で作らせていただいているところですので、当然これは商店街連合会のほうできちんと守っていただくというところで考えているところですので。","id":"exchange-049"},{"speaker":"くにば委員","kind":"質問・要望","question":"分かりました。今のご答弁で一番最後にありました形で、そういった、実際に２０時まで、毎日必ず要請に従っていたかどうかというチェックは必要だと思う、そういった問題点があるということだけは、お伝えいただきたいなと思います。それで、もう１つに関してなのですけれども、こちら、現状に関しては、２月６日までとした場合という形で予算額が計上されております。","respondent":"遠藤商業・ものづくり課長","answer":"それ以降につきましては、まだ考えておりませんが、何分、予算の範囲内でということで、それ以上につきましては、状況を見ながらというふうにしか、実際の執行などを見ながらというところになりますけれども、一応、今のところ。","id":"exchange-050"},{"speaker":"くにば委員","kind":"意見","question":"こちらに関しては、おっしゃった形で、状況に応じて柔軟な対応をぜひともしていただければと思います。ただし、もちろん予算ありきという部分だと思うので、余りにも長期化する部分に関しては、どうするかというのを、また審査をしなければいけないという状況もあると思うのですけれども、そこに関してはぜひとも柔軟に対応していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"大倉委員","kind":"質問・要望","question":"１食８００円ということなのですけれども、８００円の基準はどういうあれなのですかという。","respondent":"遠藤商業・ものづくり課長","answer":"商連に加盟していないところですけれども、商連の主催セミナーとか、そういう部分に参加している方も、一応参加の対象という形にさせていただいているところですので、実際問題、商店街に入っていない店舗もいらっしゃるところですけれども、今回の対象店舗が。","id":"exchange-052"},{"speaker":"大倉委員","kind":"確認","question":"８００円の部分ですが、では、例えば、今まで販売しているお弁当が９００円とかの、８００円を超えている状況については、品川区の予算の中では出ないけれども、どこかでもしそういう金額設定があるのであれば、どこかが負担するという形になっているということの確認と、あとは、商連主催セミナーに参加していれば、他の３つをクリアしていれば参加できるということだと伺ったのですが、これは。","respondent":"遠藤商業・ものづくり課長","answer":"８００円までの予算ということで、９００円だった場合というのは、委員おっしゃったとおりの、その１００円の部分は、原材料、ものを落とすとかいろいろなことはあるかと思いますけれども、そういう形で対応いただくような形になっております。","id":"exchange-053"},{"speaker":"大倉委員","kind":"質問","question":"最後に。商品券が使える店舗というのは、商店街ではなくても使えるというのは分かったのですけれども、そうすると、商店街連合会に加盟しているということは前提だということになるのですかねという。","respondent":"遠藤商業・ものづくり課長","answer":"失礼いたしました。そうですね。全く関係ないところという、何らかの形で、商店街連合会の事業ですので、全くというのはなかなか商店街連合会のほうでも支援しづらいところもあろうかと思いますので、一応、スキームとしてはそのような形にしています。","id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問","question":"この参加店、今いろいろお話もありましたけれども、４１店舗が参加予定ということだったと思うのですけれども、この品川区内に飲食店というのがどれぐらいあって、それで、しかもこの条件に当てはまる店舗がどれぐらいあって、そのうちの４１店舗なのかというのは分からないですかね。分かれば教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"本当は入れておかなければいけない数字だったのですが、大変申し訳ございません。特に今回、特定のところに声をかけたというわけではございませんので、広く商店街さんを通じてやっているところですので、一応、手を挙げたところで断っているというところはないような状況です。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。それで、この事業予算のところは、これはもう品川区だけが出す、都からとか、国からとかは入っていない、区の単費ということでいいですかね。","respondent":"遠藤商業・ものづくり課長","answer":"特に特定財源は入っていないような状況です。","id":"exchange-056"},{"speaker":"つる副委員長","kind":"確認","question":"今、確認があったところなのですけれども、プレスを見ると、当然、変化がありますよとなっているので、最終、今、先ほどご答弁のあった参加店舗数については４１店舗で、どれだけ期間が延びるか分からないですけれども、巡回というか、回して、発注をかけるという理解ですかね。そこを教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、やっていく中で、どこかがやめたりとか、あるいは、何らかの形でできなくなったりとかいう部分がありますので、そういう部分では、多少のことはあるのかなと思いますけれども、ただ、募集をしていないので、新たに追加というのは難しいので。","id":"exchange-057"},{"speaker":"つる副委員長","kind":"質問","question":"やはり、来店客数が減っちゃうから、ふだんはテイクアウトをやっていないのだけれどもテイクアウト用のお弁当を作ってという、そこのところなのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"4)で想定していたのは、いわゆるお弁当屋さんとしてお店を最初からやっているようなところを想定しておりましたので、仮に今回のコロナの影響で、一定程度お店は閉めてというところであれば、検討するような形になるのかなと思いますけれども。","id":"exchange-058"},{"speaker":"つる副委員長","kind":"質問","question":"予算のところなのですが、これは、もともと当初とか、また補正があったわけではないと思うので、流用だと思うのですが、その元の財源は何を活用して、今この事業を、プロジェクトをやっているのか教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの原資となる部分につきましては、今年は商店街さんのイベントがほとんどできなかったというところがございまして、そういう部分のお金が当然ながら不用額という形になりそうなところですので、そういうものなどを回しまして、こちらのほうで使わせていただくということで。","id":"exchange-059"},{"speaker":"つる副委員長","kind":"質問","question":"であれば、例えば、今回は趣旨としては医療従事者というところに絞ってという感じだと思うのですけれども、いろいろなやり方があると思うのですね。その予算をどう扱うかという、非常にセンシティブな部分であると思うのですね。いろいろな団体、グループがやろうとしたけれどもだめだった。その衛生管理の部分というのが、非常に、コロナは関係なく、あると思う、食べ物ですから。","respondent":"遠藤商業・ものづくり課長","answer":"今回、このように商店街連合会から、ぜひ医療従事者にというようなお話を伺ったところで進めさせていただいたところでございまして、あくまでも私どもの意味合いは飲食店といいますか、そういうほうの支援という形で、商業・ものづくり課でやらせていただいているところです。","id":"exchange-060"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"つる副委員長","kind":"意見","question":"当然、歴史館自体は感染症対策をとったりとかしているのですけれども、この展示期間が３月２１日までと短い期間であるのだけれども、そこまで感染がどうなのかなというのがあるので、集団で来る者に対して割引というのは、いろいろな考え方・見方があるのでしょうけれども、これは一般の運用をそのまま引っ張ったのかなと思うのですが、逆に今、お一人様に対する割引というのが飲食などにあると思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/943539?Template=document&Id=2888#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":44554,"voices":160}},{"id":"r03-20210119-7","meetingId":"r03-cm01","date":"2021年1月19日","dateIso":"2021-01-19","committee":"厚生委員会","time":"午後 １時００分～午後 ４時３５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件抜き出しています。","topics":[{"id":"topic-01","title":"の(3)から聴取いたします。 それでは、(3)「こころの健康づくりカレンダー」配布","agenda":"の(3)から聴取いたします。 それでは、(3)「こころの健康づくりカレンダー」配布","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"いろいろな相談窓口がまとめて記してあって、よい試みだなと思うのですけれども、一番最後にあるいろいろな相談窓口、特にこころとからだの相談のところに、どのぐらい相談が来ているのかということをお伺いしたいのと、活用の仕方としては、配布したというようなことなのでしょうか。","respondent":"鷹箸保健予防課長","answer":"こころとからだの相談、自殺絡みでというところでは、申しわけありませんが、現在、保健センター等でそのための特別な統計をとってございませんので、数の上でのご報告はしかねるところですが、昨年の緊急事態宣言以降、外出ができないので。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問・要望","question":"こちら、少し前に見たときも、とてもインパクトのある、すごく効果を期待できるつくりだと思っています。だから、これはいい検証ができるかなと。あるいは、今は保健所中心ですが、ほかの施策にもすごく応用が利くのかなと思ったので、負担にならない程度で情報収集をされたりという要望なのですが、ご所見をお願いします。","respondent":"鷹箸保健予防課長","answer":"いただいたお話ですが、効果測定も含めて、どのようにしたらいいかというのは、すみません、これから考えてまいりますが、もともとこのキャラクターは文化観光課で推奨していたものなのですけれども、まず出来上がりを文化観光課長に渡しまして。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今ちょっと思いついたことなので、そこだけではなくて、恐らく生活福祉課とかいろいろなところに、何で女性が増えるのかというのは私もわからないところがあるのですけれども、妻とも話すのですが、女性はつながりが切れてしまうと、男性よりも絶望に襲われやすいのかなとうちの妻は言っていましたけれども、ちょっとわからないのですが、そういう方たちに、男女共同参画センターだけではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどから評判がいいということで、本当にかわいらしくて、明るくて、飾っておきたいカレンダーだなと思います。５,５００部ということですけれども、この５,５００部の活用は、大体どこにどれぐらいみたいな、そういうのがあったら教えていただきたいのが１つと、それから、これは自殺対策計画ができたときに、中小企業向け啓発カレンダー等の配布というところからつくられたということですよね。","respondent":"鷹箸保健予防課長","answer":"学校は各フロアの廊下とかにも貼っていただこうと思っておりまして、今後増刷した分はそうしたところに配布する予定にしています。保育施設は、数が非常に多いのと、１つ１つのお部屋の数まで調べられなかったので、園に何部という形での送り方になってあります。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"こういう悩みがあったときにはこういうところでこういう相談がありますよだったり、子どもの心のＳＯＳということで、子どもの虐待とはとか、そういういろいろなところで情報を得られるということが、具体的に使える、具体的なところで活用できるというものが、これを調べていけばそういうところにつながっていくというのはあると思うのですけれども、カレンダーそのものでこういうものがあったので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"「品川区における新型コロナウイルス感染症患者数等について」というホームページで公表されているデータについて、もう少し具体的に伺いたいのですけれども、この中でいうと３番の表なのですが、自宅待機者が５６８人、その１週間前の１９２人と比較して３倍近くに増えているのですが、こういう状態に対して区としてはどういうふうに捉えていらっしゃるのか。","respondent":"鷹箸保健予防課長","answer":"そちらはアレルギー対応もした食べ物ということで、我々もかなり期待しているところなのですが、ただ、届くのが１日遅くなるというのだけは違いです。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"今の説明で、よく理解できていないのかもしれないですが、入院療養の調整中という人の数字は、今の説明とはまた別の話なのですか。それを伺おうと思っていたのですけれども、今、いろいろ詳しくご説明なさったので、そこのところの関係もお伺いしたいのですけれども、お願いします。","respondent":"鷹箸保健予防課長","answer":"東京都で別々に出ているものは、区の毎週更新している統計では、入院待ちの人、施設療養待ちの人も合わせて、その時点で家にいるので自宅療養者の中に入っています。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"例えば三百何人の自宅療養者の中で調整中の方は何人というのはわかるのですか。","respondent":"鷹箸保健予防課長","answer":"もちろんわかりますが、毎日、それから時間で変わるので、それをこのグラフに反映させることは、申しわけございません、ほぼ不可能です。","id":"exchange-008"},{"speaker":"おくの委員","kind":"質問","question":"それから下のＰＣＲ検査センターが３日間で１９１件となっているから、割ると１日大体６０件。そうすると、１日４００件というのを検査センター以外のところでやっていることになると思うのですけれども、それは医療機関でやっていることになると思うのですが、検査ができる医療機関というのは大体何カ所になったのでしょうか。それをお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"最新のデータが都から送られてきますが、私の記憶では１２月１０日の１３４カ所というのが最新のものと記憶しております。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"こういう事態になっているのですけれども、やはり検査数を増やすという方法に変えていくべきではないかと前から申し上げているのですが、品川区は無症状者を把握・保護するためのＰＣＲ検査をやる方針はとっていないとおっしゃっていましたが、私はこういう実態から転換すべきではないかと思うのですけれども、こういう実態を踏まえると、ますますそういうふうに言えるのではないかと思うのですが。","respondent":"鷹箸保健予防課長","answer":"ただ、検査が必要だと思う方あるいは身近な方が陽性になったので自分は濃厚接触者ではないかといった方々への検査は、無症状であっても非常に重要だと考えますので、品川区におきましては、つい先週、検査を実施可能な医療機関について、ご自分が濃厚接触者だと思う方。","id":"exchange-010"},{"speaker":"おくの委員","kind":"質問","question":"今、濃厚接触者ということで言われたので、１つお伺いしたいのは、濃厚接触者、マスクをせずに１５分以上、１メートル以内の距離で接した人というふうに国立感染症研究所が出した基準ということなのですけれども、この基準にエビデンスはあるのでしょうか。それが１つお伺いしたいことです。これを行った結果はどうだったのかということをお伺いしたい。その点、お伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"確認","question":"今の質疑の中で新しい情報があったので確認したいのですが、まず１点目が、課長の記憶だと、東京都で１３４カ所ぐらい検査をできるところがあるよという、正確な数字かどうかはあれですけれども、それはどういう施設のことをおっしゃって……、東京都が把握しているということですが、私が知っている限りでも、うちの地域にも格安で唾液を集めますよというところもあるのですが。","respondent":"鷹箸保健予防課長","answer":"ですから、唾液を郵送でみたいな医療機関は、先ほどの１３４カ所には入っていません。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問","question":"協力要請で、例えば私がそういうご相談を受けたときに、濃厚接触者だと私は思うのだけれどもという事例が２日以内にあった場合に、やっているところを知っているから、あそこに行って受けてみたらどうですかといったときに、断られるようなこと、協力要請、お願いベースの話であって、いや、うちはそういうの、いきなり来られてもできませんからという感じなのか、今のところ、どういう感じになっているのか。","respondent":"鷹箸保健予防課長","answer":"少しおくれましても、それをするということは、ご自身に心配のある方の検査は確実にできないといけませんので、今、時期はわからないのですが、東京都から東京都医師会にそのような話が、品川区は少し早めにそれを区の２つの医師会にお願いしたところですが。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今のお話ですけれども、これまでは医療機関を受診しても、かなり重症にならないとＰＣＲ検査を受けられないという、私の知り合いが、発熱して２回受診したけれども、一番初めに受診したときに、コロナでは困るのでＰＣＲ検査を受けさせてもらえないかと言ったけれども、３７度何分だったので、それではまだだと言われて、２回目もだめで、３９度何分が３日ぐらい続いて、やりましょうということになって。","respondent":"鷹箸保健予防課長","answer":"ただ、ご家族の方への検査については、先ほどの説明のとおり、これまでですと、保健所から家族が濃厚接触者と判断されたので、濃厚接触者と判断された時点で今度は検査に行くにも公共交通機関を使ってはいけないとか、いろいろとあるのですけれども。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"酸素飽和度を測っておくというのが、重症を発見するというところでもすごく、それがポイントだと言われておりますので、そこのところはぜひ継続してお願いしたいと思います。結果はわかりましたか、どうでしたかと聞いていたのですけれども、結果がやっと来ましたというのが１５日にメールで来たので、そんな状況だったのですが、そこら辺のところはここの事例ぐらいで、あとはそれほどないのでしょうか。","respondent":"宮尾高齢者福祉課長、鷹箸保健予防課長","answer":"９月の補正予算で予算をいただいて、ＰＣＲ検査を実施させていただきました。検査総数ですが、最終的には３,９５６人に対して実施いたしました。このうち、陽性と判明された方が全部で５名いらっしゃいました。区のほうで毎回何百検体を出しても、１回目の検査では再検査扱いということで、そういう方は翌日になったりということは確かに実際にあるので、そういう場合もあるかもしれませんが、とにかくその方のケースについての正確なところは。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうことを避けていくためにも、高齢者施設や障害者施設の入所者・通所者、そこの従事者、それから医療機関の従事者へのＰＣＲ検査を拡充していくことがやはり必要なのではないかなと改めて思うのですけれども、そういう点についてはいかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"２点ご質問いただきましたが、合わせてお答えいたしますと、確かに重症化を予防するために対象者を全員検査するという考え方はあると思いますが、現状、少なくとも品川区の状況は、陽性の方で入院が必要な方がなかなか入院できないという状況の中で。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それは改めて申し上げておきたいと思います。それともう１つ、今、医療機関もすごく大変な状況にあると思うのですけれども、そういう中で品川区も医療機関への支援を出されたということは、本当に評価されることだと思います。支援金はもう支給されたのかということと、慰労金についてはどうなのかということについてもお聞かせいただきたいと思います。","respondent":"高山健康課長","answer":"ご質問いただきました、補正予算でお認めいただきました慰労金、そして支援金に関しましては、今、医療機関と最終的な調整をしているところでございまして、お認めいただいた限られた予算を功労に応じて等しく分配するという観点から、今、最終的な調整をしています。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"医療機関は本当に大変な状況で、減収補填という考え方が政府にないので本当に苦労していますし、もともと医療機関はどこもゆとりがない中で、今回のコロナというところで本当に大変な思いをされているので、ぜひなるべく早くの支援をということでよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"それからもう１つは、今随分お話がありましたが、保健所職員の方々の勤務状況が大変厳しい状況であるということもあるので、時間外勤務の状況とか働いている方々の身体的・精神的な状況は、もちろんものすごく大変だと思うのですけれども、その辺の状況について、わかる範囲で教えてください。","respondent":"鷹箸保健予防課長","answer":"保健所の職員ですが、もともと常勤の職員の数が決して多くなかったので、個別の職員のかなりの超勤で対応していたところですが、先ほどの資料でご説明したとおり、暮れから保健所の中での応援、それから健康推進部からの応援も含めて。","id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうございました。それから、職員の方、今お話があったように、大変な状況の中でお仕事されているということなので、もちろん課長をはじめ、職員の方々、非常に大変だと思うので、健康状態を把握しながら、少し改善するのではないかということですから、ぜひそういった点を考慮していただいて、お仕事していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"確認","question":"今の職員の関係なのですけれども、自宅で調整なり、待機、自宅療養されている方が数百人、３００人から４００人いらっしゃるというところで、毎日１回、保健所の方がご連絡されて健康状態を確認されていると聞いていますが、東京都でフォローアップセンターを立ち上げると。","respondent":"鷹箸保健予防課長","answer":"正式にといいますか、確実に始まるのはようやく１月２５日でございまして、そこから東京都のフォローアップセンターに自宅療養者の部分も、電話だけではなくて、東京都はＬＩＮＥでの健康管理もしてくださるということで、そこも頼む予定になっていますが。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"「品川区における新型コロナウイルス感染症患者数等について」というところでの確認だけさせていただきたいのですけれども、「１.届出週別、感染源判明別感染者数、及び累計感染者数」というところで、１週間ごとの感染者数が茶色い数字で出ていて、１月４日から１月１０日までで４９７人とあがっているのですけれども、この数字というのは、区民ではなくて。","respondent":"鷹箸保健予防課長","answer":"つまり、先ほど高橋（し）委員のご質問にお答えしたとおり、区内の病院に入院している患者は全て品川区管理といいますか、品川区が把握してサポートしなくてはいけない患者で、品川区保健所が対応している数ですので、区民以外の重症な入院患者。","id":"exchange-022"}]},{"id":"topic-03","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"障害者団体ヒアリングの実施、この１３団体、前にも伺ったのかな、どの団体かを教えてください。それから、２３区の他区での説明会の実施状況をご存じなら教えていただきたいと思います。それをお願いします。","respondent":"築山障害者施策推進担当課長","answer":"こちらにヒアリング実施予定の団体を記載させていただいているところです。他区の説明会の実施状況ということで、自治体によっては実施されているところもあるということを聞いてはおりますけれども、全て正確に把握しているわけではございません。","id":"exchange-023"},{"speaker":"おくの委員","kind":"質問","question":"把握しているところだけでも教えていただけますか。","respondent":"築山障害者施策推進担当課長","answer":"具体的な自治体というところでは、今、手元に資料があるわけではないので回答できないのですが、やっているところもあるということは聞いております。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"確認させていただきたいのですけれども、正直、本当にわからないところがあって、陳情の文章、陳情の理由の中に、障害者団体に加入している障害者はとても少なく、障害者７団体の加入率はわずか５％と書いてあるのですけれども、これは当事者の方のご意見なので、もしわかるのであれば、こうおっしゃっている根拠、推測でもいいので、どういうことでこういうことをおっしゃっているのか。","respondent":"築山障害者施策推進担当課長","answer":"１点目、陳情者の方が５％とおっしゃっている理由ですけれども、私もなぜ５％という数字が出てきたのかがわからないものでして、障害者団体の人数は公表しているところではございませんので、恐らく陳情者の知り得るところで計算されたのかなと認識しています。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"確認","question":"確認ですけれども、今ここに配布数が６,４６２とあるのですが、この数が品川区で、行った当時、サービスを受けていた方ということでよろしいのですか。８２ページの配布数のところを見たのですけれども。","respondent":"築山障害者施策推進担当課長","answer":"６,４６２というのは、障害福祉サービスを使っていない方も含まれておりまして、手帳を取得しているけれども、特にサービスは使っていないという方も入っております。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"ということは、いわゆる品川区が考える障害者の方の全数調査ということでの認識でよろしいですか。","respondent":"築山障害者施策推進担当課長","answer":"障害福祉サービスを使っていらっしゃる方は全員に行いまして、サービスを使っていない方、手帳を持っているだけの方については、抽出で行っております。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"どんなサービスがあるのかということがわからなくて受けられないという方もいらっしゃるのではないかなと思って、そういうことから考えたら、当事者の方々が計画を知ることで、障害者サービスの中身や実態がわかるということと併せて、共生社会を目指すということを掲げておりますので、障害者理解の促進ということでも説明会を位置づけてやるべきではないかなと私は思うのですが、いかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"よって、必要な方は皆様、相談につなげているという認識です。説明会につきましては、先ほどもご説明させていただきましたとおり、パブリックコメントですとか障害者団体ヒアリング等を実施する中で、ご意見等をお聞きしながら進めていきたいと考えております。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"障害者の方々が社会で差別なく当たり前に生活できるという共生社会をつくっていこうということを掲げているわけですから、区民理解という点からもやったほうがいいのではないかと思うのですけれども、その点どうかということ。そういう点でいえば、区民説明会をやらない理由は何かあるのでしょうか。やってほしいと当事者が求めているのに、やらない理由というのは何かあるのか、その点についても伺います。","respondent":"築山障害者施策推進担当課長","answer":"説明会を実施しない理由というご質問がございましたが、相談については、障害のある方それぞれ適切にどのようなサービスを求めているか、個々の相談に応じて対応しているところですので、説明会という形で実施するのではなく。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"行わない理由が、それではちょっとわからないですよね。それから理解促進というのも、例えばいろいろな集いがあったり、障害者の週間があったり、いろいろありますけれども、そういうものと併せて、この説明会がさらにそれを深めるという、もう１つの機会として使えるのではないかなと思うのです。そういう本当にいい機会になるのにもかかわらず、やらない理由がよくわからないのです。","respondent":"築山障害者施策推進担当課長","answer":"理解促進というところでいきますと、先ほどもご説明しましたとおり、さまざまな事業を展開していますので、そうしたイベント等にご参加いただくとか、または差別解消法の例でいきますと、障害者差別解消法ハンドブックの配布等もしております。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今まで申し上げたような観点からも、説明会はぜひ行っていただきたいと改めてお願いしておきたいと思います。そういうところでは、オンラインでも結構ですので、やり方についてはコロナに合わせた形で検討していただきながら、ぜひ説明会はしていただきたいと要望させていただきたいと思います。それから続けて、障害福祉計画のほうは、皆さん、いいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"いいですか。では、すみません、障害福祉計画のほうも質問させていただきたいと思います。今回、１ページの「計画策定の趣旨」というところで、障害者権利条約を批准して、それから法整備はこうされてというところを、私は３年前のときにぜひそういうところを入れていただきたいとお願いしていたのですけれども、それがしっかりと明記されて、ありがとうあります。その点をお願いします。","respondent":"築山障害者施策推進担当課長","answer":"素案の閲覧につきましては、配布もありますし、ホームページからもご覧いただくことができます。希望がございましたら、障害者福祉課からお渡しすることも可能です。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それから全体のところで、策定委員会を既に３回されていて、資料から議事録からいろいろとホームページに載せていただいていて、１２月２２日の３回目も踏まえた形での計画と考えていいのでしょうかというのが１点と、それから、そこの資料で出されていたものに、国の障害福祉計画および障害児福祉計画に係る基本指針についてというのがありまして。","respondent":"築山障害者施策推進担当課長","answer":"こちらでは強度行動障害というところで、高次脳機能障害の記載はございませんが、高次脳機能障害も含めて、専門的人材の育成を図るという考えです。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"高次脳機能障害については、家族会でしたか、団体の皆さんもいらっしゃいますし、さまざまな要望も出されており、本当にもっと充実していただきたいという要望を聞いておりますので、ぜひ高次脳機能障害の支援体制の充実というところも入れていただけたらと思います。その点をお聞かせいただけたらと思います。それから、何点かお聞かせください。","respondent":"築山障害者施策推進担当課長","answer":"それから今期の主要テーマのところですが、３４ページにわかりやすく一覧で記載させていただいているところですけれども、今後どういったことに取組まなければいけないかといったときに、まず「（１）安心して暮らせる地域生活の支援」というところでは。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから３５ページの一番下なのですけれども、地域生活支援拠点、拠点機能の充実ということで、先ほど言われた親亡き後を見据えてというところで、地域生活支援拠点としてのあるべき姿を地域生活支援拠点検討会において検討し、必要な機能の充実を図りますと書かれているのですけれども、この地域生活支援拠点検討会というのは、自立支援協議会の分科会としてつくられている組織ということなのでしょうか。","respondent":"松山障害者福祉課長","answer":"それから３５ページの地域生活支援拠点検討会ですが、こちらは、地域生活支援拠点が区内に３拠点あります。３拠点と申しますのは、心身障害者福祉会館とぐるっぽと福栄会の３拠点です。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひ医療的ケア児だけでなく、者のほうも充実させていただきたいなと切実に思っていまして、そこのところの確認と、それから2)のところに黒丸が５つあって、さまざまな拡大だったり充実ということが書かれているのですけれども、この中に人工呼吸器をつけた医療的ケア児、これは医療的ケア児も者もなのですが、通所とかショートステイの検討というのをぜひ入れていただけないかなと思ったのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"書いてありましたか。２カ所目。そうですか、すみません、見きれなくて。そこのところを思いました。とりあえず、いろいろ細かくごちゃごちゃとすみませんけれども、今のところをお答えいただけたらと思います。","respondent":"松山障害者福祉課長","answer":"それから２点目の人工呼吸器の方についてですが、人工呼吸器の方によってその状態像がかなり大きく左右されるものと認識しておりますので、こちらに文言として入れるかどうかにつきましては、検討という形にさせていただければと考えています。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"６６ページの放課後等デイサービスなのですけれども、これは需要もすごく増えているし、１人あたりの日数も、令和元年は６日なのが、令和３年には７日、令和４年には８日、令和５年には９日ということで、１カ月あたりの日数もトータルでこれだけどんどん増えていくということになっていくのですけれども、事業者の誘致・確保ということでの整備を進めていきますということなのですが。","respondent":"松山障害者福祉課長","answer":"初めに、医療的ケア児・者の支援関係機関連絡会の開催見込みについてのお尋ねです。今、実際に委員長と相談を進めているところです。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。グループホームですけれども、利用者ニーズの把握に努めながらと書かれているのですが、この把握は、特別養護老人ホームみたいな形で申込書をとっていない中で、どういうふうに把握されて、今、待機者はどれくらいいるのか、そこのところを教えていただきたい。","respondent":"松山障害者福祉課長","answer":"現在のところ、グループホームに入りたいご希望については、計画相談の相談員あるいは地域拠点の相談員がアセスメントをする中で、ご本人とご家族から把握しています。昨年１０月時点での数になりますけれども、施設入所とグループホーム合わせて大体４２名となっております。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ありがとうございました。そうすると、１０４人は他の自治体のグループホームに入られていると考えていいのか、その確認をお願いしたいと思います。それから、それを令和３年から一気に何倍にも増やしていくということなのですけれども、これだけの計画を組めるような体制整備をどういう形でしようとしているのかということについてもお聞かせいただきたいと思います。","respondent":"松山障害者福祉課長","answer":"６７ページの障害児の計画相談なのですが、ここの数字は請求ベースの数字となっております。３月にもう１カ所できるので、８事業所という予定ですので、体制整備については、このように区が計画相談事業所を増やすということ、あと。区内のグループホーム入所者については、８８名の方が入所されておりますので、８８名以外の方については。","id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"相談支援事業所とかも本当に少ないところから出発したのが、さまざまなご努力によってかなり増えてきましたし、まだまだグループホームとか足りない部分もありますので、これから本当に充実させていっていただきますようにお願いして、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"４１ページの「障害児の地域社会への参加や包容（インクルージョン）」のところですけれども、上の３行で、「連携して支援する体制を構築し」とあるのですけれども、保育所等訪問支援は児童福祉法による障害者支援なので、手帳を持っている子とかという話になると思うのですが、その前というか、そういったことがなくて、その境界だったり、少し配慮が必要な子とか、そういうお子さんたちを含めて。","respondent":"松山障害者福祉課長","answer":"委員お尋ねの４１ページの保育園等、関係機関との体制ですけれども、今現在、区の中で稼働しているのは、障害者福祉課が主催となってやっております、地域自立支援協議会の子ども支援部会というところが動いておりまして、そちらの関係機関としましては、教育委員会の方ですとか。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"意見","question":"今お話があったように、そういう組織はあるのですが、今後の課題というか、どうやっていこうということを今検討されているということなので、また機会を改めてお尋ねしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"西村委員","kind":"意見","question":"本日、結論を出すで、不採択でお願いいたします。さまざまに考え、取組んでいただいていることが理解できました。パブコメに関しましては、昨年から品川区の公式ＬＩＮＥアカウント等もありますので、こちらの活用などもご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"意見","question":"本日、結論を出すで、不採択でお願いいたします。通常の手続きにのっとって、一定の方のご意見を聞かれているということで、まさにこれからパブリックコメントをされるということで、陳情自体はパブリックコメントの前にということですが、これからスタートするということもありますし、今回は不採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"渡部委員","kind":"質問","question":"今回といいましょうか、この厚生委員会で、福祉計画をつくっていくという中で、前回から比較しても、団体の方を７団体ですか、委員としてご意見を伺えるようであったり、私自身、全数アンケートの中で、あれだけの二千何百という数字だったり、四十何％返ってきているなんていうのは、さまざまなアンケートの中でもすごい数字だなと思っていて、それが反映されているわけですから、立派な計画となっている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"おくの委員","kind":"意見","question":"本日、結論を出すで、採択でお願いいたします。最も大事な計画の当事者の方に十分納得いただいて計画は定めるべきだと思いますので、説明会は一番重要な手続きだと思います。採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"質問","question":"本日、結論を出すということで、不採択でお願いします。ほかの委員の方もおっしゃっていましたが、策定のときには７団体を含めたあれですが、今度、１３団体に拡大してお話を伺うわけで、そこの中で実際に障害をお持ちの方あるいはそのご家族等のご意見を丁寧に伺っていただくこと等が大切なのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]},{"id":"topic-04","title":"を再度聴取いたします。 それでは、(1)「品川区成年後見制度利用促進基本計画（素案）」に係るパブリックコメントの実施","agenda":"を再度聴取いたします。 それでは、(1)「品川区成年後見制度利用促進基本計画（素案）」に係るパブリックコメントの実施","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"ご本人の人間としての尊厳が最後の最後まで担保されるというのが一番大事なことだと思うのです。だから、その点がどうやって担保されているのか、最大限に担保されているのかということが大事だと思うのですけれども、その２点について、大きなところで伺っておきたいと思うのですが、いかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"この計画の中では、そういったこともしっかりと担保できるような考え方をまず示すということで、この中で全てを解決できるということではないのですけれども、例えば３５ページに、「不正防止効果」、それから順番が逆ですけれども「意思決定支援」。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今まで成年後見制度は、品川区は随分前から社協の中に成年後見センターをつくられて、そこに相談にいって、そこでいろいろやっていただくという状況で、私なんかもいろいろとお世話になってきたなと思うのですけれども、今度は地域連携ネットワークをつくっていくということになっていくと、今までは社協の成年後見センターだけでやっていたのかなと思うのですけれども。","respondent":"寺嶋福祉計画課長","answer":"結論から申し上げますと、品川区の今までの取組みについて、このスタイルは既に十分とれているというのがあるのですけれども、今回、国の示した法の中で、まず計画にしっかり落とし込んでいくということで、品川区の考え方としては、もちろん１００％。","id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうすると、この協議会というのは、今も既に協議会というのはあって、成年後見制度についてさまざま、協議会がこういうふうに実際に動いているということ、それとも、高齢者の方がいて、成年後見を使うということになれば、もちろん介護保険も使えますし、いろいろなところで連携し合いながらやっていくことになると思うのですけれども、それが協議会ということで位置づけられるのか、それとも。","respondent":"寺嶋福祉計画課長","answer":"方向性を決めるとか、上がってきたケースについて、学識経験者の方、医療機関の方、弁護士の方に入っていただいている運営委員会というものがございまして、こちらで判断していくということを定期的に行っているのですけれども、今の想定では、協議会につきましては。","id":"exchange-051"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そういうことでいうと、いろいろなところで出しているものを見ると、本人の意思決定や心身保護等の福祉的な観点を重視した運用にする必要があるとか、そういうところが課題みたいな形で出ていたりするのですけれども、そういうところは、とりあえず品川区の場合は、今はクリアされているという形になっているのかということなのですけれども、それから、特に、今までずっとされていて。","respondent":"寺嶋福祉計画課長","answer":"それから実質的な話としては、例えば運用上は取組むのですけれども、先ほど言った不正防止みたいな話については特にどこかに記載があるものではなく、今回計画の中にそこをしっかり書き込んでいくとか、それから社協がやっている活動というのは。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問","question":"今回、１９ページを見ると、中核機関は、品川区と品川区社会福祉協議会の２本立てになっているのですが、いろいろな事務局機能をつかさどるとか、次のページにいろいろ書いてあるのですが、これは普通のパターンなのですか。自治体が中核機関もしくは、民間の社協、成年後見センターと名づけられているものが中核機関になるというのはわかるのですけれども、この２つが中核機関というのは普通なのかどうか。","respondent":"寺嶋福祉計画課長","answer":"中核機関の位置づけにつきまして、これは国が示している内容としては、区市町村単位に設置して、設置主体は区が望ましいという表現をとっているのですけれども、実際には恐らく多くのところが直営ではやれないので委託でやったりするのだろうなという想定はつきます。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問","question":"ということは、中核機関に自治体が望ましいと国が言っていて、それと２つ並列して、並べているというやり方は、割と独特な感じと捉えておいていいのでしょうか。","respondent":"寺嶋福祉計画課長","answer":"ただ、恐らく行政が直営的に、委託先とどこかというのはあるかもしれませんけれども、品川区と社協みたいな形で、行政がしっかり前に出てくるというところはそれほど多くないのかなという気はして、ごめんなさい、推測の域でしかお話しできないのですけれども、ただ。","id":"exchange-054"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"西村委員","kind":"質問","question":"１個お伺いさせてください。なかなか出向いていただくのが現実的に難しい中で、2)のほっとサービスの部分は、通常どのようなお困り事をシニアの方々からご依頼されていて、コロナになってからはどんなご依頼があるのかとか、もしおわかりだったら教えていただけますか。","respondent":"寺嶋福祉計画課長","answer":"要介護認定を受けている方については、在支につなぐとか、それから、専門性の高い、ちょっとした技術が必要なものについては、例えばさわやかサービスとかシルバー人材センターにつなぐといったことをやっているということで、こういったことをやっていたのですけれども。","id":"exchange-055"},{"speaker":"西村委員","kind":"質問","question":"さわやかサービスは、お掃除とかを頼んでいらっしゃる方が多いのかなという印象だったのですけれども、高齢者の方にとって、ほっとサービスとどういうすみ分けになっているのですか。","respondent":"寺嶋福祉計画課長","answer":"ほっとサービスの基本的な考え方として、さわやかサービスもボランティア的な要素は強いのですけれども、住民同士の助け合いということで、支援員がやっていることになりますので、ぎりぎりどっちかと言われると難しいところがあるのですけれども。","id":"exchange-056"},{"speaker":"高橋（し）委員","kind":"質問","question":"もう１つは、最後の健康づくり云々のところの、右側のページの（２）外出自粛に伴う云々のところですけれども、なかなか高齢者の方が回覧板とか広報紙、ホームページは見にくいのですが、先ほどの支え愛ほっとステーションのステーション便りとかにも、あまり外に出られないときはこういうことをしたらいいねみたいなことがきっと載っているのだと思うのですけれども。","respondent":"寺嶋福祉計画課長、菅野高齢者地域支援課長","answer":"支え愛・ほっとステーションのコーディネーターから、実際にどれくらいの件数が、例えば在支につながったかという細かな数字は、申しわけありません、そこまで把握できていないのですけれども、考え方としては、通常。２つ目の、チラシをつくってステーション便りに載せているかどうかというお話ですけれども、いろいろと区のホームページや広報紙等、さまざまなツールを活用してというお話をさせていただいたのですが、今のところ。","id":"exchange-057"},{"speaker":"高橋（し）委員","kind":"質問","question":"それぞれありがとうあります。要支援高齢者の発見という言葉がいいかどうかはあれですけれども、そういう方を見つけて支援につなげていく、重要な役割と今伺ったので、期待していますので、よろしくお願いします。広報のほうは、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"渡部委員","kind":"質問","question":"ちょっと簡単に、最後の健康づくりのところですけれども、このコロナ禍の中でというところで、右側の２番の表で、休みはあったけれども再開してという、それはわかったのだけれども、再開したところで、実際の参加者はどんな感じなのか教えてほしい。","respondent":"菅野高齢者地域支援課長","answer":"今後ですけれども、やはり私たちもどうすれば少しでも多くの方の心身機能の低下を防げるのかと考えているところなのですが、コロナのこともありますので、引き続き定員を減らすなどいろいろと工夫をしながら事業を展開しなくてはいけないので。","id":"exchange-059"},{"speaker":"渡部委員","kind":"確認","question":"ありがとうございました。だけれども、確かに身体機能の向上といいましょうか、体を動かして、本当は出てもらいたいのだけれども、出られなくなってしまったりして、でも、体を動かしてほしいと、くしくも課長がおっしゃいましたけれども、品川区にはケーブルテレビがあるのだから、そこで１０分でも１５分でも高齢者体操番組みたいなものをぜひ何か仕掛けてほしい。答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ほっとサービスですけれども、１回３０分２００円ということですが、これもボランティアの方の組織が大変と伺っていたのですけれども、今、ボランティアの方は、１つのほっとステーションで十幾つかの町会があると思うのですが、何人ぐらいで組織されているのか、その人数も教えていただきたいと思います。そこら辺も教えていただきたいと思います。その点、お願いします。","respondent":"寺嶋福祉計画課長","answer":"ご本人が嫌がっているので、これは難しいということです。それから、介護認定を受けている方。アウトリーチをした結果、介護認定を受けている方もしくはその後受けた方については、在支のほうになるので、そこで外れるということです。","id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"健康づくり・介護予防の取り組みですけれども、いろいろな取り組みをされていますが、これは全て介護保険の地域支援事業にあたるもの、介護保険でやっているものと考えていいのでしょうか。それとも、一般財源でやっているものがあれば、それは何なのかというのを教えていただきたいと思います。","respondent":"菅野高齢者地域支援課長、寺嶋福祉計画課長","answer":"３点ご質問いただいたと思います。１点目の一般介護予防事業、今回ご紹介させていただいた部分ですけれども、全て介護保険の地域支援事業の中での実施事業ということでご紹介させていただいたものです。先ほどの地域支援員の人数の関係ですけれども、令和２年度の数字では、１,１８６名という人数になっていまして、こちらの資料に書いてある１,１９１件。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１,１８６名ということは、１事業者あたり１０名……、違うか、１００名……。１事業者あたり１００名弱みたいな感じで、かなりのボランティアの方を組織できているということで、でも、実際は件数としてはそんなに多くない感じなのですかね。わかりました。","respondent":"寺嶋福祉計画課長","answer":"地域支援員は、もちろん定期訪問だけの役割ではなく、やっている件数としてはこうなるのですけれども、実際の活動としては、先ほどの地域づくりの中の１つに、下のほうにコロナ禍でできなくなったときの折り紙付きカードとか返信用はがきとかいろいろ出ていますけれども。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/779921?Template=document&Id=3586#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":62642,"voices":177}},{"id":"r03-20210119-8","meetingId":"r03-cm01","date":"2021年1月19日","dateIso":"2021-01-19","committee":"建設委員会","time":"午後 １時００分～午後 ５時０６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件抜き出しています。","topics":[{"id":"topic-01","title":"東京都市計画 都市計画区域の整備、開発及び保全の方針の変更","agenda":"東京都市計画 都市計画区域の整備、開発及び保全の方針の変更","exchanges":[{"speaker":"田中委員","kind":"意見","question":"方針（案）の中の４ページのところの「デジタル技術を生かした都市づくりの推進」の「スマート東京」の部分なのですけれども、ＡＩやＩｏＴ、ビッグデータの基盤となる情報通信ネットワークということで、多分５Ｇの話などが関係するのかなと思うのですけれども、５Ｇのアンテナ基地局の設置場所について。","respondent":"鈴木都市計画課長","answer":"区の所管全体とすると、例えば情報推進課等がありますが、そうした意味で区が把握しているかというところですと、そこまで確認しておりませんので分からないのですが、都市計画課、私としてその基地局を把握しているかというお尋ねであれば、私としては把握していないところです。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ東京都のほうに区内での設置場所について把握できるように情報提供していただきたいというのと、ぜひその情報を公表していただきたいということを求めたいと思います。健康面についても心配されるところがあるので、ぜひ把握と、そして公表をしていただきたいと要望いたします。でそれに関してご答弁いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"最後のトランジットの対応の部分は、次の便までの数時間、６時間だったりとか、その少しの時間ですぐに戻れる、電車１本で来られる範囲での、旅行者の方たちが気軽に楽しめて戻れるようなところということで、この地区という話をしたので、ぜひそういった観点も考えていただければと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"このＡ３の資料の裏面のほうに書いてある「天王洲」とか「北品川」とか、ここに書いてあるのは駅ですか。例えば「品川」と書いてあるのですけれども、品川のどこを差しているのですか。これは、品川駅周辺という理解でいいのでしょうか。それから、西大井のほうなのですけれども、これ、現状がこういう評価なのでしょうか。それとも、これから先、こういうふうにしていくということなのでしょうか。","respondent":"鈴木都市計画課長","answer":"ご指摘のとおり、品川、大森、状況によっては駅周辺ということになりますと目黒もまたぐですが、ある意味、この記載をしていく中で、東京都が広域的な計画として位置づけられて、その方向性を示しておりますので、当然。西大井ですが、西大井については、記載のとおり、駅前広場、一定程度、ＪＲ横須賀線、新駅ができるときに、いろいろ地区計画、都市計画を定めて、駅前広場ですとか公園、都市基盤を整備してまいりました。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"区界に関しましては、東京都が調整を図るということで、統一性のある形で進められているのだろうなというふうに思いますが、うまくコラボレーションできればいいなというふうに思っていますので、お願いしたいと思います。それと、西大井のほうですけれども、あそこの駅ができて、ただ、あの駅も反対側に改札口をつくってほしいとか、いろいろ意見があるわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"のだて副委員長","kind":"質問","question":"そうすると、都市計画などのコントロールがきかなくなってしまうのではないかと思うのですけれども、区の受け止めはいかがでしょうか。計画方針の改定にあたって、区への意見照会というのはあったのか、そしてまた、どのような意見を出したのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"ですので、どういったものを返しましたかということであれば、例えば立会川・勝島、先ほどご説明したものは、区としてまちづくりビジョンも作っておりますので、ぜひ都の上位計画のほうでも位置づけていただきたいというところが意見としてお返ししたところのほかに。","id":"exchange-006"},{"speaker":"のだて副委員長","kind":"質問","question":"そうすると、区の意見としては、大体今までどおりで、特に立会川・勝島のところを追加してほしいという意見だったのかなというふうに思います。そうしたもとで、やはりこのコロナも人が多いところが感染者も多いということになっておりますので、東京一極集中のあり方が根本から問われているのではないかと、変えていかなければならないのではないかというふうに思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"コントロールができないというよりも、そうした意味での記載だです。それから、一極集中ですが、今回、東京都のこの改定も、コロナ禍を踏まえたまちづくりの基本的な考え方、方向性は記載しています。","id":"exchange-007"},{"speaker":"のだて副委員長","kind":"意見","question":"結局、都市の集積は進めていく。そうしたことが東京一極集中にもつながっているということになりますので、そこを変えていかないと、このコロナ禍のもと、そしてその後の社会を考えていく中でも、そういった考え方が必要だというふうに思いますので、コロナ（禍のもと）での再開発ですとか、特定整備路線等の巨大道路を進めていくというのは、やめるべきだというふうに私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それはどうしてかというと、羽田空港から飛び立つのが１２時台が結構多い。だから、そういう意味で言うと、それこそ競馬場の活用とか、ぜひそれは地域の方との時間の問題もあるのは重々分かっているのだけれども、そういうことも踏まえた中で、もし計画を練っていくのであれば、そういうものも品川区のマスタープランなのだから、それも１つのまちづくりになるわけだから、ぜひそれはお考えいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"これ、どういうような考え方で書き違いがあるのか、教えてください。逆に上が国際ビジネス交流ゾーンであれば、やっぱり南部という地域、エリア指定をするのではなくて、ゾーニングに該当するような表現があってしかるべきだと思うのですけれども、どういう取り扱いをしたのか、教えてください。","respondent":"鈴木都市計画課長","answer":"変更前といいますか、この計画の変更以前は、センター・コアですとか、ちょっと呼び方が違う形でいろいろ東京都のほうでも元の計画はゾーニングしていたのですが、より大きく環状７号線の内側と外側でまず大きく分けましょうというところで。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"これはあくまでも都の。もちろん概要版だから都のものをまとめられた部分だろうけれども、いずれにしても、もうちょっと都のほうでも、上にゾーニングしてあるのだから、南部というのはちょっとちくはぐな気がしますので、そのうちゾーニングも決まってくるのでしょうけれども、そこのところにちぐはぐさを感じたので質問させていただきました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"東京都市計画 都市再開発の方針の変更","agenda":"東京都市計画 都市再開発の方針の変更","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"以前は「国庫交付金交付要件の一つに位置付けられている」ということだったのですけれども、ここの部分が、交付金の要件が、どういったことから変わって、どういうふうになるのかというのが、ちょっと勉強不足で教えていただきたいと思うのですけれども。","respondent":"多並都市開発課長","answer":"もう少し前ですと、かなり以前の、この前の話になりますけれども、そのときは、交付金ではなくて、個別補助金といいまして、国がこの内容に従った形で事業をやってくださいというような考え方の交付要綱にはなっていたのですけれども。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"ですので、恐らく先ほどの答弁の中では、そこはある程度、東京都も認識をしていただいているのかなという期待は持っているのですが、そこはどうなのでしょうか。それとも、従来型の整備をして、そこにマンションを建ててしまうみたいな、そういう手法がやはりまだまだ主流なのか、それは東京都はどういう考え方を持っておられるのでしょうか。","respondent":"鈴木都市計画課長","answer":"今、委員のほうから「従来型」という言葉で表現をいただきましたが、基本的な考え方は、従前の計画も大きな建物を建てることを第一に据えて計画や方針が作られてきているわけではございませんで、今ご紹介いただいたまちづくりは、密集だとか、みどりだとか、景観だとか。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"イメージとして再開発というとビルという頭がどうしてもあるので、それでいいのか。そうなったときに、そこは東京都と調整を図りながら、品川区の特徴はこうだからと強く言って、補助金を別枠で作ってくれみたいな、お金も出してくれみたいな状況まで踏み込んで言える状況になってくれたらいいなと思うのですけれども、その辺はいかがですか。","respondent":"鈴木都市計画課長","answer":"国等の交付金、補助金等の中身も、景観であったり、みどりであったり、それぞれの地域が抱える課題解決のために、１種類、建物を建てるための補助金だけがあるわけではございませんで、様々なメニューが用意されてありますので、それをしっかり区としても使いながら。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"地域の方々は、いろいろな手法があるというのが分からない部分があると思うのです。そういうことをサポートするのが区の役割だと思っているので、ぜひそういう形で。主体は地域住民というふうに思っておりますので、ぜひその辺は東京都とうまく調整を図って進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"先ほどの交付金の部分は、難しくて何と質問していいか分からないので、また別の機会にもう１回まとめて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"４８ページに絵がありますが、Ａ３の資料の裏面を見ていただいて、今ご紹介いただいた４８ページに描いてある絵が、裏面の２ページ目の下段のほうに、太い線で、横線で描かれてあります。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"不勉強で教えていただきたいのですが、都市再開発の方針が変更されました。そのときは例えば行政の判断で、どこの地域だろうと、やると言ったらやれるという判断でいいのですか。ほかの話だと、地域からいろいろ話があってやっていくではないですか。２号再開発は行政が大分絡みますね。こういうものはここで方針が変わったとしても、行政がやると言ったらやれるという理解でいいかだけ教えてください。","respondent":"多並都市開発課長","answer":"ただ、法の中で、やはり今後の再開発の方針でどう進めていくべきかということを世の中に知らしめて、計画的に民間の開発であったり、まちの動きが活発に動くように、そういう形で誘導していくための１つの方針というところがありますので、そういう位置づけというところです。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問","question":"誘導地区だとか、いろいろな地区はあるのだけれども、そうではなくて、再開発自体を２号でやるというと、行政主導でやるみたいな話ではないですか。１号の向こう側があるとして、ＪＲとか、こっちの周りもあると、行政側が主導で、これは２号再開発で一緒にやるとかあるではないですか。西大井だったり。関係ないのですか。行政がやると言ったら、それはできるという理解でいいのですか。","respondent":"多並都市開発課長","answer":"失礼いたしました。今のは恐らく第一種市街地再開発事業と第二種市街地再開発事業の違いかと思います。ただ、そういう事業を１つの地区の中で組合せながら進めていくということはあり得るかと思いますので、そのためには、やはり地区計画であったり、そのような切り分けをその自治体の中でしながら、計画的に連携しながら進められることで。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"今のお話、第二種市街地再開発事業についてなのですけれども、具体的に、イメージが湧かないので、こういうふうにやりましたと何かあればありがたいのですけれども。ちょっとイメージがつかないのです。品川区で第二種市街地再開発事業で行政主導で開発を進めているところはあったのですか。","respondent":"多並都市開発課長","answer":"区ではありません。私が確認してきた中ではないと認識しています。ほかの自治体とかであるかといいますと、稀に地方のほうである場合がありますけれども、都内で、区部でというのは、私、今のところ、聞いたことはないです。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"今進めようとしている品川区の中での再開発の中で、第二種市街地再開発事業というのはないという認識でいいですか。","respondent":"多並都市開発課長","answer":"今はなく、地域の方と一緒につくっていくということで今は進めているところであります。","id":"exchange-020"},{"speaker":"のだて副委員長","kind":"質問","question":"区としては、どのように考えているのか。先ほどとも一緒ですが、照会とかがあって、どのような意見を出したのかというところを伺います。","respondent":"多並都市開発課長","answer":"この考え方ですけれども、品川区としては、まず全体的には都市再開発方針というのは、５ページで示されているこの方針に従って、全体的な考え方の中で都とも協議しながら進めているところであります。","id":"exchange-021"},{"speaker":"のだて副委員長","kind":"質問","question":"今回、そういった照会などもあって、都ともやり取りして成ったということでした。今回はコロナの中でこういった再開発を進めていくというのは、やはり見直していくべきだと。そうしたもとで、今回、広町地区も加えて対象拡大をしていくということはやめるべきだというふうに思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"別紙２のそれぞれの特に再開発促進地区のところでは具体的な記載がされてあります。その１１地区すべてにおいて、超高層の建物を建てて開発を進めていくという記載がされているわけではございません。","id":"exchange-022"},{"speaker":"のだて副委員長","kind":"質問","question":"やはりそうした環境問題からも、この超高層再開発を進めるという考えは変えていくべきだというふうに、持続的な社会をつくっていくためにも、そういった考えを変えていくべきだと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"そういった意味でも、この計画に位置づけるべきではないのではないかですが、繰り返しになりますが、この計画が建物の再開発のための、高い建物を建てるためにすべてが記載されているわけではございませんで、先ほど、都市開発課長からもご説明しましたが。","id":"exchange-023"},{"speaker":"のだて副委員長","kind":"質問","question":"どういう個々のまちづくりの解決をしていくかというのはそれぞれだということでした。ということと、カーボンマイナスのお話がありましたけれども、そうすると、実際には、開発する前の排出量と、開発した後の排出量は、比べてしっかりマイナスになっているということなのか、その具体的なデータがあれば伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"その個々の建物について、開発に限らず一つひとつの建物がすべてその方向性に沿ってやっているかというと、考え方がしっかり示されているというのは間違いない話でございまして、何か総量的なものが計画の中で示されているというのは。","id":"exchange-024"},{"speaker":"のだて副委員長","kind":"意見","question":"総量でいくと、ほかのものとかも入ってきてしまうのかもしれないので、そこの開発の前後でどうなったのかということをつかまなければ、そして個々の計画がマイナスになっていかなければ、やはりそれはマイナスになっていかないということになりますので、そういった環境の面からも言って、やはりこの再開発を進めていくというのはやめるべきですし、この方針には反対をしたいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"田中委員","kind":"確認","question":"１点だけ確認をし忘れてしまって。先ほどの都市計画区域の整備、開発及び保全の方針の中と、今の都市再開発の方針、両方の案の中で、リニア中央新幹線の整備のことについて文言があるではないですか。調布市の外環道の陥没のこともありますし、ここの文言、リニアのことについては、東京都と品川区のほうで、方針（案）に入れる際に、どういったお話があったのかなというところを伺いたいのですけれども。","respondent":"鈴木都市計画課長","answer":"これは都の計画の中で都の広域的な視点から記載されているものだというふうに認識しているものです。それから、そのご紹介いただいた陥没の件を受けて記載を改めた、あるいは記載を今改める方向で考えているというところは、今現在のところは区としては聞いてございません。","id":"exchange-026"}]},{"id":"topic-03","title":"戸越公園駅周辺まちづくりビジョン駅前広場計画編（素案）の策定","agenda":"戸越公園駅周辺まちづくりビジョン駅前広場計画編（素案）の策定","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"今後のスケジュールのところで、素案の説明に対して対象が関係町会および関係団体へ説明ということだったのですけれども、関係町会、関係団体の、そこに当てはまる、その町会などをお知らせいただきたいと思うのですけれども。","respondent":"中道まちづくり立体化担当課長","answer":"こちらのほうでは、戸越公園駅付近のまちづくり協議会がありますので、そちらのほうと、また、再開発も進められている組合がありますので、そちらにも説明に行きたいというふうに考えてあります。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"説明に行くというご説明だったのですけれども、では、その町会に足を運んで説明に行かれるということで、説明会が行われる日程とかは、そこの地域住民の方へのお知らせということはないのでしょうかということと、あと、先日、一般質問でもお話しさせていただいたのですけれども、都市計画法に則ってきちんと地域に限らず、対象と書かれていますけれども。","respondent":"中道まちづくり立体化担当課長","answer":"今回の戸越公園駅周辺まちづくりビジョン駅前広場計画編ですが、昨年度策定しました基本計画編の中の駅前広場に限定的な計画です。ですので、今回は地域限定に特化して説明をしていきたいというふうに考えてあります。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問","question":"地域に限定したお話ということだったのですけれども、資料の中で、ここの駅を利用されている方の割合が、ここもあとで聞こうとは思っていたのですけれども、定期利用者が４７％と半分以下であるという、この「定期」という意味もあとで伺いたいのですけれども、地域の方に限らない利用者の方たちがいるのかと私は読み取ったのです。","respondent":"中道まちづくり立体化担当課長","answer":"定期外の方も半分以上いるというところで、皆さんにこういったことを説明したほうがですが、確かにこの戸越公園駅というのは、戸越公園もありますし、そういった遊びに来る、または商店街を活用される方も非常に多いというところではありますが、まず駅前広場をつくるにあたって。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"概要版のところになるのですけれども、ご説明の中で、歩行者と自動車等が交錯するおそれがあるということなのですけれども、どのように交錯するおそれがあるのかといった部分、具体的な交錯場所をお知らせいただきたいということと、また、次の段落で、高齢者や障害者の方にとって駅へのアクセスが困難な状況にあるということだったのですけれども、高齢者や障害者の方たちから。","respondent":"中道まちづくり立体化担当課長","answer":"バスも、今、バス停まで約５００ｍ離れているといったところであったり、８ページでは、タクシーを拾うところなのですけれども、国道や都道まで３００ｍ、１８０ｍといったところで離れている、こういったところで、今、やはり戸越公園駅は、なかなか年配の方たちであったり。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"高齢者や障害者の方たちから、どういった声が届いているかというご答弁がなかったと思うので、そこをお知らせいただきたいと思います。","respondent":"鈴木都市計画課長、中道まちづくり立体化担当課長","answer":"今、例示としまして旗の台駅周辺の歩行者の観点のご質問をいただいたわけですが、旗の台駅周辺地区については、大井町駅周辺地区の後にバリアフリーの基本的な計画を定めておりまして。高齢者や障害のある方たちの声というところで、まず１つは、昨年度行いました基本計画編のパブリックコメントの意見の中に、「戸越公園駅が高架になった場合、駅前広場を作って欲しい。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"旗の台駅周辺のことでご答弁ありがとうございました。旗の台駅周辺とかこの戸越公園駅周辺に限らず、品川区内全体のバリアフリーというところを考えてほしいというのは、たしかこの前の決算特別委員会のときにもお話しさせていただきました。ですので、ぜひ広い範囲で説明をしていただきたいというのと、あと、地域の方は特にというのはすごく分かります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"西本委員","kind":"確認","question":"スケジュールだけ確認をしたいと思います。高架化になるのと、特定整備路線もあるわけです。全部やるのですね。だから、進め方が何から始まって、どういう進め方をするのか。あそこのところはすべてが同時進行ではないとこれが出来上がらない、将来的な広場をつくるにしても、スペースがなかったら広場はできないわけであって、具体的にはどう進められていくのですか。","respondent":"中道まちづくり立体化担当課長","answer":"連続立体交差事業を早期に事業化したいというところもありまして、今現在、こういった駅前広場の考え方とか、または昨年度ございました要望書等で活動しています。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"それだとちょっと残念なので、見立てはあるのでしょうか。あそこは開発も始まってしまっているので、片や開発が始まっていて、だけど、あれが何ができるのだろうなというふうに思いつつも、でも、立体化になって、踏切も解消になって、それで広場もできてというのが同時にできるわけではないですか。そうすると、やはり早くつくってほしいという思いも強くなってくると思うのです。","respondent":"中道まちづくり立体化担当課長","answer":"この戸越公園駅周辺の連続立体交差事業の事業性ということなのですけれども、２０１６年度（平成２８年度）に、こちらの路線が、事業候補区間に東京都の中で位置づけられているというところがあります。","id":"exchange-034"},{"speaker":"西本委員","kind":"意見","question":"なかなか進まないと、がっかり感というか、やはり不安のほうが募ってきてしまうと思うので、皆さんにこういう状況になっていますという情報は発信されると思いますが、いいことであるので、ぜひ皆さんに夢を与えていただけるような情報発信をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"田中委員","kind":"確認","question":"確認で、先ほど、素案の説明は対象の方以外にはしないけれども、今後、広く説明をするといったご答弁があったではないですか。そのタイミングというか、どの時期に説明をするのか。その説明をされるときには、ここはこうしてほしいといった意見が反映されるときなのかというところだけ確認させてください。","respondent":"中道まちづくり立体化担当課長","answer":"その流れとしましては、次に都市計画素案があります。それで都市計画案という流れになってくるのですけれども、そのタイミングで、都市計画決定に向けて説明会を開くです。そのときにまた意見をもらったりというタイミングがありますので、そのときに意見をいただくような形です。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"そのときの都市計画素案の決定についての説明会は、この地域に限らず区内全域に対して縦覧とかも求められるのですねということだけを確認させていただきたいのですけれども。","respondent":"中道まちづくり立体化担当課長","answer":"今度は都市計画決定になりますので、都市計画の窓口のほうで、そうした都市計画資料は縦覧が可能となっています。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"そのときの説明会についても伺いたいのですけれども。","respondent":"中道まちづくり立体化担当課長","answer":"都市計画法の中で、第１６条と第１７条の説明会というものがあります。第１７条のほうでの説明会のときに、区民全員参加可能な説明会が開かれるところです。","id":"exchange-038"},{"speaker":"大沢委員","kind":"質問","question":"お願いしたいのですけれども、緊急事態宣言下ですので、委員の皆さんにおかれましては、やはり委員長の指導のもとに効率的で重複しない、まとまった要点を心得た質問に心がけるよう、指導方、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"この戸越公園駅周辺の問題は地元の問題なので質問させていただきたいと思いますけれども。先ほど来、スケジュールの話がありました。基本計画編のときに既に駅前広場についても聞いているということでしたけれども、やはり今回新たにこの駅前広場計画編というのを作るわけですから、パブリックコメントなどをやるべきではないかというふうに思うのですが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"今後の進め方ですが、連続立体交差事業は東京都が行うという……。","id":"exchange-040"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"そうすると、スケジュールとしては、都市計画素案の段階のところで立体化が進んでいったときに一緒にやっていくということですね。分かりました。そういったところで区としては、どのように利便性というか、必要性を考えていらっしゃるのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"下のほうの将来像ですが、補助第２９号線や補助第２６号線が整備されると、ここが交わる一番近い駅が戸越公園駅になってきて、そういった意味でも、ここは利用する方々、品川区民にとって利用する方々が増えるのではないかというところで、そういった整備をしてまいります。","id":"exchange-041"},{"speaker":"のだて副委員長","kind":"質問","question":"そうすると、直接そこに行けばいいということにもなってくると思うのです。これができることによって来やすくなるというお話ですけれども、やはり駅前広場が再開発の基盤整備のために進められていく、再開発ができれば多くの方がそこに来るわけで、その基盤整備を行っていくという駅前広場になっているのではないかという問題を感じているのですけれども、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"再開発と駅前広場の関係性ですけれども、そこについて直接的な関係は特にございません。ですけれども、再開発事業があれば一定程度の空間は整備されますので、そういったことも併せまして、駅前の一体的な整備というのは考えていきたいというふうに思ってあります。","id":"exchange-042"},{"speaker":"のだて副委員長","kind":"質問","question":"実際に道路整備などが行われて、バスルートも将来的なネットワークのところで必要性があるということでしたが、ここにバスが通る可能性はあるのか、区としてそこのバス停をつくっていくですとか、そういったお考えがあるのか、伺います。","respondent":"中道まちづくり立体化担当課長","answer":"こちらのバスの運行ですけれども、民間のバス会社のほうにヒアリングに行ったところ、通す、通さないというのは、その場での発言ではもちろんないのですけれども、補助第２９号線または補助第２６号線については。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"スケジュールのところで、やはり何回伺っても分からないので、区民意見が確実に反映されるタイミングだけをお知らせください。","respondent":"中道まちづくり立体化担当課長","answer":"都市計画決定をする前に都市計画案の段階で、説明会または都市計画資料の縦覧、意見募集を行いますので、その際に意見をいただければ区のほうに届きます。","id":"exchange-044"}]},{"id":"topic-04","title":"東京都の土砂災害警戒区域等の追加指定予定","agenda":"東京都の土砂災害警戒区域等の追加指定予定","exchanges":[{"speaker":"西本委員","kind":"質問","question":"５０箇所、３８箇所になるのでしょうか、それは公表するのでしょうか。ホームページに公表されるのかということと、それから、１月から住民説明を個別にするということなのですけれども、どういう内容で、どういう対応をしていくのかということを、中身だけ教えてください。","respondent":"長尾建築課長","answer":"こちら、追加指定予定の箇所が指定された後は、土砂災害警戒区域が５０箇所、土砂災害特別警戒区域は３８箇所ということになります。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"住民は何をすればいいのでしょうか。そういう説明の中に建物をどうしろとか、何か具体的な行動を要請されるのでしょうか。","respondent":"長尾建築課長","answer":"ただ、こういう場所であるということを認識していただくとともに、大雨等が降ったときに、そういう崖地に関しての認識を持っていただいて、何かいつもと違うなと感じたときに避難するといったところのきっかけというか、認識をしていただくというところが主になります。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"そうすると、そういう指定をされると、そこの地価とかに影響してきますよね。例えば、危ないからどこかに引っ越そうとかといったときに、当然ながら、そこは危険箇所だということで売れない可能性もあるわけではないですか。そういう場合はどう対応するのでしょうか。","respondent":"長尾建築課長","answer":"建てる場合でも、仮に土砂が崩れたとしても被害が出ないような防護壁を造るであるとか、あと、擁壁そのものを改修して安全なものに造り替えるといったことをすれば、そういった規制については除外されるのですけれども、それについては個別に東京都がご相談に応じていますし。","id":"exchange-047"},{"speaker":"田中委員","kind":"意見","question":"具体的に御殿山小学校の中のどういった面になるのかといったところを知りたくて。子どもたちへの影響が、もしそういうときに大丈夫なのかといったところが知りたいのですけれども。","respondent":"長尾建築課長","answer":"急傾斜地が学校敷地の外側というか、民地側のほうにもありますので、そこに対しての安全策としては、擁壁を造ることと併せて、落石等も防ぐ措置も学校の敷地側のほうでやっているなど、安全対策は学校側で可能なところはやっているというふうに聞いております。","id":"exchange-048"},{"speaker":"田中委員","kind":"意見","question":"ご説明で分かったのですけれども、対応はされているといったことだったのですけれども、でも、今回指定されたということで、やはり不安になる保護者と子どもたちもいるのではないかと思うので、そういった説明はどのようにされるのかといったところをお知らせください。","respondent":"長尾建築課長","answer":"今後、庶務課とも情報を共有しながら、学校側でできることのお話と、あと、やはり民地側でどうしてもご対応いただくお話と両方あると思いますので、可能なところを進めていって、より安全なところを建築課としても支援していきたいと考えております。","id":"exchange-049"},{"speaker":"のだて副委員長","kind":"質問","question":"やはり今回新たに警戒区域ということで指定されたわけですが、そうした土砂災害が起きない支援を拡充していくということが必要だというふうに思っています。今も区のほうで支援されているとは思うのですが、なかなかそれで進めていくというのが難しいということで、この支援拡充をぜひやるべきだというふうに思うのですが、いかがでしょうか。","respondent":"長尾建築課長","answer":"区のホームページにも、土砂災害に関する個別のページを作っておりまして、建築課と防災課で共に情報発信なども行っておりますので、そういったところでの周知も今後継続して努めてまいりたいと考えています。","id":"exchange-050"},{"speaker":"石田（秀）委員","kind":"意見","question":"２つ聞きたいです。御殿山小学校の東側だけれども、これ、なぜ今さらなのか。「なんだよ、（土砂災害警戒区域に）ならなくて大丈夫なの？なのに、なぜ今さらというのが１点。そんな大雨のときだ、地震のときだと。イコールというのは必要だと思うのだけれども、どこかで整理はしてほしいと思うのだけれども。これは所管が違うというなら答えなくてもいいけれども、ぜひそこの２つ、お願いします。","respondent":"長尾建築課長","answer":"今回、その建築工事が終わりましたので、追加調査を都のほうで令和２年になってから行って、今回の追加指定予定となったというところです。","id":"exchange-051"}]},{"id":"topic-05","title":"環境表彰式・環境講演会","agenda":"環境表彰式・環境講演会","exchanges":[{"speaker":"のだて副委員長","kind":"意見","question":"のだて稔史です。よろしくお願いします。","respondent":"中島防災課長","answer":"１枚お戻りいただきまして、資料２の一番下の３の今後についてをご覧ください。この内容を品川区防災会議に諮りまして、地域防災計画に定めた後に、施設の管理者などに対しまして周知をするとともに、令和３年度に避難確保計画の作成および避難訓練の実施を支援してまいります。","id":"exchange-052"}]},{"id":"topic-06","title":"令和２年度品川区地域防災計画の修正","agenda":"令和２年度品川区地域防災計画の修正","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほど、土砂災害警戒区域の報告のところでこれを質問したのだけれども、このとおりで、避難施設が分からなかった。そうすると、もう混乱を招くだけ。町会の役員でさえ間違えて行くような始末だったわけです。ここら辺のところの現実問題を、いろいろ周知していくというのだけれども、どうお考えなのかなと、直していくのは非常にいいことなのだけれども、そこら辺のお考えをぜひ聞きたい。","respondent":"中島防災課長","answer":"おっしゃるとおり、これをいかに周知していくかということと、やはりまだ地震と風水害の違いというか、そこのところの周知も併せてしていかないといけないと思いますので、今後、町会・自治会をはじめとして、地域の方々にご説明する機会でありますとか、あと。","id":"exchange-053"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"真っ暗でピンポンを鳴らして「うちじゃありません」では、それはそのとおりなのだけれども、そこの考え方もしてもらわないと、例えば門を開けておいて中へ来てもらって、雨の中、濡れないところでちゃんとご説明をして、「ここではあれなので、こっちへ行ってください」ぐらいのことがないと、間違えて来た学校側のところも何かないと、真っ暗の中、インターホン越しに言われるのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、石田秀男委員の話の中で、作っていただいて手直しをしていただいたのだけれども、混乱をする。この中には何か原因があるだろうからこういう形になったのだろうと思いますけれども、そこのところはどういうふうにお考えになっているのか、聞かせていただきたいのが１つ。それと、地図ですけれども、資料１の別添１で「ＳＣ」と書いてあるのは、これは何ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"大沢委員","kind":"質問・要望","question":"ああ、シルバーセンターね。別添２のほうは、きちんと「後地小」とかと漢字で書いてくれるから分かるのだけれども、確かにシルバーセンターは長くなってしまうから。これ、シルバーセンターですね。分かりました。では、最初の部分だけご答弁いただきたい。","respondent":"中島防災課長","answer":"ちょっと曖昧だったところがありましたので、それが原因と考えて、今回、しっかり明確に避難施設を示していきたいということが考えです。明確でなかったというところに原因を思いまして、少し明確にするということで、今回見直しをさせていただいたものです。","id":"exchange-056"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、前回のところは周知不足だったということで、前回のものをさらに十分に周知するという作業をするということになると、そもそも案自体は見直しをされていなくて、前回あったものをさらに周知をするという、アプローチ段階を１つ上げただけなので、見直しというのは違うのではないですか。","respondent":"中島防災課長","answer":"見直しということで、指定の考え方の見直しというところになりまして、地区部に１から２施設をしっかり決めていって、そこに避難をしていただくということの。","id":"exchange-057"},{"speaker":"大沢委員","kind":"質問","question":"考え方の見直しだったらいいのだけれども、資料１に「避難施設の見直しについて」と物で書いてあるので、考え方は物ではないですよね。そこらの表現というか、そうでないと、施設の見直しと書いてあるので、私たちは「なんだ？どうですか。","respondent":"滝澤災害対策担当部長","answer":"今回は、もう自主避難施設を開くときには、各地区１ないし２施設というふうに決めて、そこを必ず開きますという言い方をしようということで、自主避難施設については１３か所を固定して開きますという形で周知をしますので。","id":"exchange-058"},{"speaker":"西本委員","kind":"確認","question":"たしか区の職員ではないのです。昼間だったらいいけれども、夜間だったら誰がやるのですかという。もう１つ確認ですが、開設対象施設というのは、これは近いところに行っていいということですね。それも多分混乱する要因の１つなのかなという思いがあるので、そこら辺の周知が、庁内の方々、区民の皆様方にどうやって伝えたらいいのかというところがありますので、お考えをお聞かせください。","respondent":"中島防災課長、滝澤災害対策担当部長","answer":"初めに、２の避難施設の考え方についてですが、こちらについては、自主避難施設と避難場所というのは、どちらかというと、災害が発生する前に危険を回避するために開設をするもので、区民避難所というのは、どちらかというと。区民避難所として開設するときの対象者は約十何万人という規模の人を対象にしていますけれども、この自主避難施設と避難場所については、１,０００人とか、台風１９号で６００人とか、多分。","id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１つだけ。その町会の役員が、説明するほうも悪いのかもしれないけれども、そのとき町会で話をするのは、３回は最低やろうと言っています。高齢者クラブへ行って３回説明しても、８割の人ぐらいしか分かっていない。言ったうちの１つしか覚えていない。だから、周知の仕方もぜひ考えていただきたい。１回、２回でうまくいくなどとは到底考えられない。ぜひそれは考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"田中委員","kind":"提案","question":"最初の説明のところで、この開設対象施設（案）については、地域の声を聞いて、今後修正をしていくといったご説明もあったと思うのですけれども、その地域の声の聞き方、今の案をどのように提案して、そしてどうやって聞き取るのかといったところと、また、先ほど来、前回は混乱が生じたといったお話がありまして、確かに混乱が生じていたなと、周知不足だったというお話もあったかと思うのですけれども。","respondent":"中島防災課長","answer":"最後に、自主避難施設、昨年、食料などはご持参くださいみたいなところの周知もさせていただいたところなのですが、やはり避難するということも緊急の対応の１つですので、どういう形で何をご持参いただくとか。","id":"exchange-061"},{"speaker":"田中委員","kind":"意見","question":"地域への説明と声の聞き方についてですけれども、町会長会議を基本ということだったのですけれども、町会に入られていない方たちにもやはり声を聞いていただけるような工夫をぜひしていただけたらと思いますが、そこら辺についても。","respondent":"中島防災課長","answer":"今回、図面のほうで記載させていただいていますが、地域の中のできるだけアクセスがしやすいような場所を考えたのですが、ただ、区としましては、１３地域センター全体のバランスなども勘案しまして、今回、住所地を特に指定しないで避難をできるような形なので、ある程度。","id":"exchange-062"},{"speaker":"田中委員","kind":"確認","question":"要配慮者利用施設の指定についての部分ですけれども、ちょっと具体的になってしまうので、もしかしたらお答えが難しかったりするかもしれないのですけれども、確認で、歩行困難者の方たちが避難に使えるエレベーターの設置について、この施設全体的に。","respondent":"中島防災課長","answer":"もう１点の要配慮者利用施設につきましては、今回、施設から、例えば避難場所とか、施設内で少し高い２階以上とか、そういう施設内での避難ということを計画する形のものになりますが、現状、我々としましては、避難のエレベーターとか。","id":"exchange-063"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"この避難施設の考え方を伺いたいのですが、先ほどちょっと説明があったところで、台風の規模でも、この資料で見ますと、９５０ｈＰａから９７０ｈＰａの規模であれば、自主避難施設は全部開設をしていくというような形でご説明があったと思ったのですが、資料の右側を見ると、開設の考え方のところで、台風の規模に応じて開設の是非も含めて区で決定していくということで書いてあったので、以前のように。","respondent":"中島防災課長","answer":"シルバーセンターの取り扱いについてですが、こちらも検討の中で、やはり畳があるということのいい面も十分考えたところなのですが、やはり一定程度、バランスよく配置される中で、一定程度の収容人数でありますとか、避難の分かりやすさというところで。","id":"exchange-064"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"そうした中で、資料１のところで、伝達手段が左下のところで書いてありますが、これが当日、災害発生の危険性がある場合の伝達手段ということだとすると、実際、区ホームページとかしなメールとかツイッターがあるのですが、そういったことができないお年寄りの方もいらっしゃいますので、車を回したりですとか、ケーブルテレビのＬ字放送とか、そういったことをやるべきではないかと思っているのですが。","respondent":"中島防災課長","answer":"初めに、城南小学校のところですが、これも今回検討する中で慎重に検討してみたところなのですが、やっぱり色が結構ついているところですが、今回、校舎の建て替えがございまして、比較的旧東海道側に校舎も移りまして。","id":"exchange-065"},{"speaker":"のだて副委員長","kind":"質問","question":"分かりました。次に、要配慮者利用施設の指定のところで、法改正が平成２９年６月に施行されたということで、大体４年ぐらい経つことになると思うのですが、施設の指定が今になったという経緯を伺いたいと思います。具体的にどのように進めていこうと考えていらっしゃるのか、伺いたいと思います。そういったところでの避難の考え方などもありましたら伺いたいと思います。","respondent":"中島防災課長","answer":"２点目が、避難訓練の実施ということで、こちらについては、当然、災害事象が、区からの情報伝達をもとに、皆さん、行動していただくことになると思いますので、いわゆるタイムラインという形式になるか、その辺は各施設側の取組の中だと思いますが、一定程度、時系列というか。","id":"exchange-066"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"ハザードマップの見直し等で遅れたということですが、やはり命に関わることでもありますので、ぜひこれは迅速にやっていただきたいというふうに思います。併せて、いろいろ平屋のところは水平避難も含めてということで、やはりしっかりと避難確保計画、そして避難訓練の実施ということができるように、区としても指導して支援をしていっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"田中委員","kind":"質問・要望","question":"要配慮者利用施設の指定のところで、先ほど、調査対象ではないといったお話があったのですけれども、障害児者総合支援施設「ぐるっぽ」で、そこに設置されているエレベーターが非常用エレベーターのため、消防が来ない限り動かすことができないということがありましたので、この機会にぜひ調べて、ほかの関係部署と連携して調査していただきたいということを思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"若林委員","kind":"質問","question":"聞き間違いがあったのかもしれないので、そこの点を。先ほど、災害対策担当部長のご答弁で、いわゆる超大型台風のときはすべての５２か所の避難所を開けざるを得なくなるでしょうというお話がありました。この３で言うと、９７０ｈＰａ以上は「在宅避難とし、避難施設は開設しない」というところの、先ほどの答弁と合わないのですけれどもと思うのですが、合っているのでしょうか。","respondent":"中島防災課長","answer":"今、災害対策担当部長が話をしましたのが、この９５０ｈＰａよりも左側の、もっと強い、左側に行けば行くほど強くなりまして、現時点で関東地方で上陸したときの一番強いものが９５０ｈＰａなので、過去３０年ぐらいでないような台風が上陸した場合の話で、先ほど。","id":"exchange-069"},{"speaker":"若林委員","kind":"確認","question":"ということになってしまうのですね。１つ確認ですけれども、これを地域防災計画の表にどう載せるかというのは、また会議の中でお決めになられると思うのですけれども、私はこういう理解をしているのですけれども、２の自主避難施設に載っているところは、４の自主避難施設に対応している。２の区民避難所は、この表の、今回の見直しの表には対応していないというところの確認をさせてください。","respondent":"中島防災課長","answer":"区民避難所は、３の一番左側というところと、あと、万が一災害が発生しまして避難生活をするような状況になりましたら設置するということで、ちょっと分かりづらいところですが、しっかりと整理をしまして周知に努めてまいりたいと思います。","id":"exchange-070"},{"speaker":"若林委員","kind":"質問・要望","question":"そうすると、縦方向避難ということが普通に言われていて、それは国も、当然その指定を受けた区もそういう言い方をされる。そういう中で、平屋かどうか、縦方向避難ができるかできないかを、この段階で把握していない、また調査をする考えもないというのは、私は今のこの流れの中での答弁としてはいかがなものかなというのは、ちょっと違和感を感じたので、改めて答弁を求めたいと思います。","respondent":"滝澤災害対策担当部長","answer":"どの施設が浸水区域にあって、どの施設が浸水区域にないかというのをすべて洗い出しまして、その中で今回の法律は、その浸水区域にある該当する施設の管理者は計画をつくらなければいけないという義務づけの明示をするというのが区の役割でありまして。","id":"exchange-071"},{"speaker":"若林委員","kind":"質問","question":"だから、説明が、今ので「ああ、そうなのか」と。このやり取り、また議事録をもとに、私たちも、ある意味では区民に説明するということに当然なるわけではないですか。だから、そこら辺も踏まえて、今の部長のフォローの答弁も含めて、これでよしとしますけれども、今後また伝え方とかというのは、本当に工夫というのではなくて、工夫と言うしかないのかな、さっきの確度と一緒で、重々お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"}]},{"id":"topic-07","title":"防災タブレットの更新","agenda":"防災タブレットの更新","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはこれでぜひやっていただきたいと考えていますが、例えば私の地域には、１６の町会・自治会がありますけれども、８割方の方は置きっ放しだと思っています。これはもう防災課だけではなくて、本当に地域センターの人たちにも本当にお世話にならなくてはいけないと思いますが、ぜひそれは有効活用していただきたいなと思います。よろしくお願いします。","respondent":"平原防災体制整備担当課長","answer":"地域から様々な声をいただきましたら、個別にも丁寧に対応してまいりたいというふうに考えてあります。","id":"exchange-073"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"答弁は要らなかったのですけれども、先ほど言ったように、高齢者の人には３回言っても分からないので、８割ぐらいの人しか理解してくれないと思うし、高齢になったら、多分もっと分からないと思うのです。だから、本当に習うより慣れろで、ぜひ連携していただいて、よろしくお願いします。要望で、答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"田中委員","kind":"質問・要望","question":"予算額を伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"続きまして、実施ですけれども、地域の方々につきましては、本来であれば、２月上旬からの町会長・自治会長会議の場でご説明をする予定でございましたが、緊急事態宣言の期間との関係で、そこら辺の会議の開催が現在微妙なところですけれども。","id":"exchange-075"},{"speaker":"田中委員","kind":"質問・要望","question":"アプリのところですけれども、今、庁舎の中で海外の方に向けたアプリを使っているではないですか。そのアプリには手話通訳者の方とも連絡がとれることにもなっているので、ぜひそのアプリを活用して、早急にアプリを入れていただきたいと思います。それで、サービスとタブレットの契約ということだったので、そうなると、また契約が変わってきてしまうということですか。そこら辺をお伺いできればと思います。","respondent":"平原防災体制整備担当課長","answer":"庁舎で現在活用しておりますアプリにつきましては、こちらのアプリといいましょうか、今はタブレットですけれども、それが今回、各地域にお配りするものに同じような形で導入できるのか、またそこに費用がどういった関係になるのか、そこにつきましては、大変申し訳ございません。","id":"exchange-076"},{"speaker":"田中委員","kind":"質問・要望","question":"庁舎で使っている通訳は、通訳のサービスもついた上での契約になっていて、それに対応できるタブレットを契約しているということなのですね。やはり、発災時に海外の方たちや聴覚障害の方たちは情報弱者に陥ってとても困るといった声が届いていますので、ぜひ研究を早急に進めていただき、対応していただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"のだて副委員長","kind":"質問","question":"今回更新するにあたって、運用上の変更があるのかどうか。予算のところで、さっき導入経費ということでは１台当たり３,５７９円、通信料も入っているということだと、ランニングコストとしても、毎年というか、１台当たりの値段ということになるのか。ランニングコストのところを伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"ただ、説明の中でお話しさせていただきましたが、今回のタブレットは外に持ち出すことができるといったところで、活用方法は変わってまいりますので、どのような面でこのタブレットを使うかといったところにつきましては。","id":"exchange-078"}]},{"id":"topic-08","title":"令和２年度区内一斉防災訓練の実施結果","agenda":"令和２年度区内一斉防災訓練の実施結果","exchanges":[{"speaker":"のだて副委員長","kind":"質問","question":"１点だけ。今回明らかになった課題が何かということと、それに対して今後どう対応していくのか、特にコロナの対応等を含めて何か課題がありましたら伺いたいと思います。","respondent":"大森災害対策担当課長","answer":"ただし、地区総合防災訓練ですとか、区内一斉防災訓練ですとか、実働の部分は、やはりそこでないとなかなか自助の力をつけられない部分もありますので、そこの部分については、今後、このコロナの状況をしっかり見定めながら、区としても柔軟な対応を心がけて。","id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297355?Template=document&Id=4312#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":69417,"voices":246}},{"id":"r03-20210119-9","meetingId":"r03-cm01","date":"2021年1月19日","dateIso":"2021-01-19","committee":"文教委員会","time":"午後 １時００分～午後 ４時００分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"これはいろいろとこれから私立の受験などもあったりなどがあると思うのですが、最終的に新年度で何人になるのか、何クラスになるのかということが決まるというのは何月何日になるのでしょうかということをまず伺いたいということと、それと、この抽選や待機など、すごくいろいろな条件が加味されていて、物凄い大変な作業だと思うのですけれども、それはどのように。","respondent":"篠田学務課長","answer":"ですので、前日にお子さんが急に転入されてきて、そのことによってクラスの学級編制の枠を超えてしまえば、そこで増やす必要がありますから、そういった対応を取るということになります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"意見です。それともう一つ質問なのですけれども、最終的にこの兄弟というところがばらばらになってしまうということは、家庭にとっては相当負担ですし、兄弟にとってもよくないケースがほとんどなのではないかと思うのですけれども、最終的に兄弟がばらばらになってしまうというケースは何組ぐらいと想定していらっしゃるのか、昨年や一昨年は大体何人ぐらいだったのか、分かればお伺いします。","respondent":"篠田学務課長","answer":"そういった状況ですので、今年度どのぐらいになるかということは、これは繰り上がりの状況によって変わってきますので、なかなか見込みが立てづらいのですけれども、最大でいけばそういった数字になってくるのかというふうに考えているところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"それと今のご答弁、最大３３名ですか、後期課程は去年も一昨年もゼロということなので、中学校のほうですか。選択制がなければ、別に兄弟がばらばらになる必要はないわけですから、これはちょっとデメリットだと私は思います。一方で選択制が終わった後の指定校変更というところにも、本当だったら行く区域の学校から違う学校に行った人というのは、それはそれで１１１人もいるのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あべ委員","kind":"確認","question":"幾つか質問させてください。それと４ページ目に入学理由のグラフが書いてあるのですけれども、これは複数回答ですよね。数学の先生などだったら、多分そのように教えていらっしゃるのだと思うので、ちょっとこれ、グラフをもし載せるのであれば、違う形で載せられたほうがいいのではないかと思うのですが、いかがでしょうかということです。毎年とても心配しております。ちょっとそこを確認させてください。","respondent":"篠田学務課長","answer":"受入枠を超えたお子さんが入学されることが見込まれる場合に、基本的にいつもやっているのは、まずはクラスを増やす、学級を増やすということで、そうしませんと当然１クラスの人数が、１学級の人数が４０人を超えてしまうわけにはいきませんので、必ず４０人以内にはしています。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"これもご検討ください。それと確認させていただきたいのが、今後のスケジュールなのですけれども、ここで出ている数字というのは、抽選の行われた日のものということで、これから順次動いていくと思います。１月末と２月末、それぞれで締め切るということだったのですが、その際に何か発表のようなことをされたりするのでしょうか。決まり次第順次ご案内をするというやり方でよかったのでしょうか。","respondent":"篠田学務課長","answer":"ただ、この学校選択で入れなかった方が一部指定校変更などを希望されていて、それは個別に審査をいたしますので、これがやはり、例えば中学校の場合ですと２月が終わってから、結局入れなかった方が改めて申請をされるというようなこともありますので。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"それぞれ１月末、２月末を過ぎても、まだ行く学校が決まらないというお子さんというのは、大体例年何％ぐらいいらっしゃるものなのでしょうか。分かれば教えてください。それと最後の質問なのですけれども、やはり作業が大変というお話が出てきました。割となじむような気がするのですけれども、その方向での検討もされているのでしょうか。","respondent":"篠田学務課長","answer":"ただ、今後そういった部分で、例えば費用の部分でも低廉化が進むですとか、何らかのメリットが出てくるようなことが見込まれるようであれば、検討を進めていきたいと思っているところです。","id":"exchange-006"},{"speaker":"筒井委員","kind":"意見","question":"通学区域のお子さんは、無抽選でそのまま入れるということなのですけれども、例えば御殿山小学校などは受入可能人数が３クラス９０名のところ、無抽選で１２６名入れるということで、３６人ぐらい超えているという状況です。特に日野学園などは、そうした対応で大丈夫なのかということを少し疑問に思ったのですけれども、その点いかがお考えなのかをお聞かせください。","respondent":"篠田学務課長","answer":"仮に受入れできないということになれば、先ほど申し上げたとおり、教室の数を増やすなりして、対応していくというふうに考えているものです。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"その国の特例措置などで、１クラスの人数を４０名にしたりして対応されるということで、分かりましたけれども、人数の数字だけは大丈夫だと思うのですが、その教室の転用というものが、それほどすぐにできるものなのでしょうか。やはり物理的な問題があると思うのですけれども、何かうまくやられている事例など、そのようなものがありましたらお知らせください。","respondent":"篠田学務課長","answer":"教室の転用ですけれども、基本的に今委員ご指摘いただいたとおり、例えばこの時期に急に１教室増やさなければいけないとなると、正直なかなか対応が難しいというところがあります。","id":"exchange-008"},{"speaker":"せお委員","kind":"質問","question":"この学校運営の改善につなげるのであれば、そういった方にも聞くことはありなのかなと思うのですが、その辺のちょっとお考え、そういったところも含めて、アンケートの、今答弁を聞いていますと、アンケートを見直していくというようなところはお考えがありますでしょうか。","respondent":"篠田学務課長、工藤指導課長","answer":"いわゆる学校選択の際のアンケートというものは、このような形を取らせていただいているのですけれども、そのほか、この機会とは別に様々な形でアンケートを保護者の方、児童・生徒の方には取っていますので。今回報告しているものではございませんが、以前報告した中で、私どもで児童・生徒アンケートおよび保護者アンケートを行っている中では、全ての家庭、また児童・生徒に対して選択した理由。","id":"exchange-009"},{"speaker":"せお委員","kind":"質問・要望","question":"だからもう、これはやはり、アンケートの部分ではないのですけれども、この抽選のところなどを見ていると、兄弟、兄弟と書かれていて、前回もお伝えしましたけれども、理由というのは兄弟だけなのかなと、やはりそこは思ってしまって、本当に様々な理由が皆さんあって選んでいらっしゃるので、そこのところも、やはり今後この学校選択のところで検討していっていただきたいと思うのですが。","respondent":"篠田学務課長","answer":"これに関しましては、基本的な考え方、根本的な考え方になりますので、理由に基づいた選択を導入するいう考えは、今のところないです。","id":"exchange-010"},{"speaker":"横山委員","kind":"確認","question":"すみません。確認なのですけれども、経過措置についてなのですが、こちらは２０２２年度の入学からは終了するというようなパターンの方と、あと兄弟に関する部分は２０２４年度までということで、現在はよろしいでしょうか。確認をさせてください。","respondent":"篠田学務課長","answer":"それから委員ご指摘のとおり、兄弟に関するものは、兄弟在学中に経過措置として対応するですので、その部分に関してはさらに先まで、２０２４年までという形になってくるものです。","id":"exchange-011"}]},{"id":"topic-02","title":"令和２年特別区および東京都人事委員会報告","agenda":"令和２年特別区および東京都人事委員会報告","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"東京都人事委員会の報告で、この意見が出されていますけれども、そこの（２）のライフ・ワーク・バランスの推進のところなのですが、これに「教員については『学校における働き方改革推進プラン』等に基づく取組を継続的に推進し、実効性を確保することが肝要」というような意見が出されているわけですけれども、品川区においては、このような意見に対してどのような取組みというものを推進していて。","respondent":"工藤指導課長","answer":"その中では、やはりスクール・サポート・スタッフの配置によって教員の業務量を軽減することであるとか、また、今年度につきましては、これまでも行っていた勤務の時間外、在校等時間の把握をしっかりとする取組みなども進めてありますので。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"引き続きこれは改善が必要だということで意見が出ていると思うのですけれども、今のような取組みがされているということですが、どれぐらい改善されているのかという、そういったものというのは、教育委員会としてはある程度把握されているのか、超過勤務の時間ですとか、そういった効果についてはどのように把握しているのでしょうか。伺いたいと思います。","respondent":"工藤指導課長","answer":"今ちょっと手元に数値がないところですけれども、今年度でいえば、いわゆる月の単位でいうと４５時間を超えないというところで、超えた場合には各校長が教員と面談を行うなども行ってありますし、また、いわゆるそういった在校等時間が長い場合、そういった場合には。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"特別区の３ページのところで、保育教諭等への対応という項目があります。それで、品川区ではこれについてどのように検討しているのか、教育委員会でお分かりでしょうか。（６）番。","respondent":"工藤指導課長","answer":"保育教諭というのは、いわゆる認定こども園で、両方の資格を持った教員ですけれども、品川区の場合、幼保一体施設の中で、保育園と幼稚園というところで、それぞれで運営をしている中ですので、そういった意味では、そういった把握をしていますので。","id":"exchange-014"},{"speaker":"あべ委員","kind":"質問","question":"なので、品川区としてはどのような見解になっているのか、分かれば教えてくださいということなのですけれども、今ちょっと教育委員会だけになってしまっていますが、一応文教委員会でこれは出てきているものなので、もし教育委員会で分からなければ、後半に引き継いでいただければと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"あべ委員","kind":"質問","question":"まさに教育委員会の方にお伺いする以上に、委員長にご相談をすべきことだと確かに思います。一応文教委員会で出てきている中でのお話なので、後半、所管のほうに引き継いでいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"筒井委員","kind":"意見","question":"この特別区人事委員会の報告の３ページで、リモートでの業務遂行の課題やテレワーク導入のこと、また、東京都人事委員会のほうでも２ページ目で、ポスト・コロナ社会を見据え、テレワークを日常的かつ円滑に実施できるよう、ソフト・ハードの両面でさらに環境を整えるべきと。","respondent":"工藤指導課長","answer":"オンライン教育、またはリモートでの学習というものを進めるという考え方は、今も現状進めてありますし、そういった対応ができる環境もありますし、また、教職員のスキル、また児童・生徒の慣れというものも含めて、今後進めていきたいと考えているところはありますので。","id":"exchange-017"}]},{"id":"topic-03","title":"品川区立図書館の休館日変更","agenda":"品川区立図書館の休館日変更","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"１件確認させてください。分散された休館日になるということは、利用者にとって非常にいいことだと思います。ただこれ、指定管理だったと思うのですけれども、指定管理期間途中の休館日変更、あるいはその２つの館については日数変更になるかと思うのですが、この際、契約の変更ですとか、あるいは指定管理料の見直しですとか、そのようなことというのはやっているのでしょうか。","respondent":"横山品川図書館長","answer":"ご指摘いただきましたとおり、荏原図書館、五反田図書館につきましては、休館日が月２日から１日になり、逆に言うと指定管理業務については１日増える形になりますので、令和３年度予算におきまして、各１日分を補償する形で予算を確保しております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"第２木曜日で休館にしても、比較的どこか近くには図書館があるというのは、これは変更だと思うのでいいと思うのですけれども、この３館がずらすということなのですが、地図でいうと真ん中とか右下辺り、西品川、豊町とか、大井とか辺りにも、近くに第２木曜日でも開いているという、休館にならない図書館があるということが理想だと思うのですけれども、そのようなことはなかなか難しいことなのでしょうか。","respondent":"横山品川図書館長","answer":"実はこの変更につきましては、１年間プロジェクトチームをつくって検討してまいりました。","id":"exchange-019"}]},{"id":"topic-04","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"前半のご説明のところに当たると思うのですけれども、１００ＭＢを１ＧＢに今変えるということなのですが、光ファイバーとか、そのようなものを導入するということでしょうか。ちょっとそのインターネット環境の状況をお聞きしたいと思います。","respondent":"篠田学務課長","answer":"今回増強するのは、基本的に各学校からインターネットに出る回線になるのですけれども、こちらのほうは今までずっと１００ＭＢの制限があったのですが、今回１ＧＢにアップするということで、もともと今引かれている、学校によって設備は違うのですが。","id":"exchange-020"},{"speaker":"あべ委員","kind":"確認","question":"幾つか確認させてください。このインターネットのボリュームなのですけれども、これは学校規模によらずということなのでしょうか。ちょっとそこを教えてください。それから後半のロイロノート等々なのですけれども、ＩＣＴを適切に入れることによって、すごく学習効率が上がるということは、導入する１つの目的でもあって期待をしているところです。","respondent":"篠田学務課長、工藤指導課長","answer":"確かに学校の規模に応じて、使うタイミングによっては、たくさんのお子さん方が一遍に使えば、どうしても混み合うというようなこともあろうかと思いますので、その辺はちょっと実情を見ながら。児童・生徒への定着等を図る上では、例えば先ほどのようなロイロノート・スクールに併せてｅライブラリアドバンスというソフトが、全員が、全児童・生徒が使えるという状況になりますので、そういった意味では。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"むしろ先生の力量そのものの部分だと思うのです。そこが、いいものがあれば共有するというだけのことでいいのか。もう少し、さらに教育委員会として各学校に働きかけていくというようなことがあってもいいのかなとも思っているのですが、その辺はどのようにお考えでしょうか。いかがでしょうか。","respondent":"工藤指導課長","answer":"そういった意味で学習指導要領上の目的、ねらいに達するという上で、この１人１台タブレット、またこのＩＣＴというものは効果的に活用できるものというふうに考えてありますので、そういったところを外さないように、しっかりと押さえながら。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問","question":"ちょっとまだ聞くのは早いかもしれないですが、その来年度以降の先進的な取組みを行っていく、ある程度モデル研究校的な仕組みを新たにつくるということでしょうか。あるいは使っているソフトが違うから、ベースから授業をつくり直さなければいけないということになってしまうのではないかということをとても恐れているのですけれども、どうなのでしょうか。","respondent":"工藤指導課長","answer":"初めは、いわゆるモデル校として、活用重点校ということで、私どもで３校程度指定をして進めたいというふうに考えているところはあります。それは計画というところの中で考えているところです。","id":"exchange-023"},{"speaker":"あべ委員","kind":"意見","question":"研究、指定校も期待をしておりますし、これは来年春からすぐにということではないと思いますけれども、やはり機器やソフト、基本的に違うシステムを使って教育活動をされてきた、授業をつくってこられた先生方が異動して来られたときに、４月からきちんと授業が始められる、だんだん習熟してくればくるほど、ＩＣＴを使えば使うほど、やはり異動したときの落差といいますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"ロイロノートというアプリなのですけれども、イニシャルコストとランニングコストというものがかかるのか、かからないのかということをお伺いいたします。それと前回の１回目のときの質疑で、子どもの健康上の問題で、家庭で使う時間の上限を検討していますというような話があったと思うのですけれども、それは何時間とか、もう決まったのでしょうか。お伺いしたいと思います。","respondent":"篠田学務課長、工藤指導課長","answer":"それから休業中の対応についてですけれども、このロイロノート・スクールも含めまして、基本的に今回対応するアプリは全てクラウド環境に置くということになりますので。ただ、リアルタイムで授業を４５分、５０分を常に逐一やっていくという形でなければ、最初にＺｏｏｍなどでつないで、これから課題を送りますよといって課題を送って、それを一定程度取り組んだ上で提出をする、提出があった段階で。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"アプリ込みの年間のコストといいますか、ランニングコストというものが分かれば教えてください。イニシャルコストも分かれば教えてください。では、実際にこの主体的・対話的に深い学びというものは、今の取組みの状況というのですか、どうなっているのかということは、ちょっとそのようなものは聞いたことがないというか、私のほうから質問したことはなかったのですけれども、どうなのか。","respondent":"篠田学務課長、工藤指導課長、齋藤教育次長","answer":"トータルで見ると、これだけではなくて、これまでパソコン教室に配備していたパソコン、タブレットなども引き続き、例えばＷｉｎｄｏｗｓ機ですので。実際にそういった授業を中学校で行っている例がありますけれども、それぞれの班の進捗を見た上で、自分たちにない視点を気づいて、ああ。この問題集を解いた履歴を教員が確認することができますので、そのつまずいたところ、できないところ、こういったところを踏まえて。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"そのような主体的で対話的で深い学びということで、やはり協働学習が１つのポイントになるのかと思っていまして、今日の例なども、いろいろな他の児童・生徒の意見などをみんなで共有したりなどということで、そのような協働学習の１つの活用の例なのではないかというふうに理解したのですけれども、そういう意味では、何でしょう、個々の子どもたちの発想とか、つまずきとか。","respondent":"矢部教育総合支援センター長","answer":"ただ、品川区としてこのような形というものは示してございませんが、委員おっしゃるとおり、教員はその場その場の担当各教科で、専門で創意工夫して楽しい授業を提供することが本分だと考えておりますので、今後も、今大事にされています見通しや振り返り。","id":"exchange-027"},{"speaker":"たけうち委員","kind":"質問・要望","question":"３分の２で４万５,０００円が上限ということなので、そうすると大体７万円前後するものが国の補助を受けて、ただになるという形なのか、そこをもう１回教えていただきたいと思います。","respondent":"篠田学務課長、工藤指導課長","answer":"最初のロードマップの関係ですけれども、当初は６年生、９年生に１２月に配りたいということで、できるだけ早めにということで取り組んではきたのですけれども、こちらは事業者とかなり、取締役クラスの方ともお話をしたのですが。今説明がありましたように、昨日から研修用として、いわゆる児童・生徒に配るものと同じセルラーモデルのｉＰａｄを各校に１台ずつ配付しています。","id":"exchange-028"},{"speaker":"たけうち委員","kind":"確認","question":"分かりました。先ほど説明があったのでしょうか、ちょっと私が聞き逃したのかも分からないですけれども、ロードマップではそのように出ていましたので、これからやられるということですね。金額のほうは少し勘違いしていて、金額の上限が３分の２かなと思ったもので、結果的には一緒なのでしょうけれども、台数が３分の２だということで、残りの３分の１は区が負担していくと。確認できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"芹澤副委員長","kind":"提案","question":"幾つか伺いたいのですが、まずＩＣＴ研修員について、役割を前回少しご説明されていると思うのですが、もう１回確認をさせていただきたいのが、学校に何回か伺うということで、これは保守的な、例えば何かこういったことができない、ロイロノートなどを使ってこのようなことができないというときに、学校から要請があって伺うものなのか、それか、そのＩＣＴ研修員がいろいろなところで知識を得てきて。","respondent":"篠田学務課長、工藤指導課長","answer":"実際に学校に赴きまして、いわゆるＩＣＴ活用に当たって、こちらから、先ほど副委員長からお話があったとおり、提案型という形ではないのですけれども、逆に学校からすると様々な形で疑問がありますから。そのほか様々な活用を図られていた場合に、特に次年度以降は、ＩＣＴ推進教員向けの研修会というものを数回設けまして、その中でやはり共有も図る、区内も含めて進めていきたいと思いますので、やはり全教員向けと。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"モデル校３校というお話だったと思うのですけれども、今のＩＣＴの推進校と異なって、別の学校もモデル校を３校抽出してやっていくというお考えなのですか。今、何か副委員長のご質問にご回答がなかったかなと思ったので。","respondent":"工藤指導課長","answer":"全ての学校が全て推進をしていくのですけれども、その中で、よりそこに重点的に、情報発信も含めて行っていただきたい学校を指定するという方向で考えているところです。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"それは今のＩＣＴの推進校から３校選ぶということですか。それともゼロベースで選ぶということですか。","respondent":"工藤指導課長","answer":"現状あります推進校との関連というものは、特に考えているところではございません。現在、これから進めるＩＣＴの中で、いわゆる全校対象の中でです。","id":"exchange-032"},{"speaker":"あべ委員","kind":"確認","question":"先ほどお話が出てきた中で、ＩＣＴ研修員の方が、機械の保守や操作だけではなくて、教材作りですとか、授業を作っていくというようなアドバイスもあるということだったのですけれども、とすると、これは単にＩＴの専門家というだけではなくて、ある程度学校教育についても理解のある方が来られるという意味でよろしいのでしょうか。確認をさせてください。","respondent":"篠田学務課長","answer":"なかなか実際問題、教育の中身にまで立ち入っている方、要は理解している方というものは難しいと思うのです。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"それと前回のときにも少し質問をさせていただいたと思うのですけれども、今後長期で休んでいる方ですとか、不登校ですとか、あるいは支援学級でのソーシャルスキルという部分ですとか、そうしたことにも活用を広げていかれると期待をしているのですが、そこはどのような感じで考えていらっしゃいますでしょうか。","respondent":"篠田学務課長","answer":"長期欠席の方ですとか、不登校のお子さんも含めて、全てのお子さんに機械を配付いたしますので、あとはそれぞれの状況に応じて、各教員が連絡を取ったり、場合によっては授業でリモートができるのかとか、その辺はこれから試行錯誤していくことになると思うのですけれども。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問・要望","question":"支援学級などでも、それぞれに応じたソフトを入れて使っていらっしゃるというように考えてよろしいのでしょうか。","respondent":"篠田学務課長","answer":"支援学級のお子さんは、特に慣れているものがいいだろうということで、基本的には今までのベースのものを引き継ぐものと、あるいはそれにプラスして、新たに有効性の高いものがあれば、それはそれぞれの支援学級等の状況を見ながら。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"これも前回もちょっとお伺いしましたけれども、例えば保護者との連絡ですとか、プリントの共有ですとか、そのような公務といいますか、家庭との共有といった使い方というのも、一部の学校では試行されていると聞いているのですが、これはどのような形で進めていかれるのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"あくまで学習を支援するものということは大前提で、お子さんの学習に障害がなければ、家庭でどこまでやれるかということはこれから検討していきたいと考えております。","id":"exchange-036"},{"speaker":"横山委員","kind":"質問","question":"区固有教員の方で、ＩＣＴの推進の役割を担っていらっしゃる方というのは、何名ぐらいいらっしゃるのでしょうか。","respondent":"工藤指導課長","answer":"区固有教員の研修も、推進教員の研修とは別に、２月に予定しておりますので、区固有教員の方であればずっと品川区にいるものですから、やはりスキルを上げていただきたいということで、区固有教員独自の研修も予定しています。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問","question":"品川区にずっといて、教育活動を続けてくださる人材でありますので、区固有教員の方のＩＣＴに詳しい方とか、リーダーですとか、そういったところの育成ですとか、キャリアパスですとか、資格等の取得の支援ですとか、そういったところは力を入れていただいたほうがよろしいのかなと思っておりまして、区の固有教員以外の方とはまた別の部分で。","respondent":"工藤指導課長","answer":"区固有教員向けには、そうした、いわゆる複数の免許の取得も含めて助成する制度、またはそういったものを学習する制度もありますので、そういったものをやはりＩＣＴにも適用するということは可能ですので、前向きに検討していきたいと思ってあります。","id":"exchange-038"},{"speaker":"せお委員","kind":"質問","question":"すみません、１点だけ。今、緊急事態宣言が出ていますけれども、この「ＩＣＴ通信」にあるような授業実践という、この写真にあるような状況というのは、今現在できるものなのでしょうか。私から見ると、結構厳しく小・中学校などの感染症対策を取っているようですので、私は３月に収まるのかなとちょっと疑問ですので、そういった取組みが今現在だとできる状況なのでしょうか。","respondent":"工藤指導課長","answer":"先般、緊急事態宣言が出たところで、教育総合支援センターより通知を出したところですが、現在このような授業が、対話で行うとかというものはできない状況で、学校のほうには感染症予防のためにこういったことを、飛沫が飛ぶものも含めて、ですからこの対面でという。","id":"exchange-039"},{"speaker":"せお委員","kind":"意見","question":"ちょっとずれてしまうのですけれども、感染症対策も大事なのですが、あまりやり過ぎた対応はいかがかなと思っているので、重要なところは実践などに取り組んでいただいて、ちょっとめりはりつけたところでお願いしたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]},{"id":"topic-05","title":"の２の報告事項に戻りまして、(5)八潮北保育園の運営業務委託","agenda":"の２の報告事項に戻りまして、(5)八潮北保育園の運営業務委託","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ガイドラインは撤回をすべきだと思います。その上で質問なのですけれども、今回選定方法で、公募型ということで、応募５社ということでしたが、ほかの応募４社はどのようなところが応募したのでしょうか。評価基準項目は何項目で、それぞれ何点満点で、５事業者それぞれ合計点数が何点で、結果として品川総合福祉センターを選定したのか、具体的に伺いたいと思います。これはなぜ公開をされないのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"保育に対する区の方針と合致しているか、事業者の管理体制はしっかりとしているか、保育の内容についてはどうなっているか、保護者や近隣への配慮、地域等の連携についてはどうなっているか、財務状況は問題ないかという評価項目になっております。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問","question":"点数は公開していないということなのですが、伏せるべきところは伏せて、何かもう少し公開したほうが、きちんと透明性が確保されるのではないかと思うのですけれども、今回は区立保育園の業務委託の選定なので、そもそも民間委託するのはどうなのかという立場なのですが、様々なこのような選定のときに、やはりきちんとその理由を示すためにも、これからは公開すべきなのではないですかという質問なので。","respondent":"吉田保育施設調整担当課長","answer":"その中で選定会議としては、品川総合福祉センターに運営事業者を選んだというところは、３０年以上品川区内で保育園を安定的に運営しているところや、人材確保のところが今回２４名ほど確保する形になるのですけれども、この辺の計画性をもって出されていたというところと。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"今、そのようなご説明をいただくと、大分分かってくるのですけれども、やはり、特に今回の場合は、議会でも民営化はすべきでないという意見が、私たちも含めて幾つか出ているわけではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"あべ委員","kind":"確認","question":"幾つかお伺いしたいと思います。この数字の違いがどこから来るのかということを教えてください。そうした補助制度の対象に乗ってくるのかということを確認させてください。それから、１年間のならし期間もあるということなのですけれども、職員の方というのは皆さん替わるのか、それとも、ある程度は新しい法人に移られたりということがあるのかどうかを教えてください。","respondent":"吉田保育施設調整担当課長","answer":"ホームページ上にある６社というのは、このプロポーザルをやる際に事業者向け説明会をやるのですけれども、その際に来た事業者が６社でございまして、実際は１社は申し込まれなかった、辞退されたところでございました。","id":"exchange-044"},{"speaker":"あべ委員","kind":"確認","question":"補助金のところ、今はまだ区立で、今回の改修は区ということなのですけれども、この令和４年４月以降はどうなるのかということも教えてください。途中から合同保育になって、品川総合福祉センターの保育士が来るということはあっても、今いらっしゃる方が移籍といったらいいのですか、品川総合福祉センターに移って引き続きこの保育園に勤務するということはないということでよろしいでしょうか。確認です。","respondent":"吉田保育施設調整担当課長","answer":"そこまでの間の、令和３年１２月から令和４年３月３１日までの４か月間は、品川総合福祉センターから保育士が来まして、引継ぎのための実務的な合同保育を行うという形になります。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問","question":"移籍はなしということですね。最後に、ご説明の中で医療的ケア児の受入れということもあったのですけれども、ということは、新たな八潮北保育園では、医療的ケア児の受入れが予定、対応可能である体制になるということでよろしいのでしょうか。そういったことも含めて、先ほどの質疑にもありましたが、もう少し詳しい選定内容というものが分かるとありがたいなと思います。","respondent":"吉田保育施設調整担当課長、立木保育課長","answer":"４月、例えばこの段階から、いつから受け入れてというところがまだはっきりと確定したものではないので、今その前提で。医療的ケア児に関しましては、公立保育園、一応どちらの園でもご希望があれば、入園審査を経てですけれども、対応可能なような体制を今構築していますので。詳しい選定内容につきまして、今後分かるように出してほしいという内容ですけれども、選定内容の公開につきましては。","id":"exchange-046"}]},{"id":"topic-06","title":"上大崎三丁目教育・保育施設の整備計画","agenda":"上大崎三丁目教育・保育施設の整備計画","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"保育所型認定こども園ということなのですけれども、区内で何か所目になるのか、また改めてどのような施設なのか、簡単に伺えればということが１つです。施設整備等に関する工事が、説明があると思うのですけれども、それはいつぐらいを予定していて、どのような形で行うおつもりなのかを伺います。","respondent":"若生保育支援課長","answer":"説明会の対象ですけれども、こちらにつきましては、施設の、一般的に解体工事等を行う場合に、区では建築物の予定の高さの２倍の範囲としているというところから、そちらの高さの２倍、高さでいいますと施設で２０ｍが最大、高さの想定です。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"今後、やはり地域に長く親しまれる保育施設にしてほしいので、ある程度そのような案の段階から住民の声も伺って、可能なところということになるとは思うのですけれども、計画にも反映していくというようなことを丁寧にしていただくことで、そのようないい保育施設になるのではないかと思いますので、その辺について、先ほどの時期の問題と併せてご見解を伺いたいと思います。","respondent":"若生保育支援課長","answer":"令和３年度の説明会の時期ですけれども、今事業者から聞いているのは、令和３年度になるか、その前にできるかもしれないということを聞いているのですが、３月から４月ぐらいというような予定で聞いているところです。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問","question":"ごめんなさい。聞き落としたかもしれないのですけれども、石綿調査等ということですが、アスベストは大丈夫なのですか。","respondent":"若生保育支援課長","answer":"アスベストですが、こちらのほうは以前の国有地のときにも調査を行っていまして、今回も改めて調査を行いまして、一定アスベストのほうは検出されているということで、こちらについては法令に基づいて適切に処理してまいるです。","id":"exchange-049"},{"speaker":"あべ委員","kind":"質問","question":"これから解体工事ということで、アスベストを含むと、ちょっとまた手順がいろいろと定められているかと思うのですけれども、これは既に住民の方々、もう終わっている……。２月着工だからまだですよね。これは住民の方には、そうしたこともきちんとご説明してご理解いただいているということでよろしいでしょうか。","respondent":"若生保育支援課長","answer":"こうしたアスベストの関係も、先ほど申しました１１月３０日のときの解体工事の説明会で説明をさせていただいたところです。","id":"exchange-050"}]},{"id":"topic-07","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"コロナ感染症の対応の点で、ちょっと１点だけお聞きしたいのですけれども、保育園の対応なのですが、社会福祉法人等の私立の保育園とか、あるいは認証の保育園のほうで、どのように対応するのかということでいろいろと悩んだり、不安というところもあると思うのです。その２点だけ伺わせてください。","respondent":"若生保育支援課長","answer":"これに関しましては、今回のコロナの感染症については、基本的に区のほうは保健所とほぼ一体的にといいますか、保健所のほうと密な連携を取りながら、これはもうタイムリーに園の事業者のほうとやり取りをさせていただいていますので、そういったことで。","id":"exchange-051"},{"speaker":"安藤委員","kind":"意見","question":"もうやっているかもしれないのですけれども、重ねてお願い申し上げたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問・要望","question":"２点ほどお伺いしたいと思います。品川区ではこれに関して、何か検討していることがあれば教えていただきたいと思います。それから、すみません、２点目なのですけれども、品川区で保育士にコロナの応援金を出しているということで、既に手続きが始まっていると思うのですが、現段階での配布状況が分かれば教えてください。","respondent":"立木保育課長、若生保育支援課長","answer":"そちらのほうは保育士を配置しているというところなのですが、幼稚園教諭の資格を併せて持っている職員を中心に配置しておりますので、実質的には保育教諭と同様の扱いといいますか、きちんと教育面もフォローできる形で対応しています。保育士等への応援金の配布状況です。こちらは１２月から、事業者のほうに区のほうで支給を開始しておりまして、今月までに、ちょっとすみません、細かい数字を持ち合わせていないのですけれども、順次進めているところです。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/186280?Template=document&Id=5022#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":57128,"voices":144}},{"id":"r03-20210119-5","meetingId":"r03-cm01","date":"2021年1月19日","dateIso":"2021-01-19","committee":"総務委員会","time":"午後 １時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","topics":[{"id":"topic-01","title":"令和３年１月１５日付組織改正","agenda":"令和３年１月１５日付組織改正","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"保健整備担当は、部長級ということですけれども、品川区保健所との役割分担についてご説明いただきたいと思います。","respondent":"佐藤企画調整課長","answer":"新設する保健整備担当の役割ですが、主に新型コロナウイルス対策の全般を担うというところです。４月に設置した保健体制整備担当はＰＣＲ検査の業務を担うもので、今回設置するのは文字通り予防接種を所管しますので、その２人の担当課長のラインを主にしっかり見ていくです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"となると、新型コロナウイルス感染症に関わる部署ということで、いわゆる日常的な保健所業務は品川区保健所が行うということでよろしいのか確認させていただきたいのと、あと、誰がどこからいらっしゃるのか。どこも大変ですけれども、専門性が高いといったらいいのでしょうか。大変な役割だと思うので、そこを最後に説明いただけたらと思います。","respondent":"佐藤企画調整課長、榎本総務部長","answer":"前段のご質問ですが委員ご指摘のとおり、日常的な保健所業務も当然ありますので、それに関しましては品川区保健所等が担うということです。基本的には、秋山選挙管理委員会事務局長が兼務するという形で考えていますので、秋山選挙管理委員会事務局長がこの担当部長を兼務するという発令を出しております。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"部長級の保健整備担当ですけれども、選挙管理委員会事務局の局長が兼務ということなのでしょうか。それだけ聞くと、体制強化というふうになかなか受け止められないのですけれども、感染症の対策になりますので、そういうドクターだったり保健師だったり様々な専門的な視点での判断というのが求められると思うのですけれども、もう少しご説明いただけますか。","respondent":"榎本総務部長","answer":"その感染症のほうの本体部分は品川区保健所長と保健予防課長が専念できるように、それ以外のこれから準備しなくてはいけない予防接種の関係ですとか、感染症対策に専念してもらうためにはほかのいろいろなことがこれから発生するので。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"今、体制としては分かりましたけれども、そのほか職員の人数とかは、どうなるのでしょうか。","respondent":"榎本総務部長","answer":"資料の左下に「保健体制整備担当（主査）制」とあるのですけれども、ここに新たに４名をつけまして、その４名が新型コロナウイルス予防接種担当の下について準備を進めていくという形です。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"その４名の方というのは、ほかからの異動というか、区全体の中でどのように考えてどこからどのように持ってきたのかとか、新しい人が入るのかとか教えてください。","respondent":"榎本総務部長","answer":"異動したのは１名、総括係長で、残りの３名は兼務という形になっていますけれども、実際の仕事はこのワクチン接種のほうの準備に入ってもらうということで兼務をかけるということで、以前給付金関係でやはり兼務を多くしたのですけれども、それと同じような形で。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"区全体でいろいろな仕事が大変だと思うのですけれども、兼務ということで、どれが重要でどれが重要でないということはないと思うので、その辺の今回の組織改正というのがどの辺までという一応目途があるのか、それとも基本的にこれでずっといって、また変える事情があったときに変えるという考え方なのか、その辺を教えていただけますか。","respondent":"佐藤企画調整課長","answer":"今回行われた組織改正のこの組織体制の期間ですが、ご案内のとおり、新型コロナの予防接種に関しましては、２月下旬の医療機関の従事者を含めて来年度以降も続けていきますので、短期間に確実に区民の方に予防接種を行うという使命もありますので。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問・要望","question":"そうすると、会派でこの前に緊急要望を出させていただいたのですけれども、これはあくまでも新型コロナウイルス感染症の予防接種であったり、今後の新型コロナウイルス感染症に関してこれから何かやっていこうという部署であって、何を言いたいかというと、会派の要望の中では、教育・医療とかいろいろな分野でコロナ対策の対応がばらばらに行われているわけではないですか。","respondent":"佐藤企画調整課長","answer":"本日ご説明している組織に関しましては新型コロナウイルス感染症の予防接種とＰＣＲ検査、相談業務等の総括的に進めていく部署でございまして、仮に委員ご指摘の全庁体制というのは新型コロナウイルス感染症対策本部会議というのが設置されておりますので。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"新型コロナウイルス予防接種担当が新設されましたけれども、これもちょっと聞いたのですが、第１回ワクチン会議というのが開かれたとお聞きしたのですけれども、その内容などは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"第２４回品川区世論調査","agenda":"第２４回品川区世論調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ、重点施策についてなのですけれども、一番多かった回答が「災害対策」ということですが、備考に説明があるように前回は「防災対策」でした。防災対策から災害対策に変えたその理由を伺いたいと思います。つまり、もうずっと今回で言う災害対策が上位にあるだけに、表現を変えたのはどうしてなのかと思いまして、ご説明いただきたいと思います。","respondent":"大澤広報広聴課長","answer":"委員ご指摘のとおり、災害対策と防災対策ですけれども、災害を防ぐということだけではなくて、災害が起きた際の対応も含めて表現したいということで、「災害」という表現に変更しております。","id":"exchange-009"},{"speaker":"新妻副委員長","kind":"質問","question":"ご説明ありがとうございました。１８歳以上からと対象が拡大したということで、この２,５００人が増えている数なのかということをお伺いしたいのと、回収率がそのことによって何か変化があったのかということもお知らせください。今頂いているものは概要版ですが、冊子の調査結果には、年齢別にどういう声が挙がっていたのかというのは出されるということでよろしいでしょうか。","respondent":"大澤広報広聴課長","answer":"品川区による訪問による回収率が大体７０％でございましたので、前回までの有効回答数１,０００を得るために対象人数を増やして、１,０００以上の有効回答を求めたものです。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"重点施策もそうなのですが、定住意向理由だと、真ん中辺に「治安が良いから」とありますが、６.３％から３４.５％と急激に上昇していたり、逆に４ページの重点施策については、「高齢者福祉」が２３.５％から１８.５％に減少していたりとか、その上の「子育て支援」も２５.０％から２０.３％というふうに要望にかなり大きな開きが出ているということは、これはあくまで調査なのですが。","respondent":"大澤広報広聴課長","answer":"恐らく訪問だとちょっと拒否感がある女性の方が、積極的にお答えいただけたのかという考えを持っていて、そういう意味では、少し女性が増えたことで調査結果に影響があるのではないかということは、今の時点で推測できるのかなと思います。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、なかなかこういう世論調査というのも難しいもので、どういう方が答えてくれるかによって相当変わってきてしまうということは、頭に入れておかなければ駄目だということですか。どうですか。","respondent":"大澤広報広聴課長","answer":"抽出の時点ではかなり細かく１５０地点に分けて、品川区の人口比を地点地点で小さな人口比で選んでいくのですが、回収率で男女比でこれだけ差が出ると、次回はその辺も含めて対象を選んでいかなければいけない部分もあるのかと、今回の調査のまだ感想ですけれども。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ご説明ありがとうございました。「品川区世論調査あらまし」の２ページの定住意向理由のところです。この「災害に強いから」というところが、２０１８年は１.４％、２０２０年が９.３％で結構伸びているのかと思っています。ちょっとお考えだけお聞きしたいと思います。","respondent":"大澤広報広聴課長","answer":"「品川区世論調査あらまし」には載せていないですけれども、質問の中で、災害の場合にどういう手段で情報を入手しているかという質問が入っておりますので、その辺、結果をまた細かく分析して、それに対応する形でやっていきたいと考えております。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"課長もおっしゃるとおり、いろいろ取り組んでいただいているのは分かっているので、これから本当に所管のほうと連携を取ってやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"今までのものも、より実態に、趣旨に合うような形で少しずつ表現を変えておられるようなのですけれども、「災害に強いから」は、どういう意味でこの言葉を選ばれたのか、ちょっとお話を伺いたいのと、今の質疑を含めて、これが今聞き取ろうとしていることにふさわしい文言なのか、課長だけではおっしゃりにくいところもあるかもしれませんけれども、ちょっとこの「災害に強いから」というのは。","respondent":"大澤広報広聴課長","answer":"所管とのヒアリングにこの調査を委託している会社の方にも入っていただいて、所管が知りたいことをかなり細かくヒアリングをし、質問項目とか選ぶ項目も考えていただき、ほかの区の世論調査なども手がけている会社ですので。","id":"exchange-015"}]},{"id":"topic-03","title":"新型コロナウイルス感染症緊急事態宣言下の対応","agenda":"新型コロナウイルス感染症緊急事態宣言下の対応","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"質問は６番の職員の応援派遣等ということですけれども、この間、感染の状況も踏まえながら体制を強化してきたところではありますが、今の時点で、例えば感染が広がっていない昨年と現状を比べて体制が、例えば人数で言えば昨年と今とどのぐらい変化があるのか、単純に伺いたいと思います。自宅待機の方への食糧支援も滞っていると伺いまして、保健所からの電話も本当に少ないともおっしゃっていました。","respondent":"黒田人事課長","answer":"運転ができる職員がいればその運転業務を、当然事故には気をつけてということはありますが、そういった対応をしていくというところで、先週の１月１８日から全庁的な応援体制を組みまして、当面３月末まではこの体制で。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"この体制でという話ではありましたが、先ほども言ったとおり、検査が必要だと判断されてもすぐ検査を受けられる状況ではない、自宅待機の方だと、家族３人自宅待機になりまして、かといっても買い物にも行けないし、品川区が当初やっていた食料支援も届かず、保健所からの連絡待ちという中で時間が過ぎていったということですけれども、現状、対応が追いついていないという認識に立っているのか、いやいや。","respondent":"黒田人事課長","answer":"人事課のほうで取りまとめをしておりますのは、いわゆる事務系の職員で、その職員ができるところについては一定程度、電話をかけるですとか聞き取った内容をシステムに入れるというところを応援しておりまして、医療関係の資源の調整については。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここは総務委員会なので、それを踏まえて発言したいと思いますけれども、皆さん超勤も含めてとても努力されていることに敬意を表します。ただ、今の現状の感染拡大の深刻さからすると、やはり支援が追いついていないと私は思っております。さらに職員の応援の実施・強化を求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"開催したときの感染防止策についても、区全体として、品川区としては、もちろん専門家の意見も聞きながらですけれども、こういうことで感染防止策は徹底しようというような方向性を決めているのか、その辺について伺いたいのですけれども。","respondent":"立川総務課長","answer":"いわゆるイベントの開催はどういった形で実施するかにつきましては、まずは所管の判断がございまして、その後、新型コロナウイルス対策本部会議等で全体調整を図るという流れになっております。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"まず最初に所管が開催したいということを判断して、それにあたって、こういう対策を取るということで新型コロナウイルス対策本部会議がそれならよかろうということで承認するのか、ちょっとその辺の流れについて、開催の可否にばらつきがあるということが気になるので、教えていただきたいと思います。","respondent":"立川総務課長","answer":"ばらつきの意味がよく分からないのですけれども、まず、高齢者作品展を開催した理由を簡単に申し上げますと、期間中のいわゆる来場者数見込みというのがかなり限られるというところがまず１点です。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"見込みというのも当てにならないわけで、大体これぐらいだろうと見込んでいたのが、思いのほかたくさん来るということもあるわけですから、そうしたらやはりそのときにはこういう形で入場制限をするようにとか、やはり区全体としての一定のルールというのは、これからまだこの感染の状況は続くので、感染防止を徹底しながら必要なことはやっていくということであれば。","respondent":"立川総務課長","answer":"基本的に先ほどもお話しさせていただきましたけれども、国や東京都のほうから、イベント等における開催のガイドライン等は具体的に示されておりますので、区といたしましてはそのガイドラインを重視しつつ、なるべくできることなら開催という方向で。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"先ほども品川区内の感染者のお話が出ましたが、実際、品川区の中でも自宅療養中、それからあとはホテル療養中も含めてそうなのですが、入院や療養先の調整中という方もかなりいらっしゃるのですか。もし分かれば教えてください。","respondent":"立川総務課長","answer":"ただいまのご質問ですが、本日厚生委員会で保健所の対応について詳しく説明をされているですので、いただきましたご意見につきましては、現状の所管のほうに伝えたいと思います。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問・要望","question":"分かりました。現に制約を受けて逆に病気をしたり、そしてご高齢者は身体能力が衰えたり、そして認知症が進んだり、小さいお子さんに対してもそうですが、いろいろ制約を受けたり、まして中学生などは、もう子どものときに必要なクラブ活動、運動に対してもこうやって制約を受けるということが果たしていいのかというのを、私は総務課でも企画調整課でもやはりきちんと考えてほしいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"湯澤委員","kind":"質問・要望","question":"１点お聞きしたいのですけれども、この区主催の主なイベントのところなのですけれども、一応ここに書かれているのが全てなのかどうか分からないのですが、ここに書かれている感じだと決行か中止かということだと思うのですが、所管の中で延期とか、そういう選択肢を考慮した上で中止になったのかというのを教えていただきたいと思います。","respondent":"立川総務課長","answer":"そのほかのイベントにつきましては、例えば、いわゆる各地区の防災広場の地元説明会がございまして、こちらにつきましては、戸越三丁目と西大井三丁目の２カ所で実施する予定でございましたけれども、状況を見ながら３月に延期ということで現在考えているところです。","id":"exchange-024"},{"speaker":"湯澤委員","kind":"意見","question":"延期もあるということで、例えば成人式といったものはもう会場開催中止というのが決まっていたので、なかなか延期というのは難しいものだと思うのですけれども、ここで今議論になりました高齢者の作品展というのが例えば開催されて、それでもやはり小中学生などもこの作品展のために努力して作品を作られた子どもたちもそうですし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。品川区内でもそういう方が多いのではないかと思います。もっと早く昨年のうちから会場予約をしていて、年が明けて緊急事態宣言が出されていなくても、やはりちょっと無理かなということでキャンセルされている方もいらっしゃると思うのですが、そういうどこでキャンセルしたか、１月８日からしか還付の対象にならないのか、その期間というのは設定があるのでしょうか。","respondent":"立川総務課長","answer":"対象者ですけれども、１月８日から３月３１日までの期間に施設を使用する者ということで、対象者を特定しています。それから、申請の取り下げの受付期間につきましては、さかのぼりまして１月４日から、現状のところ２月２６日としております。","id":"exchange-026"},{"speaker":"松澤委員","kind":"質問・要望","question":"ある程度年を取ってしまうと何かずっと同じような感じになってしまうのですけれども、人生の中で小学２年生というのは小学２年生のときしかないわけで、やはり所管の判断は仕方がないと思うのですけれども、何とかできるように対応してほしいという、改めて要望だけになってしまうのですが、何とか子どもたちのためになるべく延期し、そのようにやってほしいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-04","title":"令和２年職員の給与等に関する報告の概要","agenda":"令和２年職員の給与等に関する報告の概要","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"はじめに、報告については了解いたしました。私のほうからは、３ページ目の仕事と家庭の両立支援について伺いたいと思います。２３区の平均がもし分かれば教えていただきたいのと、国等の目標が幾らなのか、現状を伺いたいと思います。区としては、取得率が目標に達していない、つまりは低いその原因についてはどのようなお考えをお持ちなのか、併せて伺いたいと思います。","respondent":"黒田人事課長","answer":"個別の数値につきましては本日は手元にございませんので、正確な数値がお答えできないのですが、目標に届いていないということはご指摘のとおりでございまして、原因につきましては。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"数字については、後で教えていただけたらと思います。今回ここを取り上げたのは、ここをしっかり取り組んでいただきたいなという思いで指摘させていただいているのですけれども、今後の対応の方向性について、最後に伺いたいと思います。","respondent":"黒田人事課長","answer":"いわゆる男性の育児休業取得率というのを目標に掲げて取り組んでおりますので、公務員制度の中で制度としてあるところについては、先ほど言った環境を整備して取り組んでいただいて、意識の啓発というところについては。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろ想像しながら読んでみても、１の（６）の保育教諭等への対応について、「引き続き保育教諭等という新たな職のあり方を統一的に整理するための検討が必要」となっているのですけれども、これはどういうことを区に対して意見として特別区人事委員会がおっしゃっているのか、ちょっと私は読み取れないのですけれども、どのように受け止めておられるのか伺いたいと思います。","respondent":"黒田人事課長","answer":"ご質問のありましたテレワークのリモートのところについては、こちらの本編の報告書では、「テレワークの導入及び定着に向けた取組が進められていくものと考える」ということなので、進めるのはいわゆる任命権者の仕事なので。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。では、そちらの冊子のほうを拝見して、さらに分からないことがあったら、改めて別の機会で質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、前にもお話ししましたけれども、今現在、民間は本当に給与が年収で１５％、２０％の減、中には半額、中にはもうリストラされて働く場所のないというような状況を考えると、時期は時期として、実態調査の時期が現状とかけ離れているということはありますけれども、果たして職員の給与が、これだけ民間の現在の実態とかけ離れたこういう概要の報告書が出るというのはどうなのかなということだけは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-05","title":"会計事故防止のための対応策","agenda":"会計事故防止のための対応策","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この間報告があったことですけれども、二度と事故がないようによろしくお願いしたいと思います。伺いたいのは１点だけなのですけれども、決済方式を変更し、確実に二重送信を防ぐ対応ということですが、この対応というのは、例えば２３区の中でも品川区の独自のものなのか。","respondent":"中山会計管理者","answer":"会計管理者の会もありますので、そうした中で、今回の会計事故は共通の話題としているところですので、また品川区はこういう形で事故防止対策を取りましたということを共有していきたいと考えています。","id":"exchange-033"},{"speaker":"須貝委員","kind":"意見","question":"今回会計事故がこのように起きて、今回会計管理者の職にたまたま就いてこういう事件が起きた。ただ、他区がこの方法を採用して、ではうちの区でもとは、なかなか事情もあるしできないと思いますけれども、本当にいい制度・ルールを作っていただいて、私は逆にありがとうありますという感謝を申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"吉田委員","kind":"確認","question":"確認なのですけれども、この1)と2)はもう既に事故が起きてすぐ対応を取られたということで、今までご説明を伺う中では、もちろん本当にいつ何時そういうことが、いろいろな条件が重なるとこういうことが起きてしまったというのが今回なのかなと思っていて、その中では指定金融機関のあちら側の問題点というものもなかったわけではないような感じで受け止めているのですけれども、その辺も含めて。","respondent":"中山会計管理者","answer":"それを今回、この2)の支払通知書だけではなく、データの送信画面のハードコピーをつけるということで、指定金融機関側もはっきりとその事実を認識するということになりましたので、万が一システムエラーか何かがあったときに。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"たしか見た、見ていないというようなやり取りもあったかと思うのです。だから、このハードコピーによる照合というのがあれば、向こうがもし今回と同じような主張をしたとしても、いやいやこういうふうになっていますということを品川区としてちゃんと主張できるようなシステムになったという理解でよろしいのでしょうか。ちょっとその辺をお願いします。","respondent":"中山会計管理者","answer":"そのとおりです。この画面のコピーにつきましては、指定金融機関のほうでもしっかりとチェックをしていただいているところです。","id":"exchange-036"},{"speaker":"湯澤委員","kind":"質問","question":"この説明文の中で、「協議が整い口座払と随時払については」というふうに書いてあると思うのですけれども、この「ついては」という表現だと、ほかにも何かあるということなのでしょうか。","respondent":"中山会計管理者","answer":"やはり前日に送ったもののチェックが効かなかったというのが今回の事故になりますが、かといってそれをまた２日前にすると債権者の皆様に着金が遅れるということにもなりますので、今回この２つについては決済後方式に、変更することといたしました。","id":"exchange-037"},{"speaker":"湯澤委員","kind":"質問","question":"そういうことはあると思うのですけれども、人的なミスに関しては、いわゆる単純にミスをしてしまったというのと、お互い正しいと思っていて過誤があったという２種類があると思うのですけれども、お互いが正しいと思ってやっていたことがミスにつながるというか、こういう事故につながるということは、今回の防止策によって、会計管理室内でも。","respondent":"中山会計管理者","answer":"当然ながら職員にルールを徹底しましたのと、やはり支払通知書と決済をしたときの画面のコピーの照合というのが確実にチェックが効く体制ということになったので、まずここでほぼほぼ二重払いはないという形で考えております。","id":"exchange-038"},{"speaker":"湯澤委員","kind":"質問・要望","question":"職員の皆様も本当にご自身の責務を一生懸命果たされていると思いますし、今の説明で安心したところでありますので、過誤がないように、そして二度とこういった事故が起こらないように、これからも対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"開催すると言われていましたけれども、今回中止になりましたが、成人式を迎えられる方にとっては突然ですね。それに対する苦情とか、あと衣装その他着物ですけれども、それに対するキャンセル料に対する費用などの苦情とか、そういうこともあったのでしょうか。逆に、今回の対応は、よかったのではないかという様々なご意見があったと思うのですが、もしありましたら教えてください。","respondent":"立川総務課長","answer":"ご意見の主なものですが、まず、やはり会場でやってほしかったという意見が結構、約１０件程度ございまして、できれば延期をしてほしかったという意見もございました。","id":"exchange-040"},{"speaker":"新妻副委員長","kind":"質問","question":"記念品が毎年参加された方にはあるかと思います。その記念品の対応もどうされるのか、お伺いしたいと思います。","respondent":"立川総務課長","answer":"ちょうど今、いわゆるお詫びとあと記念品の配布につきまして、今、新成人の方に周知文書を用意して、今週中に配布する予定ですが、実は当日配布の記念品というのは来た方にだけ差し上げており、例年大体５０％ぐらいの方が参加されるので、全員分がないのです。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私も当日拝聴していたのです、拝聴させていただきました。実行委員の１２名とおっしゃいましたね。ステージに立っていて紹介されていました。そのときに、職員の方かどうか分からないのですけれども、結構拍手がぱらぱらと聞こえたのだけれども、職員の方は当日きゅりあんの会場にスタッフとして何名ぐらいいらっしゃったのですか。","respondent":"立川総務課長","answer":"やはり周知が行き届かなくて、結構な方がお見えになるかとは想定していたのですけれども、そうではなかったのですが、総務課の職員は全員出ておりまして、なおかつ副区長、教育長等も会場にいましたので、そういった状況で開催されたということです。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/307500?Template=document&Id=2188#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":28295,"voices":110}},{"id":"r03-20210120-14","meetingId":"r03-cm01","date":"2021年1月20日","dateIso":"2021-01-20","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"５号棟、６号棟について、以前、アスベストということでお話をいただいて、停滞をしているというような報告をいただいたのですけれども、これは１年半、前期のときにお話をいただいたのですが、その後何か多少の動きがあれば、些細なことでもいいので、情報がありましたらこの場でお伝えいただきたいと思います。","respondent":"佐藤企画調整課長","answer":"地域の方々にご不安を与えないように、丁寧に対応していきたいと考えております。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"西側道路拡幅・施設整備部分のことなのですけれども、行財政改革特別委員会に何度か陳情が出ていて、この西側の住宅地部分に知的障害を持ったお子さんを抱えている方で、その知的障害を持ったお子さんが飛び出したりして危険があるので、工事や何かは慎重にやってほしいと。あるいは話し合いがどのぐらい進んでいるのかということをお伺いしておきたいと思います。","respondent":"佐藤企画調整課長","answer":"こちらの施設に関しましてはまだ設計も進んでいないところですので、今後、原案をつくって、また丁寧に対応していきたいというところで、引き続き区としてはお話をしています。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"もちろん丁寧に対応していただかなければいけないのですけれども、ご納得されるような方向で話し合いが進んでいるのかどうなのか、もう少し具体的にお話を伺えればいいかと思うのですけれどもいかがでしょうか。","respondent":"佐藤企画調整課長","answer":"その方のご納得というところに関しましては、納得していただけるように引き続き丁寧な説明をしていくというところで、施設がどういう形でできていくのかというのがお示しできないと、なかなかそういう話にもならないと思いますので、まずは情報共有と。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の説明で、解体が２年ぐらいかかるということだったと思うのですけれども、そうすると、解体への着手というのはいつになるのでしょうか。令和３年、４年の２年間で、６号棟に関して解体が行われる、峰友寮と併せて３年、４年という形で行われるということになるのでしょうか。着手がいつなのかということについて、教えていただきたいと思います。","respondent":"佐藤企画調整課長","answer":"２点目のご質問の説明会はいつかというところも、区側からも強く申し入れていますが、いつぐらいになるかというのは、区民の方から我々に電話等で問合せがありますので聞いているところなのですけども、それに関しまして、国は。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、解体はとりあえず令和３年、４年のところで、おおよそ令和４年度中には終わると考えていいのでしょうか。","respondent":"佐藤企画調整課長","answer":"２点目のご質問の、工事をすぐ始められるようにですが、こちらは当然、私どものほうも、基本設計、実施設計のほうを国が解体している間に進めたいと考えておりますので、そういう形で進めていくところを内部で検討しているところです。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、区が示された、前にこの委員会に出された資料の中で、いろいろと防災備蓄倉庫は想定規模はこれくらいですとか、地域交流スペースはこれくらいですとか、保育園とか、それぞれの特養ですとか、施設の平米数というのが出ているのですけれども、多分、前に資料として出されていたとは思うのですが、区が購入する土地なのですけれども、都有地、峰友寮。","respondent":"佐藤企画調整課長","answer":"それ以外が、敷地、取得予定の広さに関しましては、旧峰友寮のところが約１,４００平米、その下、６号棟、ここが１,５６０平米を予定しております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"建物の設計というか、おおよそどんな建物かというのはいつ頃に分かるのかということも教えてください。","respondent":"佐藤企画調整課長","answer":"申し訳ございません。建物の実際の中身に関しましては、基本設計のほうをしてみてからということになりますので、そちらに関しましては、今後また予算の計上について議会のほうにお諮りすることになるかと考えています。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほどおくの委員から質疑があった、陳情に出されていたところなのですけれども、障害者の方の、前面道路拡張に伴う工事期間中およびその後の交通量が増えることで、命の危険にも直結するものだというような陳情だということで、前にこの委員会で審議されているのを読ませていただいたのですが。","respondent":"佐藤企画調整課長","answer":"ご質問は、国が行う解体の際の騒音の防止を区で行うかというご質問ですか。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"例えば、これは区が施設を建設していくわけなので、区の事業に協力してくださる家庭への対応ということで、例えば、従前居住者住宅とかをその間活用していただくとか、そういう対応というのも可能なのではないかと思ったのですけれども、そういうのというのはいかがなのでしょうか。","respondent":"佐藤木密整備推進課長","answer":"ただいま工事の際に従前居住者住宅に入れないかというご質問でしたので、私のほうからお答えしますが、区のほうの従前居住者住宅につきましては、密集住宅市街地整備促進事業ですとか。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"分かりました。とにかく何度も陳情が出されて、様々な訴えがされておりますので、ぜひどういうことができるのかということも含めて丁寧なご説明、対応をお願いしたいと思います。解体とか工事については、近隣の方にとってはかなり大変な思いをされることになると思いますので、そこの説明会というのもしっかりと丁寧にやっていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認をさせてください。地域の人は一日も早くと思っていらっしゃるのだから、もちろんそこは連絡を取り合っていると思うのです。解体の設計は終わりましたかとか、終わったらすぐに解体してくださいという連絡は取り合っていると思うのだけれども、そこだけ確認をさせてください。","respondent":"佐藤企画調整課長","answer":"今後も引き続き丁寧に対応してまいります。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"ご説明ありがとうございました。それから、３ページ目の、社会教育性を追求した水族館なのだというところの、社会教育施設ということで、何となく生き物のことをしっかりと勉強するということは分かるのですけれども、もう少し詳細にというか、具体性を持って言うとどういうことが望まれているのかということを教えていただきたいと思います。","respondent":"高梨公園課長","answer":"最初に、イルカショーへの批判が生物全体に及ぶといったところですが、こちらは今委員からもおっしゃっていただきましたけれども、やはりそういったイルカの展示、飼育に反対される方から見ると、そういったような、反対するようなことをやっている水族館は。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"一方で、やはり今おっしゃったとおり、しながわ水族館の社会教育施設としての特徴をクローズアップしていこうというのは、私も結構ありかと思っておりまして、特にこの検討委員会でのご意見の1)、2)、3)、4)と出ていますけれども、3)とか4)、人文科学的な要素あるいは東海道の宿場町・漁師町、もっと言えば、大森貝塚などがあるように。","respondent":"高梨公園課長","answer":"今いただいたご意見は、検討委員会、専門家会議で出たご意見の方向性に沿うものと感じておりますので、まだ今年度、検討が進んでおりますけれども、しっかりと検討を今年度に完結させて、来年度、またそれを踏まえて進むべき方向性について検討を進めていきたいと思います。","id":"exchange-013"},{"speaker":"塚本委員","kind":"意見","question":"これはご答弁は結構なのですが、一つの参考としてなのですけれども、できればしながわ水族館という名前をもう少し、しながわ水族館という名前自体は、しながわ水族館という言葉は残した上で、海沿いにあるとか、どこにあるのだとか、どういう水族館なのだというのが、アクアパーク品川との違いを明確にできるような何か一言。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"芹澤委員","kind":"質問・要望","question":"３ページ目の検討委員会でのご意見の中で、勝島の生物をとか、区民公園が一体となってというような議論があって、それはまさにそのとおりだと思うのですが、今、やはり公園と切り離されて使われているような認識になっていますので、ぜひ一体として考えていただきたいのですけれども、これの今後の方針というのは令和３年度から始まるということで。","respondent":"高梨公園課長","answer":"今、世界の批判はやはり鯨類、イルカやシャチ、クジラといったところがメインになっておりますが、ただ、専門家の方々に聞くと、この３０年で大分変わりましたので、これから１０年、２０年、３０年先を見れば。","id":"exchange-015"},{"speaker":"芹澤委員","kind":"質問","question":"最後に１点だけ、前にここも含めて、ネーミングライツをどうこうというような議論があったように思っているのですけれども、今、塚本委員からも名称の話があったと思うのですが、そういった財源をどこかで確保してというような議論もここに含まれているのでしょうか。教えてください。","respondent":"高梨公園課長","answer":"ネーミングのところ、しながわ水族館の名前については、会議では実は話題に上っておりまして、やはりアクアパーク品川と混同されにくいような、別の水族館だとしっかりと認識をしていただくような名前というものを検討するべきではないかというような話は。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、やはり前回、視察に伺ったときにも申し上げたのですけれども、本当に大人の知的好奇心を刺激するような社会教育施設としての役割を持った水族館であってほしいと思っています。","respondent":"高梨公園課長","answer":"しながわ水族館は、今年度、冒頭の委員会でもご説明をさせていただきましたが、入館者からいただく入館料と、あと、かかった経費の収支のバランスによって、その年、利益が出れば区への財源で、利益が出なければ区からの支出といった形でやらせていただいておりますが。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここに書いてある意味がよく分からないのだけれども、周辺にマンションが立ち並んでいることからという、周辺にマンションが並んでいるからエリア全体で考えたほうがいいと言っているこれが、しながわ水族館に求められるもので、これが前向きな話なのか、後ろ向きな話なのか。ぜひここら辺は……、歯切れが悪いのは、必ず私はこれを質問に入れる。そういうことをやるというのだけ言っておく。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"須貝副委員長","kind":"意見","question":"今、課長からもお話があったのですが、今までしながわ水族館、何もしないわけではなくて、様々なイベントとか、集客するためにどうしたらいいのだという取組みはすごくやられていた、そういう事業だと私は思うのです。そのうちどうしても大規模な改修工事は必要。毎年こうやって１億円、２億円の予算をかけてやるというのは、私は見直す時期なのかと思います。では、課長、お願いいたします。","respondent":"高梨公園課長","answer":"区といたしましては、本年度の会議での検討のご意見であったり、本日をはじめとした区議会からのご意見等をよく聞かせていただいて、来年度以降、進めていく方向性について検討していきたいと考えています。","id":"exchange-019"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、やめる方向ではないということで課長にお話しいただきましたので、それを前提に一つだけ伺いたいと思うのですけれども、ＹｏｕＴｕｂｅｒなるものが子どもたちの憧れの職業、最近どうなっているか分かりませんけれども、数年前は憧れの職業ということで、それによって巨万の富を得たＹｏｕＴｕｂｅｒもいるということなので、そこの中で水族館の運営をすることにおいて。","respondent":"高梨公園課長","answer":"ＹｏｕＴｕｂｅとの連携というか、ＹｏｕＴｕｂｅの視聴者との関係ですが、まず、会議の中では、ＹｏｕＴｕｂｅの視聴者と来館者を併せてといったことについての議論はございませんが、広くＰＲであったり広報といったところで。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこのところで、また広告収入等々も、いろいろと付随する収入も考えられるので、そこのところ、検討方いただきたいとは思うのですけれども、それについて今後の見通し、あるいは今後の売上げというか、利用者を増やす上において、社会教育と、あるいはもう一つ、エンターテインメントという娯楽性を兼ねた部分の視聴ということを考えて運営をされるということについての感想。","respondent":"高梨公園課長","answer":"今までやっていない、検討もしていない内容でございましたので、しっかりと内容について確認をさせていただいて、これから時代が進むにつれて、ＳＮＳ、ＹｏｕＴｕｂｅをはじめとした、こういった媒体の活用というのは進んでいく方向であると考えておりますので。","id":"exchange-021"},{"speaker":"大沢委員","kind":"意見","question":"そこのところには、来館者の場合は、必ず日本に来る、あるいは品川に来るという一つの枠組みがあるわけでありますが、電波によるのであれば、地球規模で発信できるわけであります。その中でやはり注目もそこのところには付随して、ついてくる場合もある。その後、いろいろと先ほどお話しした付随した収入も考えられるわけでありますので、そこら辺の検討方をお願いできればと思います。ご答弁は要りません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"やはり公立館、区立水族館ということでできることというのもあるのかと思うのですが、例えばですけれども、生物の生態とか、そういったことを研究したり、あるいは飼育をしていく中で明らかになったこととかということがあると思うのですが、そういったことをやりつつ、その研究成果を展示していくということを行っていくというのが。","respondent":"高梨公園課長","answer":"１点目の、公立施設だからできる各種研究等についてなのですが、検討委員会の中では、港区になりますが、すぐ近く、海側にあります東京海洋大学の教授にもご参加をいただいておりまして、特にご意見をいただいているのですが。","id":"exchange-023"},{"speaker":"せお委員","kind":"質問","question":"少し細かいことになってしまうのですけれども、来館者の方たちは、ここ近年ですと、アクセス方法はどれが一番多いのかとかが分かりましたら教えてください。","respondent":"高梨公園課長","answer":"少し駅から離れてはいるものの、高速等からのアクセスがいいということで、車で来館されるお客様が多いという状況です。","id":"exchange-024"},{"speaker":"せお委員","kind":"質問","question":"子連れで一日いるとしたら、お昼ご飯も食べたいし、おやつも食べたいし、子どもが遊べるところということで、先ほどからほかの委員からもお話がありますけれども、やはり公園を含めて考えていただくのがすごくベストかと思っていまして、以前に、改修前ですけれども、しながわ水族館の北側のところに出店とかがあったと思うのですが、そういったものは改修されていて。","respondent":"高梨公園課長","answer":"今回の改修に合わせまして、仮設のようなスペースではなくて、レストランに隣接した建物を建てまして、すみません、まだ準備が整っていないので営業は始めていないのですが、そこの建物で、売店という形で軽食、飲み物等を買っていただいて。","id":"exchange-025"},{"speaker":"せお委員","kind":"質問・要望","question":"ぜひそこに少し力を入れていただいて、コロナ禍もありますし、例えば、品川区内の飲食店の方に来ていただいてキッチンカーとかを入れたり、そういったこととかも飲食店にも利益というか、いいですし、来ていただく方も喜んでいただけると思うので、そういったところもぜひ検討していただきたいと思っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/121451?Template=document&Id=6102#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":25481,"voices":85}},{"id":"r03-20210121-18","meetingId":"r03-cm01","date":"2021年1月21日","dateIso":"2021-01-21","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時００分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"ご説明ありがとうございました。２３区におけるアリーナの設置状況ということで、ご説明がありました。そうしたところを見たとき、施設の観客席のあり方というところは、自治体によっては、車いすが置ける場所が二、三席あるところは、この表で見ると、一、二か所ぐらいだったでしょうか。品川区の総合体育館や戸越体育館はどういう状況なのか、そこら辺を少し教えていただきたいです。","respondent":"中元スポーツ推進課長","answer":"恐らくほかの区におきましても、最初から設備的につくるのではなく、実際に設営するときにきちんとそういう場所を、入り口からの動線も含めて検討してつくっていくという形になるかと思います。","id":"exchange-001"},{"speaker":"こんの委員","kind":"質問","question":"今のご説明で、そういう体制をとられているのだということが分かりました。その場に行って臨場感、生で見る、これは健常者と同じように楽しめる環境ということも、あってもいいのではないかと思うのですが、そういう点ではどのようにお考えでしょうか。","respondent":"中元スポーツ推進課長","answer":"今後、改修などのタイミングで、そのようなご要望がありましたら、検討して前向きに考えていきたいところです。","id":"exchange-002"},{"speaker":"こんの委員","kind":"質問・要望","question":"スポーツをやるきっかけというのは、見たり、聞いたり、触れたりというところからかなと思うと、そうした環境も整えていけるといいと思いました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"つる委員","kind":"質問","question":"車いすを利用されている方だからここだという、それは逆に固定的な、排斥というのでしょうか、配置とか排斥になってしまうというのも、一方で障害の有無に関わらずというふうになったときは、いや、私は上から観戦、観覧したいのだという選択の余地がなくなってしまうわけですよね。身体的な機能の低下で車いすを使うという方もいらっしゃるでしょう。","respondent":"中元スポーツ推進課長","answer":"施設の、今後のバリアフリー視点での改修、改善の考え方ですが、こちらの総合体育館、戸越体育館とも、必要に応じてそういうところは今後きちんと合理的配慮の中で考えていかなくてはいけないところだと認識しております。","id":"exchange-004"},{"speaker":"つる委員","kind":"質問・要望","question":"それから施設運営というところでは、客席をどう確保するか、収益とかも考えていろいろ配席はされていくのだと思いますけれども、やはりまさに合理的配慮に基づいた、今ご答弁があったような、フレキシビリティな席の設えというのは絶対必要だと思いますので、これは強く要望しておきたいと思います。","respondent":"中元スポーツ推進課長","answer":"委員おっしゃるように、そういうお声がないという状況でも、やはり先を見てきちんとそういう対応を今後心がけていきたいと思います。その際に一つ課題となるのが、やはり駐車場の存在かなと思ってあります。","id":"exchange-005"},{"speaker":"つる委員","kind":"提案","question":"バランスがよくなければ、バランスをよくすることがいいと思います。そうしたこともやっているわけです。これは再三、ハード面の土木関係の部署にも活用というところで提案をしているわけですけれど。それが、先ほどこんの委員も言った、私もやってみようという背中を押す、大きな材料の一つになるのではないのかと思いますので、ぜひそこは公共の担い手としてお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"提案","question":"自民党として、以前から品川区にアリーナを要望していました。それは、運動するだけでなく見ることを中心とした形、区民がスポーツに接するということで、品川区文化芸術・スポーツのまちづくり条例が平成２０年から施行されていますけれど、このときも前年あたりから、随分自民党の中でも検討して、議会からの提案をさせていただいた条例の一つです。","respondent":"中元スポーツ推進課長","answer":"今すぐにどうという計画は特にないのですが、ただスポーツ推進計画は、現在最終面に来ているのですが、その中でも将来的に、そのようなスポーツを見ることができるようなところを検討していきたいというようなことは少し書かせていただいているのですが、何しろやはり土地が。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これから、敷地的にも多少の動きが出てくるのではないかと思っていますので、建築ですとか運営に関しては、区が独自でやることだけに限らず、いろいろな費用のやり方もあると思いますので、その辺も踏まえた上でご検討をお願いしたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"安藤委員","kind":"提案","question":"そういうことが必要だと思います。２番目としては、条件として時間とゆとりなのですね。区民が気軽にスポーツできる場所の増設と、時間とゆとりをつくるという、この２点を提案させていただきましたけれど、この点について、区の考えを伺わせていただきたいと思います。これは質問です。品川区で今、これらの現状というのはどうなっているのか、１点伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"２点目の、時間とゆとり、現役の方も取り組める社会の実現というところでは、国のほうのスポーツ推進計画でもやはり、なかなか働いている方、子育て世代の方は、スポーツに取り組む時間が難しいというところがあります。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"ですから、場所の点では努力はされているのでしょうけれど、やはり今、品川区民が直面しているのは、スポーツをする条件が、場所という点でも時間という点でも整っていないということだと思います。課題がここにあるわけですから。意見を述べします。先ほど、現状はどうなっていますかという質問もさせていただいたので、ぜひそちらについてもお聞かせいただければと思います。","respondent":"中元スポーツ推進課長","answer":"そのような、まさに身近なところで区民の方が、健常者の方も一緒にまず取り組んでいくというところを地道にやっているところです。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそういう、人材の育成なども含めて、障害者の方々のスポーツ環境の整備をできるところから、身近な自治体として充実していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"ごめんなさい、私が把握している限り、２０１９年の行財政改革特別委員会の資料の中で、新庁舎の機能検討の中で「アリーナ」という文言があるぐらいで、ほかにアリーナの話は出てこなかったと思うのですけれど、アリーナ新設を進めるための、今回のこの議論なのですか。新設が予定されているのかどうかと併せて伺いたいのですけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"行政に聞く話ではなくて、今回委員会を開催するにあたって、各会派からいろいろな要望を出していただいて、この１年間はこういうことを検討していこうということで、今日は「アリーナ・障害者スポーツ施設に関すること」というのを議会マターでやっていることですので、行政がどうこうという話では、まず全くない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"田中委員","kind":"確認","question":"アリーナの新設やそういう計画はないということで、今、確認をしました。ないのですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"田中委員","kind":"確認","question":"今回のオリンピック・パラリンピック推進特別委員会の中で、具体的なものが進んでいくということではないということで、確認をしたかったのです。そこら辺のアリーナの想定というものが、どこまでされているのかということも伺いたかったのですけれど。今、オリンピック・パラリンピック推進特別委員会の中では、スポーツだけをする施設がアリーナとなっているのでしょうか。確認させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"渡部副委員長","kind":"質問","question":"誰かが何を決めるということでは全くありませんから。例えば障害者スポーツをどうしたいのか、区民の方々の声をどう届けたいのかということがあれば、それはお伺いすればいい。そこに前提も何もありませんから。もう純粋に、フラットな状態で議論いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問","question":"フラットな状態で伺いたいのですけれども。生活者ネットワークとしては、アリーナのイメージがスポーツ施設に限らずというところだったのですね。そこら辺の、今日・明日の命であったり、生活を考えている人たちがいる中でのバランスというのがとても重要だと思うのですけれど、そこら辺の考えというのを伺いたいと思いますし、皆さんとも議論ができたらと思うのですけれど、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"安藤委員","kind":"意見","question":"そうした中で何を優先すべきかという点では、先ほど言ったように大規模なアリーナを区が、いろいろ様々な課題もある中で、しかも区民が気軽に利用できないような料金形態にもなるでしょうし、施設規模にもなるでしょうし、そういったところを優先するのかという点でいうと、私は違うと思っていますので、先ほど言ったような、障害者スポーツの環境の充実。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"ここに今ある区内の総合体育館や戸越体育館の話の中で、磁気ループについてのお話があって、現状体育館にはついていないけれども改修の際にそのような声があったら検討するといったお話だったと思うのですけれど、ぜひ当事者の方たちの声を待つのではなく、聞きに行ってほしいということをいつも思っています。そういったことを求めたいのですが、いかがでしょうか。","respondent":"中元スポーツ推進課長","answer":"現在、スポーツ推進計画策定の中でも、障害者団体の方２名に入っていただいたりしておりますので、今後もちろんそのような方々のご意見等、障害者福祉課も交えながらご紹介いただいて、ご意見を伺えればと思っています。","id":"exchange-019"},{"speaker":"田中委員","kind":"意見","question":"もしこの先改修があるようでしたら、当事者の方たち、車いす利用の方たちや視覚障害の方たちが実際にそこを使ってみて、こういうところをこうしてほしいといった声を聞いてほしいと思うのですが、そこら辺もご答弁いただけたらと思います。","respondent":"中元スポーツ推進課長","answer":"今のところ改修の予定がないので、はっきりとはお答えが難しいのですが、もちろんそういう場合にはそのような方々のご意見も教えていただきながら、工夫してまいりたいと思ってあります。","id":"exchange-020"},{"speaker":"新妻委員","kind":"質問・要望","question":"今回、障害者スポーツということで、障害者スポーツに特化した施設が、東京都の２つと日本財団パラアリーナということでご紹介をいただきました。先ほど、これだけの人的にもまた設備的にも整えるのは、１つの区ではなかなか難しい、東京都との立て分けの中で、城南地域にも東京都の障害者スポーツ施設を区が求めているという話もありましたが、それは本当に理想であるなと思います。","respondent":"中元スポーツ推進課長","answer":"この都の施設を品川区民がどのくらい利用されているかというのは、申し訳ありません、今回は手持ちがございませんので回答ができないのですが、品川区の体育館で行われている障害者スポーツの事業といたしましては、教室等も定期的に、戸越体育館。","id":"exchange-021"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。大きな施設、スポーツ専用の施設でなくても、小さな会場でも、いろいろ使えるのかなと思いますので、障害者の方がスポーツをやりたいというところでは、またその推進もしていただきたいと思います。動線であったり、ドアの形状であったり、トイレであったり、障害のある方に特化するということは誰でもが、健常者にとっても使いやすい施設なのかなと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"楽しいで片づけてはいけないですけれど、まちの価値も上がっていくのかなというふうにも思います。あそこのホールが。それを活用していただくことによって人出があるわけですから、それによってまた地域も活性化していくのかなと考えます。そういった意味で、ぜひ今後、これも質問というより要望になってしまうかもしれないのですが、何かの折に、そういう観点でぜひ考えてほしいとは思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-02","title":"大井ふ頭中央海浜公園の利用休止","agenda":"大井ふ頭中央海浜公園の利用休止","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"工事に伴う利用中止ということですが、具体的にはどのような内容の工事を、どこにやるのかということだけ、教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"メインピッチに関しましては、大会を行うときの仮設の観客席を、ぐるりと周りに作るですとか、サブピッチも今は開放といいますか、ホッケー協会中心に利用しておりましたが、また追加で仮設の座席を設置します。","id":"exchange-024"},{"speaker":"新妻委員","kind":"確認","question":"１点だけ確認します。ここにドッグランがあります。場所としては大田スタジアムの近くのほうに、大田区の中にありますけれども、６月まではこのドッグランは使用可能で、７月以降、オリンピックの期間も含めて使えないというふうになるのでしょうか。お知らせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ちょうどサブピッチの手前側にあるところだと思います。委員ご指摘のとおり、６月まではドッグランはまだ使えます。７月に入りますと、こちらは使えなくなるというふうに聞いております。オリンピックの期間も使用できないというふうに、今のところは聞いております。","id":"exchange-025"}]},{"id":"topic-03","title":"東京２０２０オリンピック聖火リレー","agenda":"東京２０２０オリンピック聖火リレー","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"現状が分かればというところですけれども、１年延びたということで、１年前にここで走る予定だった方たちは、今回どうなるのか。再度選定されているのか、その辺、状況を教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"基本的には、去年と同じ方が第一候補といいますか、お願いするというふうに聞いております。その中で、走行の意思があるのか現在確認をとっていて、走りますよという方はそのまま走るというふうになっていると聞いておりますが、まだ現在調整中とは聞いております。","id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"せっかく決まった方なので、特段の何かがない限りは参加して、ここを走っていただければという思いですが。そうすると品川区としては、１年前に計画をしていた、コースだとか、運営上の流れだとかいうのは特段変わりなく、そのときの計画を今回も予定どおり進めるということで、変化はないという理解というか、どのような状況なのか、教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ただ、１年延びたということで、金額的な面ですとか、新型コロナの状況もありますし、簡素にするですとか、沿道の観客がたくさん来てしまいますと危険なこともありますので、そのあたりをどうするのかということで。","id":"exchange-027"},{"speaker":"こんの委員","kind":"意見","question":"現状をありがとうございました。これからどのように進めていくことになるのか、大変に悩ましい状況かと思いますけれども、ご担当の課長はじめ品川区の取り組みとしてご苦労をおかけしますが、どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"つる委員","kind":"確認","question":"本当にコロナ次第でというのが、もうずっとついて回ってしまうと思うのですけれど、去年のときも確認させていただいたかどうか忘れてしまったのですが、例えば、当然オリンピックの公式行事になってくるのですよね。それを教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そういうところで、今まさに東京都のほうとも話をしておりまして、東京都自体も決められない、組織委員会マターのものもありますし、いろいろな形を使って、区民の皆さんが走行しているところを実際に見なくても、テレビを通してでも、自分のまちが出ているのだ。","id":"exchange-029"},{"speaker":"つる委員","kind":"意見","question":"当然、放映権とかということもいろいろ出てきてしまうと思うのですけれど、やはり区民がしっかりと見られるような形の方向性で、これはもうオリンピックが開催できる、パラリンピックが開催できるという大前提ですけれど、その辺も並行してぜひ進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"西村委員","kind":"意見","question":"ちょうど暑さ対策とか、いろいろなお話をしていたことを今思い出したのですが、加えて感染症対策ということで、本当に大変なご準備になってくると思うのですが、引き続きよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"少し教えていただきたいのが、エコラ、このキャラクターは今回がデビューということでしょうか。すみません、勉強不足で、もともとこのキャラクターがあったのかどうか、教えていただきたいのと。そういうことも、ただ置くだけではなく少しコメントをつけて、お取りになる方が意識を持ってこれを読んでいただけるような、そういう一文も必要かなと思いますが、いかがでしょうか。","respondent":"提坂環境課長","answer":"イメージキャラクターのエコラですが、これは今回デビューということではございませんで、正式な年がいつだったかは申し上げかねるのですが、１０数年前につくったキャラクターで、ぬいぐるみとかも作って窓口とかに置かせていただいて。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"委託でということで、やり取りをして校正というお話でしたけれど、こういう温暖化問題というのは、かなり科学的な知見も必要というか、いろいろそういったことも踏まえて進めていく、対策を進めていく必要があると思うのですが、内容について監修とかをお願いしたりということも、やはり必要なのではないかと思うのですが、そういったことはあったのでしょうか。","respondent":"提坂環境課長","answer":"あくまでこれは委託ということなので、直接指示をするというとなかなか、委託の本来の目的から逸れてしまうので、なかなか難しい部分であるのですが。","id":"exchange-033"},{"speaker":"安藤委員","kind":"提案","question":"漫画でこういう問題を分かりやすくとか、その狙いは非常にいいと思うのですね。温暖化問題を考えるのに、それでいいのかなと。分かるのですよ。そういう子どもたちには、家庭内の努力だけに限定することなく、この問題の全体像ですとか、社会的背景ですとか、重要、核心点を、漫画で分かりやすく提示して考えてもらえるような資料こそ、挑戦すべきだったのではないかと思うのですけれど、いかがでしょうか。","respondent":"提坂環境課長","answer":"その辺は今後、学校等にアンケートをとらせていただいて、その結果などを踏まえて、来年すぐに改訂というのはなかなか難しいかもしれませんけれど、今年は４年生から９年生に配布させていただいたので、来年度以降、新たに４年生になる方に配らせていただくので。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこに向けてどういう動きが今あるのかというところで、再生可能エネルギーの普及の取り組み、あるいは脱石炭、火力、原発の動きなども多くの世界で取り組まれているわけですから、それを達成しなければ本当に大変なことになってしまうという問題なので、そういう記述もあってこそ、自分たちの身近で具体的な行動というのが温暖化を止めていくという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"こんの委員","kind":"質問・要望","question":"確認です。４年生から市民科でこの問題が入ってきているということで、４年生から配ると。１年生から３年生はなぜ配ってないのかという確認と、それから、こういうご自宅への啓発は非常に大事なことであると考えています。環境課として、より啓発をしていくために、私が今申し上げたような考え方は、どのように考えていらっしゃるのか、教えていただきたいと思います。","respondent":"提坂環境課長","answer":"ＩＣＴ教育の中では、動画を取り入れて自然災害の減少などを勉強するということも当然あると思うのですが、そういうところにも、今後環境課としてもご意見というか、参加できるものでしたら参加していきたいと思いますし、来年４月に環境学習交流施設がオープンする予定ですので。","id":"exchange-036"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうすると１年生から３年生までにお配りしているものは、今現在はないということですね。今後、そうしたお考えを持っていかれたらいいのではないかと、再度要望したいと思います。何かあればその点について。","respondent":"提坂環境課長","answer":"環境学習交流施設については、工事のほうについては着工したばかりです。運営内容については来年度、１年間かけて運営事業者候補者と練り上げていくところなので、その中で遠隔教育とかそういうものができるかどうか、その辺も検討してまいりたいと考えています。","id":"exchange-037"},{"speaker":"湯澤委員","kind":"提案","question":"ご説明ありがとうございました。大変読みやすく、こういったことなのかというのが、子どもたちにも理解できる内容かとは思うのですけれども、この感じですと、読んで終了してしまうという子も結構いるのではないかと思うので、これは提案なのですけれど、例えば各所でクイズ方式みたいなものにして、「こういうのはどうだと思う？これは提案ですけれど、何かご意見があればお願いします。","respondent":"提坂環境課長","answer":"そういうものも好評な部分がありましたので、今後こういう漫画の中でもクイズ方式とかを取り入れられないか、その辺も研究したいと考えています。","id":"exchange-038"},{"speaker":"湯澤委員","kind":"意見","question":"ぜひそういう、エコチャレンジというものがあるのであれば、エコチャレンジもまたこちらのほうで紹介していくとか、本当に子どもたちが楽しく学べる、そしてその子どもたちが今度家に帰ったとき、「お父さん、お母さん、こういうのって何か知っている？」ということで、家庭内でこういう啓発をしていくということが、大変すばらしい試みだと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"つる委員","kind":"提案","question":"今の湯澤委員の指摘を、まさに私も同じように思って見ていて。そのころの時代のあれかなと思って。だから、今ご提案もありましたけれど、ＱＲコードとか。今、湯澤委員のほうからもあったので、ぜひ、ホームページのほうのことも含めて、早目に対応できるのだったらやったほうがいいかなと思いますので、ぜひよろしくお願いしたいと思います。要望で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"私も、こうした漫画によって、子どもが積極的に読みたくなるような工夫、こうした取り組みというのは非常に有効かと考えております。ほかの委員からもお話がありましたけれども、今回の地球温暖化というテーマ以外にも、ＳＤＧｓとか電気自動車のこととか、今後はいろいろなことに応用ができるかなと思っていますので、ぜひ取り組みをお願いいたします。そのあたり、いかがお考えなのでしょうか。","respondent":"提坂環境課長","answer":"今後とも、地球温暖化防止ですとか、様々な環境問題に取り組んでく中で、このエコラを最大限活用して周知をしてまいりたいと思います。区の中でいろいろなキャラクターがあると思うのですけれど、その辺もまた環境課とともに整理をしていく必要があるのかなと考えています。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"よろしくお願いします。ではエコラは、この黄色のエコラで統一していくのか、それとも何かいろいろな、メスとか、きょうだいとか、そういうのを登場させていくのでしょうか。これからのことだと思うのですけれど。お聞かせください。","respondent":"提坂環境課長","answer":"エコラの色につきましては、私もこういう黄色というか茶色いような色というイメージで、ぬいぐるみのほうもこういう色をしているのですが、グリーンというのははっきり言って、私も認識がなかったです。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"すみません。何かこの話で少し長くなってしまいますが。しながわエコリンクミニガイドというのが、ホームページを検索するとＰＤＦで出ているのですけれど、そこにいろいろな色のエコラが登場しているので、これからのことだと思うのですけれど、ぜひ分かりやすく、エコラというのも伝えていっていただきたいと思っていますので、よろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"やはり先ほどもお話があったとおり、配布時の説明とか利用については、教育委員会ともっと検討していただきたいなということを思いました。配布して終わってしまっている状況もあるのかなと思うこともあるので、これを利用して環境について考えるといった、せっかく作成されているのですから、利用されたらいいなと思いますので、そこについてお知らせいただきたいです。","respondent":"提坂環境課長","answer":"こちらの漫画の内容については、もちろん事前に教育委員会のほうと内容の検討を行ったのですが、配布時の説明ですとか活用方法というところについては、確かに若干足りなかった部分があると思いますので、今後そういうことがないようにやってきたいと思います。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/363997?Template=document&Id=6588#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":38988,"voices":106}},{"id":"r03-20210122-10","meetingId":"r03-cm01","date":"2021年1月22日","dateIso":"2021-01-22","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"ごめんなさい、ちょっと、ちゃんと聞き取りにくかっただけで、ワクチンのことについて、どんなことを確認したいのか、もう一回ちょっと説明、よく分からなくて。","respondent":"渡辺議長","answer":"であればやはり、事務局、とにかく事務局一元化で問合せをする。そして情報を前回のように共有するという形が望ましいという意味で、中身というよりはとにかく問合せを議会事務局に一本化したいという趣旨です。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"確認","question":"小中学校の入学式・卒業式、それはもうそれで私はいいと思うのですけれども、ちょっと確認なのですが、学校自体はこれは、ちょっと最近、きのうもある町会長から聞かれたのですが、学校自体は基本的にもう町会長宛てには出しているみたいなのですけれども、これはやるのかな、やらないのかなとか、学校側が、何というのですか、どう判断するのかと、ちょうどこれも。","respondent":"渡辺議長","answer":"中でも議員への対応というのは非常に、先方が気を遣われるというふうに、僕らもそう思うので、であれば、議会意思として今日議運の場で諮れれば、お伝えして自粛されたほうが、現場がやりやすいのかなという思いです。その他の周辺状況はちょっと承知していないのですが。","id":"exchange-002","title":"町会・自治会支援"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/761909?Template=document&Id=5396#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":8329,"voices":44}},{"id":"r03-20210216-10","meetingId":"r03-cm02","date":"2021年2月16日","dateIso":"2021-02-16","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時２９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"石田（秀）委員長","kind":"提案","question":"私から１点、提案があります。それからもう１点、ここで先ほど言いましたように提案でありますが、これはこういうことが必ず出てくると思いますので、初日の補正予算、それから２日目の歳入、この審査に当たっても、５日目の保健衛生費と同様の対応をとらせていただきたいと思いますが、何かご意見ありますでしょうか。よろしいのであれば、その対応をとらせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"中塚委員","kind":"意見","question":"補正と歳入も同様にということで、趣旨は理解しました。人数的なところの目安はどうしましょうかということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]},{"id":"topic-02","title":"標準市議会会議規則の改正","agenda":"標準市議会会議規則の改正","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"明文化されるのは大変によろしいことだと思いますので、進めていただければと思うのですが、１点だけ確認で、ここに明文化されている疾病というのは病気ということで見ると、例えばけが、不慮の事故、そうした傷害的なところというのは、ここにはその文言は入っていませんが、その他やむを得ない事由という中に含まれるという理解でいいのか、それとも文言。","respondent":"米田区議会事務局長","answer":"お尋ねの件につきましては、広く疾病の概念には、そういう事故、けがとか負傷した場合等も含むということになっておりますので、疾病の中に含むという解釈が一般的ではあるようですけれども、やむを得ないという事由に照らしても。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"この欠席事由の明文化はぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"確認","question":"念のための確認なのですけれども、明文化ということで、例示があるということなのですが、賛成なのですけれども、現状でもこうした理由で欠席届を出すということは別に問題はないということですよね。それを明文化しただけであって、今それを却下するとか、そういうことではないということの確認だけさせてください。","respondent":"米田区議会事務局長","answer":"委員おっしゃるとおり、事故の中に明文化された内容が種々入っていたということが、逆にわかりづらかったというようなことであり、内容が変わるものではございません。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば一般質問の通告には印鑑は要らないのだけれども、討論の通告をするときには印鑑が必要であったり、あと、紹介議員になるときも、現状、皆さん印鑑を押されておりますけれども、ほとんどが直筆で書いているので、対応を統一できるところもあるのかなと思いますので、これを機に、区議会議員の押印についても、合理的なものは残していいと思うのですけれども、合理的でないものは、この際。","respondent":"米田区議会事務局長","answer":"お尋ねの件の１点ですけれども、別紙２の現行の品川区議会会議規則あるいは標準市議会会議規則の現行のものの第１３３条および第１３９条の第２項、請願を紹介する議員は、請願書の表紙に署名又は記名押印をしなければならないということで。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"確認","question":"さっき話したようにこれに賛成なのですが、確認で、かなり前に、この邦文というところなのですけれども、点字で請願というか陳情があったことが記憶にあります。この邦文という扱い、あのときどうしたか、確認だけ。","respondent":"米田区議会事務局長","answer":"当時の対応ですけれども、点字とともに訳文を提出いただいて、議会の審査に付したです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"確認","question":"ただ、委員会審査に当たって、それでは分からないから、事務局で文字に、点字は文字なのですけれども、我々が読める形に直すという対応をしたと思うのですけれども、確認したいのは、点字のみでも請願・陳情を提出することができるという、この確認だと前回思うのですけれども、よろしいでしょうか。","respondent":"米田区議会事務局長","answer":"解釈といたしましては、基本的にはやはり訳文をつけていただけるのであればつけていただいて、邦文のものをあわせてご提出いただいて、それで審査を行っていくというのが基本的なスタンスかと思います。","id":"exchange-008"},{"speaker":"中塚委員","kind":"確認","question":"邦文をつけていただくことはあってもいいと思うのですけれども、点字でも提出ができるということを基本だと、私はそう思っていますし、前回もそこはそう確認されていると思うのですが、点字でも提出することができるということでよろしいのか、改めて伺いたいと思います。","respondent":"米田区議会事務局長","answer":"過去の事例においては、やはり訳文はつけていただいているということではあるようなのですけれども、その辺のところ、規則に照らしてどうかということについては、改めて委員会の中でもご協議いただければと思います。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"確認","question":"関連で。邦文と書いてあるので、例えば英文で出してきた場合、ドイツ語で出してきた場合、どうするのですかという、それも同じように保障するのですかという話にもなってくるので、何でなっているかという趣旨を考えると、我々が審議できるようにということだと思うのです。我々がいいですよと言えば、いいのではないですか、この規則。というところではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"青年会議所ということなので、皆さんお仕事をされているという意味で、夕方５時からになるということなのか。やはり通常の執務時間内のほうが望ましいといえば望ましいので、そこだけご説明をお願いします。","respondent":"渡辺議長","answer":"今のご質問、ご指摘のとおりで、こちらの都合、やはり執務時間内等を提示しました。ただ、向こうで持ち帰って役員等で検討していただいても、やはりあまり早い時間だと参加率が非常に低くなってしまうと。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"コロナということもありますし、あと先方からの希望ということもありますけれども、議会運営委員会のメンバーを中心にということですが、多様な議会の実態をしっかりと反映していくという意味でも、希望も聞きながら、議運メンバー以外の会派の方々や無所属の方々の参加もぜひ考えていただきたいなという要望です。","respondent":"渡辺議長","answer":"一方で、やはり大会派の中にも希望される方が多々いるとも聞いているので、一番バランスのとれる形に近づけるように努力していきたいと思います。","id":"exchange-012"}]},{"id":"topic-04","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"東京都後期高齢者医療広域連合議会定例会、第１回定例会本会議が令和３年１月２８日に行われました。当日、一般質問が２名、案件としましては、同意案件として、監査委員の選任同意、現在の監査委員が引き続き決定、可決。議案の６件目として、陳情の審査がありました。後期高齢者の医療費窓口負担２割化の中止を求める意見書提出についての陳情ということで、これに関しては不採択という結果になっています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"全ての議案が可決といいますか、陳情は不採択ということですけれども、鈴木真澄委員はそれぞれの議案に対して賛成したのか反対したのか、そこを伺いたいのと、これまでも述べておりましたが、重過ぎる保険料の負担軽減へ、後期高齢者医療保険料の引き下げをぜひ広域連合議会の場で述べていただきたいと思っているのですけれども、その２点、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"提案","question":"その理由としましては、議会の中でもいろいろな資料が提出されておりますが、例えば令和４年度以降、団塊の世代が後期高齢者となり始めることで、後期高齢者支援金の急増が見込まれる中で、今の保険料、今回提案のあった形の保険料でいかないと、若い方への負担が大きくなるという大きな問題が出てきております。この辺から、案件に関しては賛成をしております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/761909?Template=document&Id=5398#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":18319,"voices":80}},{"id":"r03-20210219-3","meetingId":"r03-c-budget","date":"2021年2月19日","dateIso":"2021-02-19","committee":"予算特別委員会","time":"午後 ０時２６分～午後 ０時３３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/451143?Template=document&Id=1124#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":1980,"voices":18}},{"id":"r03-20210219-10","meetingId":"r03-cm02","date":"2021年2月19日","dateIso":"2021-02-19","committee":"議会運営委員会","time":"午前 ９時００分～午前 ９時０５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/761909?Template=document&Id=5400#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":1807,"voices":13}},{"id":"r03-20210222-6","meetingId":"r03-cm02","date":"2021年2月22日","dateIso":"2021-02-22","committee":"区民委員会","time":"午前１０時００分～午後 １時３４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件抜き出しています。","topics":[{"id":"topic-01","title":"町会・自治会活動活性化促進調査の実施状況","agenda":"町会・自治会活動活性化促進調査の実施状況","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"ご説明ありがとうございました。私から何点か質問します。資料裏面の設問の回答の２段目のところですが、まず組織運営上の課題なのですけれども、平成２６年度と令和２年度というのは、順位が変わらないという認識でよろしいのでしょうか。","respondent":"川島地域活動課長","answer":"順位は変わらないです。","id":"exchange-001"},{"speaker":"小芝委員","kind":"質問","question":"それで、３つ目の、区から依頼される仕事の増加というのは、先ほどご説明いただいたとおり、大幅に５０点以上減少しておりまして、区の認識としても、大体パーセンテージみたいなところで、どのぐらいの割合で、区が依頼している仕事が減ったという感覚をお持ちでしょうか。","respondent":"川島地域活動課長","answer":"パーセント、割合ではなかなか出しづらいものではありますが、我々は例えば警察署、消防署にも依頼の文書で、町会の負担を減らすようにお願いをしたり、それから区役所の中でも、庶務担当課長会という場がありますので。","id":"exchange-002"},{"speaker":"小芝委員","kind":"質問","question":"その一方で、まだまだ活動従事者の固定化が大幅に増えていて、従事者の固定化というのは恐らく高齢化にもつながっているのかなという印象を受けるのですけれども、一番下のコロナ禍の活動で、オンラインを活用した会議の実施３％というところで、３％の町会・自治会がＺｏｏｍ等を使ったオンライン会合を行われたと思うのですけれども、それらの町会・自治会に共通した特徴とか。","respondent":"川島地域活動課長","answer":"多分、こういった町会は、コロナ禍ではありますが、通常であればいろいろなイベントを活発に行っているようなところ、それから、役員の方でいろいろな方を引っ張っていくような方がいるというところが、特徴の一つにはなるのではないかと私どもは認識しております。","id":"exchange-003"},{"speaker":"小芝委員","kind":"質問・要望","question":"オンラインに精通している方もいれば、そもそもパソコンもそうですし、スマートフォンもなかなかお持ちでない方もいらっしゃいます。そういった方々が集まる町会というのもあるので、大変これから課題になってくるのではないかと思いますので、その辺も含めて、ぜひ地域のオンライン化を進めていただきたいというのを意見としまして、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"裏面の組織運営上の課題で、３項目ある中の真ん中、活動従事者の固定化というところで、そもそもこれはどういうことか、改めてお聞きします。","respondent":"川島地域活動課長","answer":"こちらは町会長、それから町会の活動をされている役員の方が、なかなか代わりがいないということで、同じ方がずっと務めているところですとか、そういった状況を指すものだと認識しています。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"最初の説明のときに課長から、悪化しているみたいな説明があったのですけれども、固定化してしまうと、区と行政としては悪化しているという判断になるのでしょうか。","respondent":"川島地域活動課長","answer":"すみません、私の説明が分かりにくくて申し訳ございません。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"品川区に住んでいたら必ず町会に入らなくてはいけないのだとか、町会というのは任意団体ですから、区の直接ではないわけですから、その辺も含めて数字で出ているわけですから、行政として、こういう方針でこのようにしていくというのは、この分析からだんだん出していかないといけないと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"川島地域活動課長","answer":"いろいろなことを、まず状況を把握しまして、区の支援策も考えますし、それから、何か運営の見本になるようなところの紹介もするようなところで準備をしています。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"アンケート内容を見ている限り、なぜ入らないのかというところは、なかなかこれだと出てこないというか、入っていない人に聞いてみないと、なかなか分からないところはあると思うのです。現実に動かれている方たちだけではなくて、入っていない方たちの理由というのも大事かと思うのですが、今回の調査でそういった入っていない人たちの調査というのは、何か考えられているのでしょうか。","respondent":"川島地域活動課長","answer":"残念ながら、今回の調査は町会長などへのアンケートになりますので、多分なかなか理由というのは、直接の生のところは出てこないとは思うのですが、今回、世論調査のほうではアンケートをしておりまして、その中にも幾つか入らない理由というのが挙げられていたかと思いますので。","id":"exchange-008"},{"speaker":"松本委員","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"大倉委員","kind":"意見","question":"アンケートの回答数なのですけれども、２０１町会・自治会中で１７１町会・自治会ということで、１００％を目指すというのは、多分、町会名も分かっていますし、町会長名も分かっているところでは、１００％を目指すということが、町会の今ある課題を全部把握できるようなやり方というのもあるのかなと、聞いていて思ったので、勧奨といいますか、アンケートを取るに当たって。","respondent":"川島地域活動課長","answer":"回答数が、８５％の回答だったです。こちらは未回答の部分が、ほとんどが自治会のところが多かったという形になります。地域特性という形にもなるとは思うのですが、なかなかその辺で回答が難しかったと分析しています。","id":"exchange-010"},{"speaker":"大倉委員","kind":"質問","question":"自治会の方だとなかなかお答えいただくのが難しいというのも、ある種、課題というか、要は自治会の活動がどういうことでうまくいっているか、いっていないかというのが、自治会がそれだけ答えが出ないというのは、活動がそもそもないのかどうかも含めて、何か拾えるヒントになるのかなと、今お話を伺っていて思ったので、ここのところをご努力いただいて、町会の活動を応援していただこうと思って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問","question":"は前提の部分なのですけれども、こちらのアンケート調査を実施するに当たっての予算が６６０万円ということで、こちらの６６０万円の予算の内訳であるとか、あとは、調査をした母体というのが民間の調査会社などの業務委託等であるのか、まずそこをお伺いします。","respondent":"川島地域活動課長","answer":"こちらの調査費の金額は、ほぼ調査委託先、ダイナックス都市環境研究所というところへの業務委託という形になっております。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問","question":"そちらの調査会社の選定理由、選定方法を教えてください。","respondent":"川島地域活動課長","answer":"簡易型プロポーザルという形で提案をいただきまして、その業者を選定したという経緯です。","id":"exchange-013"},{"speaker":"くにば委員","kind":"質問","question":"ほかに何社ほど、そちらはプロポーザルに参加なさいましたでしょうか。","respondent":"川島地域活動課長","answer":"私の記憶ベースですが、業者の申込みが３社ほどございまして、実際にご提案いただいたのは２社だったということで、その２社の中から提案を聴きまして選定して、こちらに決定させていただいたという経緯です。","id":"exchange-014"},{"speaker":"くにば委員","kind":"質問","question":"そちらの業者は基本的には、こちらのアンケート等の作成に関しては、課のほうで作っていらっしゃると思うのですけれども、そのアンケートを実際に配布であるとか、取りまとめであるとか、アンケート結果をレポートにまとめるであるとか、そういったアウトラインの部分、あとはヒアリングの座組であるとか、連絡であるとか、どこまでをこの６６０万円の中でやっていらっしゃるのでしょうか。","respondent":"川島地域活動課長","answer":"こちらの業務委託の中では、打合せ、資料作成と、それからアンケートの項目の作成・入力・集計・分析、それからヒアリング調査につきましても、内容の検討ですとか、お声がけの対象の選定とかまとめ、報告書のまとめも含めて、委託の内容に入っているものです。","id":"exchange-015"},{"speaker":"くにば委員","kind":"質問","question":"この調査会社に関しては、前回平成２６年度と同じ業者なのかどうかという部分と、同じ業者なのであれば、今回も設問の４４項目に関しては、コロナ禍の活動以外に関しては、あと、条例施行後の状況に関しても今回からだと思うのですけれども、基本的には前回からの引き続きの項目であって、そちらに関しては今のご答弁のとおり、こちらの会社が項目を考えたということで、地域活動課では項目を精査して。","respondent":"川島地域活動課長","answer":"こちらの業者につきましては、前回の平成２６年度のアンケートも実施したところになります。それから、アンケートの項目、それから内容につきましては、私ども地域活動課で中心になって考えたものを実施したものです。","id":"exchange-016"},{"speaker":"くにば委員","kind":"質問","question":"こちらのアンケート結果なのですけれども、これ自体を分かりやすく公表するということ、あとはそれぞれの自治会・町会に関して、恐らくアンケート結果のほうは全て冊子等で、全てのアンケートに参加いただいたところも、いただいていないところにも、結果をお送りしているとは思いますけれども、それはお送りしているかどうかという点と、そちらの結果の公表に関して、あとは情報の共有に関しては。","respondent":"川島地域活動課長","answer":"こちらはアンケートの結果、それからまとめの部分も併せて、冊子を作って、全町会・自治会にお配りするような形で準備をしております。","id":"exchange-017"},{"speaker":"くにば委員","kind":"質問","question":"前回は公表でなくて、今おっしゃった形、冊子でお送りして情報共有はしていなかったのでしょうか。今回は準備しているということだったのですけれども、前回について伺いたいです。","respondent":"久保田地域振興部長","answer":"少なくとも町会からご参加いただいた会長に対しては、冊子にしたものを最終的に報告させていただいたということは、私どもでそこは確認しているのですけれども、全町会に配ったかどうかまでは確認できませんが、ホームページ等で公表はしていますので。","id":"exchange-018"},{"speaker":"くにば委員","kind":"質問","question":"今のアンケート結果を、平成２６年度分も今回の分も含めて、品川区のホームページの分かりやすい部分に掲示しておくというのは、一つ必要かなと思います。こちらの４４項目について、それぞれ自由記入欄というのは設けたのでしょうか。","respondent":"川島地域活動課長","answer":"自由記入欄を設けさせていただきまして、様々なご意見を書き加えていただいております。こちらがなかなか、まだまとまらないところではあります。","id":"exchange-019"},{"speaker":"くにば委員","kind":"質問","question":"そちらの自由項目欄等に関しても、全てアンケートをいただいた後に電話でヒアリングしていらっしゃいますでしょうか。","respondent":"川島地域活動課長","answer":"電話での聞き取りという形では、してございません。","id":"exchange-020"},{"speaker":"くにば委員","kind":"質問","question":"それで、もう一度区のほうというか、調査の段階で電話することによって、向こうも課題がまとまってくると思いますし、さらに、自由項目で書いていただいた以上に細かいヒアリングもできると思うので、そこに関しては絶好の、お互いその課題に関して考える機会であるとか、もう少し踏み入った調査ができると思うので、アンケート調査をせっかくここまで予算をかけてするのであれば。","respondent":"川島地域活動課長","answer":"内容がこちらでももう少し聞いたほうがいいような部分がもしあったら、確認する部分もあるとは思うのですが、これは今後の進め方にも関わってくるところですので、しっかりこちらの自由記載欄も分析して、それから、何か対処が必要なものであれば。","id":"exchange-021"},{"speaker":"くにば委員","kind":"質問","question":"そちらが１点と、こちらは中間報告書というのは取りまとめられないのでしょうか。","respondent":"川島地域活動課長","answer":"中間まとめにつきましては、公共用という形ではなくて、取りまとめて冊子で提出させるような形になっておりますので、そちらは作っていただくということになっております。","id":"exchange-022"},{"speaker":"くにば委員","kind":"質問","question":"そちらに関しては、区民委員会だけでも共有はできないのでしょうか。もちろん、アンケート結果だけになってしまうと、我々でも年に１回見るだけで、もろもろの施策の検討をするに当たっての情報にもなりますし、できれば中間報告という形の把握を我々もしたほうが、様々な視点から情報を見られると思うので、あったほうがよろしいかなと思うのですけれども、いかがでしょうか。","respondent":"川島地域活動課長","answer":"こちらは、私どもも年に数回、町会長会議に出席させていただきまして、補助制度の説明ですとか、それから、いろいろなお困り事もございましたら、お話を聴く機会はありますので、今まで以上に丁寧にやっていきたいと考えています。","id":"exchange-023"},{"speaker":"くにば委員","kind":"質問","question":"４番目のカテゴリーごとのグループヒアリングについて伺いたいのですけれども、今回既に実施なさった女性会長の町会・自治会に関して、様々な意見が出たということ、ご好評だったということなのですけれども、こちらに関して、かいつまんでどういった内容が具体的なヒアリング調査として出てきたのかという部分と、女性会長に対してヒアリングをしたという。","respondent":"川島地域活動課長","answer":"こちらは、２０１町会・自治会のうちで１８、女性会長のところがあるということからも分かるとおり、なかなか活動していく上では、女性の会長も大変なところがあるだろうということが、まず一つ。","id":"exchange-024"},{"speaker":"くにば委員","kind":"意見","question":"今のご答弁の中でもあったように、女性ならではの、例えば子育ての環境とか、時間に対する融通であるとか、あと、話が長いかどうかという部分は性差がどれぐらいあるのか分からないのですけれども、実際に女性会長になるのはということで、有意な回答があったのだと思いますので、女性会長に関して、なぜ性差を設けて意見を聴くのかなという部分が、ちょっと気になった部分でした。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問","question":"オンラインなどは諦めてしまうというところがほとんどで、だからオンライン会議の実施も３％ということですけれども、とはいえ、今ある現状の中で、コロナの下で、またコロナが終わっても、こういうコロナ同様の形のものがまた来た場合の活動というのも、コロナを経験したからこそ出てくるのかなと思うのですけれども、そうしたところは、アンケートで自由記入欄もあったということですけれども。","respondent":"川島地域活動課長","answer":"文献調査と、地域センター職員に対するヒアリング調査ということで、こちらは６月から９月ぐらいまでにかけて実施したものです。それから、アンケートの記載事項のまとめということです。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"コロナのところを、こうした長期の活動休止の下でも、新規加入の促進というのを進めていきたいし、入ってきてくれた方々にも何か返したいという思いがある中で、すごく悩まれているところなのだなと思いますので、ここは中心的に、今まさにコロナ禍というところで、なかなか話を聞き取るというのもできない状況かもしれないのですけれども、そこは丁寧にやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"つる副委員長","kind":"提案","question":"先ほど藤原委員のところと松本委員の質疑でも確認があったのですけれども、まず活動従事者の固定化については、課題がどこなのかとか、逆に言うと、課題となっていないところの活動ということが、令和４年度の課題解決に向けた提案とか支援拡充の検討の中にしっかりと盛り込まれて、各町会・自治会の方に提示されるという理解でいるのですけれども、これは先ほど松本委員との質疑の中でもありましたが。","respondent":"川島地域活動課長","answer":"どのような形で支援していくのかということ、それから、今も言っていただきましたが、地域センターの所長、地域センター職員によります地域のコーディネート機能というのを、引き続き頑張ってやっていく必要があると考えていますので、この結果をまとめて、それを踏まえまして。","id":"exchange-028"},{"speaker":"つる副委員長","kind":"提案","question":"リアルに人と接していっていただいている。だから、こういうコロナ禍の環境下におけるいろいろな課題が見えてきたところもありますし、逆にやれることも出てきていると思うので、令和４年の提案だとか支援拡充のところを、本当にやっていただきたいと。先ほどちらっと言いましたけれども、もっとコーディネート役を担っていただくことが非常に重要なのかなと。そこをどう解きほぐしてあげるか。","respondent":"川島地域活動課長","answer":"なかなか具体的に、こういう形でこれをやればというのがないのがつらいところではありますが、まちの方に寄り添いまして、しっかり、どういった形で支援ができるのかということは考えていきたいと考えています。","id":"exchange-029"}]},{"id":"topic-02","title":"品川区町会自治会連合会ホームページ新設支援の状況","agenda":"品川区町会自治会連合会ホームページ新設支援の状況","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"目的のところなのですけれども、２行目の後半の「独自の情報ツールを持たない町会・自治会が、情報を発信することのできる環境を整備する」というところで、情報ツールを持たない町会・自治会の役員が、直接このホームページで、町会・自治会の情報、イベント等を更新していくということなのでしょうか。どういう感じなのか教えていただけますか。","respondent":"川島地域活動課長","answer":"こちらは情報の提供依頼という形で出しまして、町会から紙媒体等で出していただいたものを、区がアップして更新していくというイメージでつくっていく予定です。","id":"exchange-030"},{"speaker":"小芝委員","kind":"質問","question":"そうすると、必ずしも町会・自治会のイベント全てが役所のほうに上がってくるわけでもないということもあるのですか。１００％の行事が区のほうに上がってくるわけではないということですか。","respondent":"川島地域活動課長","answer":"当然、漏れてしまうところは出てくると思います。こちらからも働きかけをするところはありますが、ぜひこれをお伝えしたい、こちらに掲載したいという話で出していただいたものが中心で掲載されていくです。","id":"exchange-031"},{"speaker":"小芝委員","kind":"意見","question":"先ほどの促進調査のお話と関連してくると思うのですが、町会の中枢で動かれている方々のＩＣＴスキルも伸ばしていただくように、ぜひその辺の後方支援もお願いいたしまして、終わらせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"松本委員","kind":"意見","question":"そうすると、強制はもちろんできないのですけれども、例えばやり方としては、一番大きいというか、情報公開というところでは、規約をきちんとアップするというのは、まず一つ、本来的にはあっていいのかなと思うのですけれども、それが難しいということであれば、例えば町会費は幾らですというところが書いてあれば、そこはみんなそれで、それが重要なのだなというのが分かりやすいと思うのですけれども。","respondent":"川島地域活動課長","answer":"今の委員のご指摘のところというのは、理想形に近い形だと思うのですが、今回の町会の紹介ページの中で、町会長の名前まで出すのか出さないのかとか、連絡先を載せるのか載せないのかというところも含めて、確認をした上で情報を入れておりますので。","id":"exchange-033"},{"speaker":"松本委員","kind":"質問・要望","question":"その中に、例えば会費という項目があると、自然に載せてもらえるという可能性もあるのではないかと思っています。難しいところは理解しますけれども、そういった工夫が結果的に加入促進につながっていくのかなと思いますので、これは要望としますけれども、そういった工夫も引き続きご検討いただければと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"確認","question":"ホームページの立ち上げということですけれども、独自の情報ツールを持たない町会・自治会がということですが、持っているところがどれぐらいあって、こういう形なのか。それと、情報ツールを持っている町会・自治会に、この連合会ホームページからリンクで飛んでいけるという形になっているのかというのを確認したいのですが。","respondent":"川島地域活動課長","answer":"独自のホームページをつくったところ、ホームページを持っているところは、今回の品川区の町会自治会連合会のホームページと相互リンクを貼らせていただく予定です。","id":"exchange-035"},{"speaker":"くにば委員","kind":"質問","question":"こちらの連合会ホームページに関して、今後の運営体制、あとは来年度以降のサポートに関しての予算、その他にも予算が出るのであれば、そちらの２点を伺いたいです。","respondent":"川島地域活動課長","answer":"今回、３か月分のサポートということで先ほど説明させていただきましたが、こちらは３万６,３００円の１２か月分ということで、年間のサポートをお願いするような形になってあります。","id":"exchange-036"},{"speaker":"くにば委員","kind":"質問","question":"ということは、これが１月から３月分ということで、残りの４月から１２月分も既に契約済みで、令和３年度の予算には計上済みということでよろしいのでしょうか。","respondent":"川島地域活動課長","answer":"新年度予算も予算要求済みという形になってあります。","id":"exchange-037"},{"speaker":"くにば委員","kind":"質問","question":"こちらがサポート費なのですけれども、これはコンテンツの更新料、更新作業が全て含まれるのでしょうか。町会自治会連合会のどなたかがこちらのページを更新しながら、それをサポートするという形なのか、コンテンツの更新も丸ごとやってくださるのか、いずれなのか教えてください。","respondent":"川島地域活動課長","answer":"こちらは丸ごとお願いするのではなくて、区でやるものを支援していただくという形の契約になってあります。","id":"exchange-038"},{"speaker":"くにば委員","kind":"質問","question":"町会・自治会の方はなさらないのでしょうか。","respondent":"川島地域活動課長","answer":"データの更新等の作業については、基本は区で行いまして、そちらの支援、それから、大規模な改修等は当然、業者にやっていただく予定です。","id":"exchange-039"},{"speaker":"くにば委員","kind":"質問・要望","question":"そういった部分に関しても、任意ではなく、こちらから、ぜひホームページへのリンクを貼ってくださいということでお願いして、どんどん被リンクを増やしていくべきだと思うのですけれども、それに関して、どこからアクセスを増やすのか、どういうところからリンクを貼っていただくのか、考えていらっしゃる施策がありましたら教えてください。","respondent":"川島地域活動課長","answer":"検索のターゲットのユーザーというところになると思うのですけれども、これがなかなか難しいところではありますが、今まで町会活動をしていなかった方、町会活動がどんなものかも分からないという方が、見て分かるような形にしていきたいと思ってあります。","id":"exchange-040"},{"speaker":"くにば委員","kind":"質問","question":"こちらは、例えば町会・自治会に関しての加入の案内のお知らせであるとか、そういった紙媒体にもスマートフォンのＱＲコードを貼って、ここの町会自治会連合会のホームページに誘導したらいいのではないかと思うのですけれども、そういった、区で町会・自治会に関してお知らせするためにＱＲコードを入れる、あとＵＲＬを入れる予定というのはいかがでしょうか。","respondent":"川島地域活動課長","answer":"たしか紙媒体のところにでも、入れられるところは入れていく方針でやっておりますので、それから、今回のホームページも各所に加入申込みのフォームに、ボタンを入れさせていただいたりという工夫もしておりますので、できるだけ最新の媒体が使える部分についてはそれを活かして。","id":"exchange-041"},{"speaker":"くにば委員","kind":"質問・要望","question":"現状ぱっと見る限りでは、ただのテキストの羅列、項目の紹介に見えるのですけれども、ここに自治会の特徴や活動内容などを確認できますという部分、これを見た限りでは分からないのですけれども、どれぐらいしっかりヒアリングをしたりとか、紙に記入していただいて、それを盛り込むとか、ページを魅力的にするという部分に関して、何かお考えがある部分があれば、聞かせていただきたいと思います。","respondent":"川島地域活動課長","answer":"今ご指摘のところ、町会からの情報につきましては、最初の紹介ページについてはテキストデータで、エクセルでデータを送ってきていただいておりまして、それをまとめて流し込むような形になりますので、字だけだと、なかなか取っつきにくいというのでしょうか。","id":"exchange-042"},{"speaker":"くにば委員","kind":"質問・要望","question":"最終的にそれぞれの紹介というページから、オリジナルのホームページにリンクを貼ると思うのですけれども、先ほどご答弁のありました４４ですか、前回いろいろと調べさせていただいたときに問合せしましたけれども、今、品川区の町会・自治会が自力でつくっているホームページというと、ホームページをつくっていらっしゃらないところがほとんどで、つくっているところでも。","respondent":"川島地域活動課長","answer":"細かな今のお話にあったようなところのつくりかどうかというのは、今は分からないところではありますが、できるだけ情報は、確かに流れていってしまわないような形になるというのが重要なところだと思いますので、これからどのように運営していくかというところで。","id":"exchange-043"},{"speaker":"くにば委員","kind":"質問","question":"こちらは４月から本格運用開始ということで、去年いろいろとお話を伺った中で、町会・自治会の情報発信の強化の部分で、やっとホームページが出来上がるという部分、大変楽しみにしておりますし、期待しております。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"つる副委員長","kind":"質問","question":"今、いろいろなところにホームページが見られる宣伝という話がありましたけれども、まずは、ホームページをつくって知っていただくということが目的のところに書いてあるのですけれども、どうやって見るのですか。誰も多分、反応はしないと思うのです。その辺のアプローチの仕方をどのように、マーケティング的な観点かもしれませんけれども、お持ちなのか、教えてください。","respondent":"川島地域活動課長","answer":"ページのつくり等も業者とよくよく相談した上で、色ですとか、視覚的な部分も含めて考えたつもりではあるのですけれども、多くの方に検索して見ていただけるようになるというところを、究極の目標とするところですので。","id":"exchange-045"},{"speaker":"つる副委員長","kind":"意見","question":"そういうことだと思うのです。もっと言うと、Ｚ世代です。ホームページとか、ＩＣＴとか、ＩＴとかいっても、１０代後半から２０代前半のＺ世代の方たちに、どう引っかかってもらうかということによって、その後ろの２０代、３０代、４０代、５０代、６０代、７０代の人たちに広がっていくというのです。そういう工夫のところを、ぜひお願いしたいと思います。","respondent":"川島地域活動課長","answer":"すみません、１点だけ。町会・自治会の加入は今、電子申請でできるような形になってありますので、ご案内します。","id":"exchange-046"}]},{"id":"topic-03","title":"令和２年国勢調査","agenda":"令和２年国勢調査","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"国勢調査をしてくださった方は、平均的に何日ぐらい国勢調査に関わってくれたのかと、その方に対する手数料、報酬は幾らなのか、１日幾らとか、時間で幾らとか、そういうので決めるのでしょうか、教えてください。それと、品川区が、厳密な数字は出ていないというけれども、これで見ると７７％ということです。","respondent":"川島地域活動課長","answer":"調査の回答というところの７割で、調査として有意な数になるのかというご質問だと思いますが、こちらはそのほか、調査員、職員が補記という形で聞き取り調査して、それから調査票を作るという報告のやり方もありますので、あくまでもこの話というのは。","id":"exchange-047"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、調査区が１つだと、複数だとというお話が出ましたけれども、調査区は大体１つの調査区で、平均でどのぐらいあるのですかということと、中間でこういう結果を出してくださっていますけれども、最後は１００％に近くなるように努力というので、何かの時点で、年内中に出ないかもしれないけれども、もう一回、最終的にはどのぐらいに回答状況がなったかということは。","respondent":"川島地域活動課長","answer":"こちらは例年というか、通常だと２月に速報値が出るというところですけれども、それが６月ということですので、そちらで回答率等、数字が出たところで報告をする予定です。それから、罰則の話ですが……。","id":"exchange-048"},{"speaker":"藤原委員","kind":"質問","question":"書いて、きちんと期間内に郵便ポストに入れたけれども、ただ、その反面、書きたくないのだという自由も認めてあげなくてはいけないのではないかなという思いがあるもので、こういう質問を毎回してしまうのですけれども、国のことですから、事務的なことは区がこういう形でやったとしても。でも、その考え方についてどう思われるか、ぜひ担当の課長としてお伺いしたいのです。","respondent":"川島地域活動課長","answer":"こちらの国勢調査も統計法に基づいて実施しているものでございまして、統計法にこういう記載があるということで、案内の中にも記載していますが、我々は、罰則があるから書きなさいということではなくて、お願いをして書いていただくというスタンスで調査を進めてまいりました。","id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回たしかコロナ禍で、配布が対面しなくていいということで、ポストインでいいですということで、配布をしてくださる調査員は、少し簡単になったなという思いがあったと思うのですけれども、回答のところで、今までは対面して説明などもしていたりしたのかもしれないですけれども、ポストインにしたことで回答率が下がっているとか、今の時点でそういう情報が分かったら教えていただきたいのですけれども。","respondent":"川島地域活動課長","answer":"正式な分母というのでしょうか、世帯数がまだ分からないので何とも言えませんが、前回と比べてネットの回答が伸びているという形で、郵送のほうはそんなに変わらないようですので、回答もしやすいというところもあったのかと分析しています。","id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、対面してお伝えするというのも大事だと思うのですけれども、ポストインでもそこまで変わりがないということであると、今後、説明は大事だと思うのですけれども、調査員の皆さんの負担を減らすというところでは、そういうのもありかなとなっていく状況なのですか。","respondent":"川島地域活動課長","answer":"今までもいろいろ段階を踏んで、封筒をお渡しするような形だったのが、今回はインターホン等で住んでいることが確認できれば、そのまま調査書類をお渡ししていいという形になりまして、一回こういった簡略化をした後、また厳しくするというのもなかなか難しいと思うので。","id":"exchange-051"},{"speaker":"くにば委員","kind":"意見","question":"こちらの回答率についてなのですけれども、東京都の平均７４.２％、品川区７７％というところで、これは全体の回答率のパーセンテージが東京都平均より高い分析、あとは、インターネットの回答が東京都平均４０.６％のところ、４６.８％ということで、こちらの６.２％高いというのは、統計上すごく有意な差だと思うのですけれども、そちらに関しての分析と見解を、まずお教えください。","respondent":"川島地域活動課長","answer":"現状の先ほど参考値として申し上げた４６.８％が、２３区でいいますと４位という形になって、かなり上位のほうに入っているところで、調査員にとっても省力化になりましたし、回答するほうにとっても簡単に済むという、郵便ですと封入して。","id":"exchange-052"},{"speaker":"くにば委員","kind":"質問","question":"今のご答弁で、東京都で４位のインターネット回答の率ということで、大変うれしく思います。そこの中で、なぜそうやって東京都で４位になるぐらい施策が成功したのか、これの施策がヒットして、インターネットの回答率がこれだけ上がったという部分の、何か手応えであるとか、ここがよかったのではないか、東京都で４位というのは物すごいことですから、これに関して必ず分析はしなければいけないと思います。","respondent":"川島地域活動課長","answer":"ＦＭしながわとインターＦＭでも情報発信をさせていただいたので、こういった今まで使っていない媒体を使ったことで、効果が表れたのではないかと考えています。","id":"exchange-053"},{"speaker":"くにば委員","kind":"質問・要望","question":"コロナ禍における国勢調査が回答率に及ぼした影響の傾向とか分析に関して、どのようになさっているのか。例えば、コロナ禍で在宅率が上昇したではないですか。在宅率が上昇したから訪問回数が、以前だったら１回、２回、３回ぐらい訪問しないと、ご在宅ではなかった部分が、再度の訪問の頻度が減ったとか、そういった報告等での分析が何かあれば伺いたいです。","respondent":"川島地域活動課長","answer":"今現在、直前まで調査票の審査ということで、そちらのほうに職員が忙殺されておりまして、２月下旬の東京都への第１次の要計表というものの提出をもって一段落してくるというところですので、その先の分析等の話というのは、これから大事なところですので。","id":"exchange-054"},{"speaker":"くにば委員","kind":"質問","question":"ではこれからということで、もう１点、コールセンターに関してです。コールセンターは９月１０日から１０月１６日まで開設されていましたけれども、こちらのコールセンターへのクレームについて伺いたいのですが、クレーム件数が前回と比べて増えたのか減ったのか、クレーム内容に変化があったのかどうか。例えば、コロナ禍なので、訪問しないでほしいという方々が一定数いらっしゃったと思います。","respondent":"川島地域活動課長","answer":"追加のＩＤの発行依頼ですとか、調査員の事務の不明点はどういうものなのかということですので、あまり強硬なクレームがあったという報告は受けておりませんので、淡々と分からない部分と、それから不明な点のお問合せがあったと認識しています。","id":"exchange-055"}]},{"id":"topic-04","title":"第１４号議案 品川区地域センターの設置に関する条例の一部を改正する条例、および(2)第１５号議案 品川区立区民集会所条例の一部を改正する条例","agenda":"第１４号議案 品川区地域センターの設置に関する条例の一部を改正する条例、および(2)第１５号議案 品川区立区民集会所条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほど定員数が全体ので説明されたのですけれども、今日の資料では、表の一番右に広さが１部屋ずつ書いてあるので、比較したいと思うので、現区民集会所の広さ、定員数も教えていただきたいと思います。","respondent":"川島地域活動課長","answer":"失礼いたしました。もう一度お伝えいたします。現在の広さ、区民集会所が３室合計で２７６.３m2、新しいところが２７０.７７m2という予定になっております。現行の区民集会所の第一集会室が１４３.７５m2、第二集会室が５０.０５m2、第三集会室が８２.５m2です。","id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、この周辺地域の町会長にも話を伺わせていただいたのですけれども、移転のことは結構前から聞いていた、そういえばそうだねということだったのですけれども、施設の新しくなるほうの内容は、まだほとんど説明されていないということだったので、ぜひ使いやすい設備にしてほしいという声を寄せていただきました。その辺はどう考えているでしょうか。","respondent":"川島地域活動課長","answer":"その後、２月の町会長会議で、荏原第一地区、荏原第二地区も含めて説明にお伺いする予定だったのですが、今、緊急事態宣言が発出されておりますので、しかるべきタイミングで、また説明のほうはお伺いできればと考えています。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"設備のほうは、町会長会議等でご説明ということでしたので、そこは緊急事態宣言が明けて、様子を見て、状況がよければ、ぜひやっていただきたいと思うのです。それで、駐輪場は地下にはならないですか。隣のビルは地下なのです。なので、新しく移転するところの駐輪場というのは、平設置なのか、地下なのか、そこを伺いたい。","respondent":"川島地域活動課長","answer":"駐輪場が約２０台分という形で、有料と聞いているのですけれども、地下か地上かという形ですが、分からないのですけれども、駐輪場は２０台分という形で配置されて、準備されているです。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"地下かどうかは分からないのですか。それと、現集会所は東急の２階でしたか、区分所有ということで、先ほど年間２４万９,９００円がかかっているということでしたけれども、どういう経緯で現第一区民集会所は区分所有という形になったのか、お聞かせください。","respondent":"川島地域活動課長","answer":"大分前の話にはなるのですが、もともと別のところに荏原第一出張所という形であったというところですけれども、昭和５４年に現住所、今のところの２階部分を、３億円余ということで聞いておりますが、買収して、荏原第一出張所として移転して、現在に至ると聞いてあります。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういう経緯で区分所有ということですけれども、建設委員会の資料ですが、この場所も武蔵小山のまちづくり方針というのですか、そういう計画を見ると、４棟目の開発ビルが建つ予定になっているので、そうすると、ここも移転した後に、跡地に何が入るのか、それで行く行くは開発に、またのまれるという形になってしまうと思うのですけれども、その跡地活用というのはどうなっているのか伺いたいと思います。","respondent":"川島地域活動課長","answer":"現行の荏原第一地域センターが移動した後、あちらは改修工事をしばらくした後に、男女共同参画センターの仮移転の場所と、それから、図書の取次サービスの移転先になるという予定と聞いてあります。失礼いたしました。両方とも暫定利用という形です。","id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これは年で言っていただいたのですが、それが毎年なわけですから、結構な額になってくると思うのですけれども、こうしたことも、ぜひ区民の皆さんにご説明いただいて、こういう計画は、新しくなって便利になるけれども、それ以上に開発ビルというのは税金がかかっていってしまうというところも説明が必要なのではないかと思うのですが、この辺の考えはいかがでしょうか。","respondent":"川島地域活動課長","answer":"当然、新しくて利便性のいいところに移ってくると、経費というのがかかる部分というのは出てくると思いますので、その辺はしっかり説明していきたいと考えております。","id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"利用料の部分に、そうしたかかる部分が反映されなくて、本当によかったとは思っているのですけれども、きれいになって便利になるにしても、まだまだ不足している区民の集会所だったり集う場というのを、なくさないようなまちづくりというのをすべきだと、改めて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"松本委員","kind":"質問","question":"今、駐輪場の話が出たのでお伺いしたいのですけれども、今の話だと、地下かどうかというのは分からないというところで、多分、地下の気もしなくもないのですけれども、問題はこの後の、有料という言葉が出たのではないかと思うのですが、今の荏原第一地域センターは多分、数は少ないですけれども、無料ではないかと思うのです。それは、無料だったものが有料になるということでいいのでしょうか。","respondent":"川島地域活動課長","answer":"多分、こちらは区役所の駐車場とかと同じで、地域センターに用のある方については１時間以内は無料になるとか、そういった扱いになると聞いているのですけれども、詳細の扱いについては、まだ詳しいところは分かっておりません。","id":"exchange-063"},{"speaker":"松本委員","kind":"質問・要望","question":"これは今、駅から５分、６分ぐらい離れたところに１か所あって、大体そこがいつも満杯になっていて、道まではみ出すような状況もあって、せっかく地域センターが移転するというタイミングであれば、所管はまたぐとはいえ、シェアサイクルの事業とも一応連携はしていただいて、実際には、これは民間の部分ですから難しいとは思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"大倉委員","kind":"質問・要望","question":"それが１点。先ほどのお話の中で、今ある現地域センターのほうの集会室とかというのは、先ほど暫定的に利用が、男女共同参画とかで使われるということなのですけれども、集会室もそういう意味では、そっちも使えないということなのか、そこの確認だけ。","respondent":"川島地域活動課長","answer":"こちらは区民集会所も併せて新しいところに移転するという形になりますので、そちらの跡地の使い方が変わってくるという形になります。","id":"exchange-065"},{"speaker":"大倉委員","kind":"意見","question":"全体も移って、そちらで基本的に使って、集会所というのはもうなくなるという理解で、分かりました。先ほどお伝えした駐輪場等の結果をぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"つる副委員長","kind":"質問・要望","question":"それと、先ほど石田ちひろ委員の質問の中であった年間の経費、駐車場代が１００万円とありましたが、これは地域センター所有の車両を置く駐車代という理解ですか。その確認と、あとは、駐輪場が２０台ということなのですが、あの建物だけで２０台なのですか、それとも地域センターの持分で２０台なのかというのと、車で来られる方の駐車場というのはあるのでしょうか、教えてください。","respondent":"川島地域活動課長","answer":"駐車場代という形で説明した部分につきましては、荏原第一地域センターの車の駐車場代という形になります。それから、駐輪場はもっと台数があるはずですけれども、地域センターの部分が２０台と割り当てられているという考え方です。","id":"exchange-067"},{"speaker":"つる副委員長","kind":"質問","question":"ほかの地域センターで区民の方とか、地域センターを利用される方用の駐車場というのは、設けてあるところと、反対に設けられていないところがあるかもしれない、設けられているところがあるのかなというのと、既に契約等が進んでいるので、今からの確保というのは難しいのかもしれないですけれども、例えば搬入とか、集会室とかを使うのに様々な備品等の搬入とかで使われる方もあろうかと思うのですけれども。","respondent":"川島地域活動課長","answer":"少しその辺は、どこまで交渉できるか分からないのですけれども、駐車場の余地のところを確認させていただければと思います。","id":"exchange-068"},{"speaker":"つる副委員長","kind":"質問・要望","question":"地域活動課の所管ではなくなってきてしまうのかもしれないですが、今後は周辺の整備というところで、他課としっかりと連携・協議等していただきたいこととしては、ちょうど角の位置というのでしょうか、交差点といいましょうか、丁字路といいましょうか、になるので、あそこは信号がない交差点となっていて、割と自転車の往来とか車の往来もそれなりに激しいところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、駐輪場も、もしこれが地下で有料だとすると、本当に使い勝手がマイナスになるという思いです。ですので、そこはぜひ、私も駐輪場は無料にしていただきたい、するべきだと思いますし、移転に関しては賛成ですけれども、こうしたまちづくり全体を見て、いかがなものかと。そして、区民の集会所を残してほしいと。そこに応えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/943539?Template=document&Id=2890#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":44788,"voices":183}}]);
